window.HANUL_DATA = {"source": "Mục lục Ngữ pháp - 6 Quyển THTH.xlsx", "sheet": "Tiếng Hàn Tổng Hợp", "items": [{"id": "E2", "book": "1", "lesson": "1.1", "topic": "소개", "vocabulary": "나라", "grammar": "N입니다", "note": "이다 : gắn vào sau danh từ, có nghĩa tương đương trong tiếng Việt là ‘là’, \n- Hình thức kính ngữ của ‘이다’ là ‘입니다’, thường dùng trong cân trần thuật. \n\n+ 화입니다. \n+ 학생입니다. \n+ 베트남 사람입니다. \n+ 뚜안입니다. \n+ 회사원입니다."}, {"id": "E3", "book": "1", "lesson": "1.1", "topic": "소개", "vocabulary": "직업", "grammar": "N입니까?", "note": "입니까 : là hình thức nghi vấn (hỏi) của 입니다, có nghĩa tương đương trong tiếng Việt là ‘là....phải không?’ \n\n+ 남 씨입니까? \n+ 학생입니까? \n+ 베트남 사람입니까? \n+ 디엠 씨입니까? \n+ 회사원입니까?"}, {"id": "E4", "book": "1", "lesson": "1.1", "topic": "소개", "vocabulary": "인사말", "grammar": "N(은/는)", "note": "Gắn vào sau danh từ để chỉ ra danh từ đó chính là chủ thể của hành động. \n+ 은 kết hợp với những danh từ có phụ âm cuối, \n+ 는 kết hợp với những danh từ không có phụ âm cuối. \nCó trường hợp ‘danh từ + 은/는’ được giản lược đi khi chủ thể đó đã được đề cập trước đó. \n\n+ 저는 남입니다.\n+ 제 이름은 남입니다. \n+ 남 씨는 학생입니까? 조민재 씨는 회사원입니다. \n+ 선생님은 한국 사람입니다."}, {"id": "E5", "book": "1", "lesson": "1.2", "topic": "학교", "vocabulary": "장소", "grammar": "여기, 거기, 저기", "note": "여기 là đại từ chỉ vị trí khi gần người nói . \n거기 là đại từ chỉ vị trí gần người nghe. \n저기 là đại từ chỉ vị trí xa người nói lẫn người nghe. \n\n+ 여기 / 거기 / 저기는 도서관입니다.  \n+ 여기 / 거기 / 저기는 은행입니다."}, {"id": "E6", "book": "1", "lesson": "1.2", "topic": "학교", "vocabulary": "학교 시설", "grammar": "이것, 그것, 저것", "note": "이것 là đại từ chỉ đồ vật gần người nói. \n그것 là đại từ chỉ đồ vật xa người nói và gần người nghe. \n저것 là đại từ chỉ đồ vật xa người nói và cũng xa người nghe. \n\n+ 이것 /그것 / 저것은 책입니다.  \n+ 이것 / 그것 / 저것은 사전입니다."}, {"id": "E7", "book": "1", "lesson": "1.2", "topic": "학교", "vocabulary": "교실 물건", "grammar": "N(이/가)", "note": "Là tiểu từ đứng sau danh từ làm chủ ngữ, \n+이 đi theo sau danh từ kết thúc bằng phụ âm và \n+가 đi theo sau danh từ kết thúc bằng nguyên âm. \nTiểu từ 이/가 thường được kết hợp với 있다 (có), 없다 (không có), mà dạng kính ngữ của 있다 và 없다 là 있습 니다 và 없습니다. \n\n+ 책이 있습니다.\n+ 시계가 있습니다."}, {"id": "E8", "book": "1", "lesson": "1.2", "topic": "학교", "vocabulary": "", "grammar": "Place에 + 있습니다", "note": "에 là tiểu từ chỉ vị trí của người hoặc vật. \n에 với nghĩa là 'ở' được dùng với 있습니다 hoặc 없습니다. \n\nA : 교실에 컴퓨터가 있습니까? \nB : 아니요, 없습니다."}, {"id": "E9", "book": "1", "lesson": "1.2", "topic": "학교", "vocabulary": "", "grammar": "N(이/가) + 아닙니다", "note": "아니다 : có nghĩa tương đương trong tiếng Việt là ‘không ..., không phải ...’. \n- Hình thức kính ngữ của ‘아니다’ là ‘아닙니다’. \n- Trước ‘아니다’ thường có ‘danh từ  + 이/가’ \n\nA:  이것은 사전입니까? \nB : 아니요, 사전이 아닙니다. 책입니다."}, {"id": "E10", "book": "1", "lesson": "1.3", "topic": "일상생활", "vocabulary": "동사", "grammar": "V/Aㅂ/습니다", "note": "- Là đuôi câu được gắn vào sau thân động từ hoặc tính từ thể hiện sự đề cao người nghe khi tường thuật lại một sự thật hay suy nghĩ của bản thân. \n- Đuôi câu này tạo cảm giác trang trọng và được dùng trong các tình huống mang tính nghi thức. \n+ Nếu thân từ kết thúc bằng nguyên âm thì kết hợp với dạng -ᄇ니다, \n+ còn thân từ kết thúc bằng phụ âm thì kết hợp với dạng -습니다. \n\n+ 유진 씨가 잡니다. \n+ 학생이 공부합니다. \n+ 가방이 작습니다."}, {"id": "E11", "book": "1", "lesson": "1.3", "topic": "일상생활", "vocabulary": "형용사", "grammar": "V/Aㅂ/습니까?", "note": "- Là đuôi kết thúc câu dạng nghi vấn của đuôi kết thúc câu trần thuật -ᄇ/습니다. \n+ Nếu thân từ kết thúc bằng nguyên âm thì kết hợp với dạng -ᄇ니까, \n+ còn thân từ kết thúc bằng phụ âm thì kết hợp với dạng -습니까. \n\nA : 지원 씨가 일합니까? \nB : 네, 지원 씨가 일합니다. \n\nA : 가방이 큽니까? \nB : 아니요, 가방이 작습니다."}, {"id": "E12", "book": "1", "lesson": "1.3", "topic": "일상생활", "vocabulary": "일상생활", "grammar": "N(을/를)", "note": "- Là tiểu từ được gắn vào sau danh từ để biểu thị danh từ đó là tân ngữ trong câu. \n+ Nếu danh từ kết thúc bằng phụ âm thì kết hợp với 을, \n+ còn danh từ kết thúc bằng nguyên âm thì kết hợp với 를. \n\n+ 지원 씨가 빵을 먹습니다. \n+ 학생이 책을 읽습니다. \n+ 준영 씨가 친구를 만납니다."}, {"id": "E13", "book": "1", "lesson": "1.3", "topic": "일상생활", "vocabulary": "의문대명사", "grammar": "Place에서", "note": "- Là tiểu từ được gắn vào sau danh từ để biểu thị địa điểm xảy ra một hành động nào đó. \n\n+ 흐엉 씨가 집에서 쉽니다. \n+ 수빈 씨가 은행에서 일합니다."}, {"id": "E14", "book": "1", "lesson": "1.4", "topic": "날짜와 요일", "vocabulary": "요일", "grammar": "한자어 수사", "note": "- Có hai loại số từ trong tiếng Hàn để biểu hiện số lượng. Đó là số từ Hán Hàn và số từ thuần Hàn. Số từ thường được đặt trước danh từ chỉ đơn vị và tùy theo từng danh từ đơn vị mà số từ được dùng là số từ Hán Hàn hay số từ thuần Hàn. \n- Khi nói về ngày, tháng, năm (년, 월, 일) và số điện thoại, số tầng nhà, số nhà (전화번호, 층, 호) thì số từ được dùng là số từ Hán Hàn. \n\n+ 오늘은 2월 15일입니다. \n+ 제 전화번호는 139-287-3195(번)입니다. \n\n(*) Kí hiệu \" - \" trong số điện thoại được đọc là [에] thay vì 의."}, {"id": "E15", "book": "1", "lesson": "1.4", "topic": "날짜와 요일", "vocabulary": "날짜", "grammar": "N와/과", "note": "Dùng để nối hai danh từ với nhau. \n+ 와 dùng để nối danh từ kết thúc bằng nguyên âm, \n+ 과 dùng để nối danh từ kết thúc bằng phụ âm. \n\n+ 교실에 책상과 의자가 있습니다.  \n+ 여기에 시계와 가방이 있습니다."}, {"id": "E16", "book": "1", "lesson": "1.4", "topic": "날짜와 요일", "vocabulary": "", "grammar": "Time에", "note": "- Dùng sau danh từ chỉ thời gian để chỉ thời gian xảy ra một hành động. \n(*) Đối với các từ chỉ thời gian như 언제 (bao giờ), 그저께  (hôm kia), 어제 (hôm qua), 오늘 (hôm nay), 내일 (ngày mai), 모레 (ngày kia) thì không dùng 에 kèm theo. \n\n+ 토요일에 영화를 봅니다. \n+  12월 10일에 생일 파티를 합니다."}, {"id": "E17", "book": "1", "lesson": "1.5", "topic": "하루 일과", "vocabulary": "시간", "grammar": "고유어 수사", "note": "- Số từ là từ dùng để đếm số hoặc biểu thị số lượng. \n- Trong tiếng Hàn, có hai loại số từ là số từ thuần Hàn và số từ Hán Hàn. \n\n(*) Với số lớn hơn 100, dùng số từ Hán Hàn\n\n(**) 하나, 둘,셋, 넷, 스물 : có danh từ chỉ đơn vị bổ nghĩa thì các chữ số này đổi thành 한, 두, 세, 네, 스무. \nVD : 교실에 남자가 한 명(두 명/세 명/네 명/스무 명) 있습니다. \n\n(*) 명 (người) là danh từ đơn vị dùng để đếm số lượng người, ngoài ra cũng có thể dùng 사람 thay cho 명 với cùng ý nghĩa"}, {"id": "E18", "book": "1", "lesson": "1.5", "topic": "하루 일과", "vocabulary": "일상 표현 동사", "grammar": "수 관형사", "note": "- Số từ bổ nghĩa cho danh từ đơn vị đứng sau gọi là \"định từ số\". \n- Trong tiếng Hàn, tùy vào danh từ đơn vị mà có thể dùng số Hán \n\nA: 지금 몇 시입니까? \nB: 열두 시입니다. \n\nA: 지금 몇 시입니까? \nB: 오후 세 시 사십오 분입니다."}, {"id": "E19", "book": "1", "lesson": "1.5", "topic": "하루 일과", "vocabulary": "", "grammar": "V/A아/어요", "note": "- Là đuôi câu, được dùng kết hợp vào sau thân động từ hoặc tính từ để nói lên suy nghĩ của người nói, thông báo một sự thật hoặc cũng có thể dùng trong câu một cách thân mật. Đối với cách nói trân trọng, hoặc mang tính chính thức, được thay thế bằng đuôi câu -ᄇ/습니다, -ᄇ/습니까. Trong trường hợp là câu hỏi thì được đọc lên giọng ở cuối câu. \n+ Những động từ hoặc tính từ kết thúc bằng ᅡ, ᅩ thì dùng với -아요, \n+ còn những động từ hoặc tính từ không kết thúc bằng ᅡ, ᅩ thì dùng với –어요. \n+ Đối với động từ có đuôi 하다 thì 하다 được chuyển thành 해요. \nA: 지금 무엇을 해요?\nB: 학교에서 공부해요. \n\n- Trong trường hợp những động từ hoặc tính từ có nguyên âm trùng với nguyên âm phía sau có thể lược bỏ nguyên âm trùng, còn những động từ hoặc tính từ kết thúc bằng các nguyên âm khác thì có thể thu gọn lại. \n+ 다음 주말에 여행을 가요. \n+ 극장에서 영화를 봐요. \n+ 카페에서 커피를 마셔요. \n\n(*) -아/어요 không những dùng trong câu trần thuật, câu hỏi mà còn dùng làm câu đề nghị, yêu cầu hoặc mệnh lệnh.\n(**) trong trường hợp kết hợp với danh từ thì dùng -입니다/-입니까 cho câu trân trọng, dùng -이에요/예요 cho câu thân mật. \n+ 선생님입니다./입니까?  →  선생님이에요. / 선생님이에요?\n+ 의사입니다./입니까?      →  의사예요. / 의사예요?"}, {"id": "E20", "book": "1", "lesson": "1.5", "topic": "하루 일과", "vocabulary": "", "grammar": "Place에 가다", "note": "- 에 ở trong 에 가다 dùng để chỉ hướng đi, \n- còn được dùng với 가다 / 오다 / 다니다. \n\n+ 지금 학교에 가요. \n+ 저는 한국 대학교에 다녀요."}, {"id": "E21", "book": "1", "lesson": "1.5", "topic": "하루 일과", "vocabulary": "", "grammar": "안 + V/A", "note": "- Đặt trước động từ hoặc tính từ để chỉ nghĩa phủ định. \n- Trong trường hợp động từ hoặc tính từ có dạng \"danh từ +하다\" thì 안 được đặt sau danh từ và trước 하다. \n\n+ 지금 학교에 안 가요.  \n+ 동생이 사과를 안 먹어요."}, {"id": "E22", "book": "1", "lesson": "1.6", "topic": "주말", "vocabulary": "의문관형사", "grammar": "V/A았/었-", "note": "- Được gắn vào thân động từ hoặc tính từ để biểu hiện một sự kiện hoặc một tình huống đã diễn ra trong quá khứ. \n+ Thân động từ hoặc tính từ kết thúc bằng nguyên âm ᅡ, ᅩ thì được dùng với 았, \n+ thân động từ, tính từ kết thúc bằng các nguyên âm khác và thân từ là 이다, 아니다 thì được dùng với 었. \n+ Đối với những động từ hoặc tính từ có đuôi 하다 thì được biến đổi thành -했. Sau 았/었 thì -아/어요 đều dùng chung một dạng là -어요. \n\n+ 공원에 사람이 많았습니다. \n+ 저는 아침에 빵을 먹었어요. \n+ 여기는 도서관이었어요. 지금은 도서관이 아니에요. \n+ 아버지는 의사였어요. \n\nA: 어제 뭘 했어요? \nB: 도서관에서 숙제했어요. \n\n+ 어제 11시에 잤어요. \n+ 우체국에서 편지를 보냈어요. \n\n(*) Sau khi kết hợp với 았/었, nếu nguyên âm của thân động từ, tính từ giống với 았 hoặc 었 thì có thể tỉnh lược đi, nếu nguyên âm của thân động tính từ không trùng thì có thể viết gộp lại. \n\n+ 지난 주말에 여행을 갔어요. \n+ 극장에서 영화를 봤어요. \n+ 카페에서 커피를 마셨어요."}, {"id": "E23", "book": "1", "lesson": "1.6", "topic": "주말", "vocabulary": "주말 활동", "grammar": "N하고", "note": "- Là một tiểu từ dùng để nối hai danh từ chỉ vật, người hoặc chỉ đối tượng cùng tham gia hành vi nào đó. \n\n+ 저는 어제 가게에서 빵하고 우유를 샀습니다. \n+ 오늘하고 내일은 학교에 안 가요.\n+ 어제 친구하고 도서관에서 공부했어요. \n+ 오늘 책하고 공책을 샀어요.\n+ 저는 불고기하고 갈비를 좋아합니다."}, {"id": "E24", "book": "1", "lesson": "1.6", "topic": "주말", "vocabulary": "", "grammar": "V(으)ㅂ시다", "note": "- Là đuôi câu được gắn vào sau thân động từ để tạo thành câu đề nghị hoặc lời yêu cầu đối với người có quan hệ ngang bằng và thấp hơn. \n+ Với động từ kết thúc bằng nguyên âm thì cộng với -ᄇ시다, \n+ với động từ kết thúc bằng phụ âm thì cộng với -읍시다. \n+ Trường hợp áp dụng cấu trúc này với động từ kết thúc bẳng ᄅ thì ᄅ sẽ được bỏ đi sau đó cộng thêm -ᄇ시다. \n\n+ 우리 같이 영화를 봅시다.\n+ 부산에 같이 갑시다.\n+ 오늘은 같이 한국 음식을 먹읍시다. \n+ 방에서 책을 읽읍시다.\n+ 내일 도서관에서 숙제합시다. \n+ 제주도를 여행합시다.\n+ 저녁 식사를 같이 만듭시다."}, {"id": "E25", "book": "1", "lesson": "1.7", "topic": "물건 사기", "vocabulary": "단위 명사", "grammar": "N(은/는)", "note": "- Đây là tiểu từ biểu hiện ý nghĩa đối chiếu. \n+ Khi kết hợp với danh từ kết thúc bằng phụ âm thì sử dụng 은, \n+ với danh từ kết thúc bằng nguyên âm thì sử dụng 는. \n\n+ 라면은 쌉니다. 불고기는 비쌉니다.\n+ 수박은 큽니다. 망고는 작습니다.\n+ 저는 한국에 살아요. 친구는 베트남에 살아요."}, {"id": "E26", "book": "1", "lesson": "1.7", "topic": "물건 사기", "vocabulary": "물건 사기", "grammar": "ㅡ 불규칙", "note": "1.  Âm tiết cuối thân từ của những động từ, tính từ kết thúc bằng nguyên âm ᅳ (ví dụ: 크다, 바쁘다 v.v....) khi gặp các đuôi từ bắt đầu bằng nguyên âm 아/어 thì nguyên âm ᅳ bị lược bỏ. \n2.  Sau khi ᅳ bị lược bỏ, nếu âm tiết phía trước của ᅳ có nguyên âm là ᅡ/ᅩ thì kết hợp với -아요, các trường hợp còn lại kết hợp với -어요. \n+ 아프다 : 아프 +-아요 → 아파요 \n+ 예쁘다 : 예쁘 +-어요 → 예뻐요 \n\n+ 배가 너무 고파요. \n+ 민준 씨는 키가 커요. \n+ 저는 어제 바빴어요."}, {"id": "E27", "book": "1", "lesson": "1.7", "topic": "물건 사기", "vocabulary": "", "grammar": "V고 싶다", "note": "- Được kết hợp với động từ, biểu hiện nguyện vọng của người nói mong muốn thực hiện một hành động nào đó. \n(*) Đối với chủ ngữ là ngôi thứ ba, sử dụng -고 싶어하다. \n\n+ 저는 한국에 가고 싶어요.\n+ 저는 컴퓨터를 사고 싶습니다.\n+ 화 씨는 한국어를 배우고 싶어해요."}, {"id": "E28", "book": "1", "lesson": "1.8", "topic": "음식", "vocabulary": "한국 음식", "grammar": "V겠-", "note": "-겠-gắn vào sau thân động từ, để thể hiện ý định thực hiện một hành động nào đó. \n- Có nghĩa trong tiếng Việt là ‘sẽ’, được sử dụng khi biểu hiện ý định của người nói - ngôi thứ nhất và cũng được sử dụng trong câu hỏi khi hỏi ý định của người nghe - ngôi thứ hai. \n\n+ 저는 콜라를 마시겠어요. \n+ 저는 비빔밥을 먹겠습니다. \n+ 안 씨, 무엇을 드시겠어요?"}, {"id": "E29", "book": "1", "lesson": "1.8", "topic": "음식", "vocabulary": "맛", "grammar": "V/A지 + 않다", "note": "-지 않다 gắn vào sau thân động từ hoặc tính từ, để biểu hiện dạng câu phủ định. Có nghĩa trong tiếng Việt là ‘không’. \n\n+ 주말에는 바쁘지 않아요. \n+ 이 케이크는 달지 않습니다. \n+ 저는 김치를 먹지 않습니다."}, {"id": "E30", "book": "1", "lesson": "1.8", "topic": "음식", "vocabulary": "식당", "grammar": "V(으)세요", "note": "-(으)세요 gắn vào sau thân động từ, để thể hiện sự yêu cầu. \n=>  -세요 gắn vào sau thân động từ kết thúc bằng nguyên âm,\n=>  -으세요 gắn vào sau thân động từ kết thúc bằng phụ âm. \n- Có nghĩa trong tiếng Việt là ‘hãy, vui lòng, xin mời’. \n\n+ 우유를 주세요. \n+ 여기에 앉으세요. \n+  8시에 학교에 오세요"}, {"id": "E31", "book": "1", "lesson": "1.9", "topic": "집", "vocabulary": "위치와 방향", "grammar": "N(으)로", "note": "- Gắn vào sau danh từ địa điểm để chỉ phương hướng. \n+ Nếu danh từ có phụ âm cuối thì dùng 으로, \n+ nếu danh từ không có phụ âm cuối hoặc kết thúc bằng phụ âm cuối ᄅ thì dùng 로 . \n\n+ 위로 올라가세요. \n+ 왼쪽으로 오세요. \n+ 교실로 들어가세요. \n\n+ 학생 : 선생님, 어디에 계세요? \n+ 선생님 : 사무실에 있어요. 1층으로 오세요."}, {"id": "E32", "book": "1", "lesson": "1.9", "topic": "집", "vocabulary": "집과 가구", "grammar": "V(으)ㄹ래요", "note": "- Trong quan hệ thân mật thì dùng cấu trúc này để hỏi về ý định hoặc đề nghị ai một điều gì đó. \n+ Những động từ có phụ âm cuối thì dùng -을래요, \n+ những động từ không có phụ âm cuối hay có phụ âm cuối là ᄅ thì dùng -ᄅ래요. \n\n A : 남 씨, 비빔밥 먹을래요? \n B : 네, 좋아요. \n\n A : 남씨, 우리 오늘 영화 볼래요? \n B : 네, 좋아요."}, {"id": "E33", "book": "1", "lesson": "1.9", "topic": "집", "vocabulary": "장소", "grammar": "N도", "note": "Gắn vào sau danh từ, tương đương với nghĩa trong tiếng Việt là ‘cũng’. \n\n+ 교실에 책상이 있습니다. 의자도 있습니다.\n+ 저는 한국어를 공부합니다. 제 친구도 한국어를 공부합니다. \n\nA : 무슨 음식을 좋아해요? \nB : 저는 김밥을 좋아해요. 불고기도 좋아해요."}, {"id": "E34", "book": "1", "lesson": "1.10", "topic": "가족", "vocabulary": "가족", "grammar": "수 관형사", "note": "- Khi ta nói về số lượng người hoặc đồ vật chúng ta sẽ dùng số đếm thuần Hàn và Hán Hàn, khi nói về tuổi dùng số đếm thuần Hàn. \n- Khi nói về số lượng thì thường được theo sau bởi các danh từ chỉ đơn vị nên số từ có một số thay đổi. Vì thế nên 스물 thì sẽ được viết thành 스무 살, 스무 개 \n\n+ 뜨엉 씨는 올해 스무 살입니다. \n+ 저는 스물두 살이에요.\n+ 우리 형은 서른네 살입니다."}, {"id": "E35", "book": "1", "lesson": "1.10", "topic": "가족", "vocabulary": "직업", "grammar": "Sb께서 , Sb께서는", "note": "께서 là hình thức trân trọng của 이/가, \ncòn 께서는 là hình thức trân trọng của 은/는, \n=> được dùng sau chủ thể chỉ đối tượng được tôn kính. \n\n+ 아버지께서 오십니다.\n+ 선생님께서 전화하셨습니다. \n+ 할아버지께서는 텔레비전을 보십니다."}, {"id": "E36", "book": "1", "lesson": "1.10", "topic": "가족", "vocabulary": "", "grammar": "V/A(으)시-", "note": "- Nếu chủ ngữ là người có vị trí hoặc tuổi tác cần được tôn kính thì gắn thêm 으시 vào sau thân từ của vị ngữ (thân của động từ hay tính từ). \n+ Nếu thân động từ hay tính từ kết thúc bằng nguyên âm hoặc phụ âm cuối là ᄅ thì thêm 시, \n+ khi kết thúc bằng phụ âm (ngoài ᄅ) thì thêm (으)시. \n(*) Trong trường hợp sau (으)시 là -아/어요, thì sẽ được kết hợp thành (으) 세요. \n\n+ 부모님께서는 하노이에 사십니다. \n+ 사장님, 오늘 신문을 읽으셨습니까? \n+ 우리 선생님은 한국 분이세요. \n\n(*) Một số động từ không thêm (으)시 vào sau mà được dùng động từ khác (kính ngữ) để thể hiện sự tôn kính. \n\t있다 → 계시다 \t   có, đang sống \n\t자다 → 주무시다 \t   ngủ\n\t죽다 → 돌아가시다 \t   mất (chết, qua đời) \n\t먹다 → 드시다, 잡수시다   ăn \n\t말하다 → 말씀하시다 \t   nói \n\n\t+  선생님, 이 과일 좀 드세요. \n\t+ 할머니께서는 지금 주무십니다. \n\n(*) Danh từ : 집 => 댁 , 생일 => 생신 ,  밥 => 진지 , 이름 => 성함 , 나이 => 연세, 말 => 말씀\n \t+  할아버지 생신이 언제예요? \n\t+ 아버님 성함이 어떻게 되세요?"}, {"id": "E37", "book": "1", "lesson": "1.10", "topic": "가족", "vocabulary": "", "grammar": "ㄹ 불규칙", "note": "- Những động từ kết thúc bằng phụ âm ᄅ như 살다, 알다, 만들다, 열다, nếu được theo sau bằng các phụ âm ᄂ, ᄅ, ᄇ, ᄉ thì phụ âm ᄅ, ᄂ sẽ được giản lược mất đi.\n +  살다\t: 사+ᄇ니다 \t→  삽니다 \n +  열다\t: 여+세요 \t→  여세요 \n\n+ 언니는 베트남에 삽니다. \n+ 창문을 여세요.\n+ 누가 김밥을 만드세요?"}, {"id": "E38", "book": "1", "lesson": "1.11", "topic": "날씨", "vocabulary": "계절", "grammar": "V/A고 + clause", "note": "- Gắn vào sau động từ hay tính từ để liên kết hai hay nhiều hành động, trạng thái, sự việc, \n- nghĩa tương đương trong tiếng Việt là ‘và, còn’. \n\n+ 비가 오고 바람이 불어요. \n+ 집이 크고 멋있어요. \n+ 란 씨는 베트남 사람이고 유진 씨는 한국 사람이에요. \n+ 이 식당은 싸고 맛있어요. \n\n(*) Vĩ tố liên kết này còn được sử dụng khi liên kết các hành động theo trình tự thời gian, nghĩa tương đương trong tiếng Việt là ‘rồi’. \n\n+ 내가 손을 씻고 밥을 먹어요. \n+ 난 쇼핑을 하고 집에 갔어요. \n+ 어제 집에서 숙제하고 잤어요. \n+ 수업이 끝나고 도서관에 가요."}, {"id": "E39", "book": "1", "lesson": "1.11", "topic": "날씨", "vocabulary": "날씨", "grammar": "Time1부터 + Time2까지", "note": "- 부터 là tiểu từ có nghĩa tương đương trong tiếng Việt là \"từ\", biểu hiện thời điểm bắt đầu của một sự việc nào đó. \n- 까지 là tiểu từ có nghĩa tương đương trong tiếng Việt là \"đến, tới\", biểu hiện thời điểm kết thúc của một sự việc nào đó. \n(*) Hai tiểu từ này có thể được sử dụng riêng và cũng có thể được sử dụng cùng trong một câu. \n\n+ 세 시부터 다섯 시까지 운동을 합니다. \n+ 12월 20일부터 겨울방학입니다.\n+ 어제는 밤 열두 시까지 공부했습니다. \n+ 한국은 6월부터 8월까지 덥습니다. \n+ 아침부터 지금까지 식사를 못 했습니다."}, {"id": "E40", "book": "1", "lesson": "1.11", "topic": "날씨", "vocabulary": "기온", "grammar": "V(으)ㄹ + 거예요", "note": "- Gắn vào sau thân động từ, thể hiện ý chí, kế hoạch trong tương lai của chủ ngữ. \n+ Vᄅ 거예요 được gắn vào sau những động từ kết thúc bằng nguyên âm hoặc bằng phụ âm ᄅ và \n+ V을 거예요 được gắn vào sau những động từ kết thúc bằng phụ âm. \n(*) V(으) ᄅ 겁니다 được sử dụng trong các trường hợp trang trọng với cùng ý nghĩa. \n\n+ 오늘 저녁에는 비빔밥을 먹을 거예요. \n+ 다음 주에 한국에 갈 거예요.\n+ 주말에 친구를 만날 거예요. \n\n(**) Đuôi này cũng được kết hợp với động từ và tính từ để biểu hiện nghĩa phỏng đoán. \n\n+ 유진 씨는 오늘 아마 안 올 거예요. \n+ 아마 극장에 사람이 많을 거예요."}, {"id": "E41", "book": "1", "lesson": "1.11", "topic": "날씨", "vocabulary": "", "grammar": "ㅂ 불규칙", "note": "- Những động từ, tính từ có thân từ kết thúc bằng phụ âm ᄇ như: 고맙다 (cám ơn), 맵다 (cay), 춥다 (lạnh) khi kết hợp với những đuôi bắt đầu bằng nguyên âm thì ᄇ sẽ chuyển thành 우. \n+ 고맙다:  고마+우+어요 → 고마워요 \n\n+ 정말 고마워요. \n+ 김치는 매워요. \n+ 어제는 아주 추웠어요. \n\n(*) Riêng động từ 돕다 (giúp đỡ) khi kết hợp với đuôi bắt đầu bằng nguyên âm 아/어 thì ᄇ được đổi thành 오. \n+ 돕다: \t도+오+아요\t\t→도와요 \n\t도+우+(으)ᄅ 거예요\t→도울 거예요 \n\n+ 도와주세요. \n+ 이 사람이 김 선생님을 도울 거예요. \n\n(**) Các động, tính từ 입다 (mặc), 좁다 (hẹp) không áp dụng theo dạng bất quy tắc trên. \n\n+ 코트를 입어요. \n+ 교실이 좁아요."}, {"id": "E42", "book": "1", "lesson": "1.12", "topic": "전화", "vocabulary": "전화", "grammar": "Sb에게, Sb한테, Sb께", "note": "- Đây là các tiểu từ được sử dụng cùng với động từ 주다 để chỉ ra đối tượng nhận ảnh hưởng của hành vi. \n+ 한테 chủ yếu được dùng khi nói, \n+ 에게 được dùng cả khi nói và viết. \n(*) 께 dùng với người bề trên. \n\n+ 란 씨가 안 씨에게 선물을 주었습니다. \n+ 제가 안 씨한테 전화했어요.\n+ 선생님께 전화를 드리세요."}, {"id": "E43", "book": "1", "lesson": "1.12", "topic": "전화", "vocabulary": "전화 통화", "grammar": "V/A지만 + clause", "note": "- Vĩ tố liên kết sử dụng khi nội dung câu sau trái ngược với nội dung câu trước, có nghĩa tương đương với tiếng Việt là ‘nhưng’. \n\n+ 한국어는 어렵지만 재미있어요.\n+ 교실 밖은 춥지만 교실 안은 따뜻합니다. \n+ 한국 여행은 힘들었지만 즐거웠어요."}, {"id": "E44", "book": "1", "lesson": "1.12", "topic": "전화", "vocabulary": "", "grammar": "V(으)려고 + 하다", "note": "- Gắn vào động từ để biểu hiện ý đồ của hành vi. \n-려고 하다 gắn vào gốc động từ kết thúc bởi nguyên âm hoặc phụ âm ᄅ, \n-으려고 하다 gắn đuôi động từ kết thúc bởi phụ âm, \n- có nghĩa tương đương với tiếng Việt là \"định (làm)\", \"muốn (làm)\". \n\n+ 저는 이번 겨울방학에 수영을 배우려고 합니다. \n+ 10년 후에 고향에서 살려고 합니다.\n+ 주말에 가족과 함께 한국 음식을 먹으려고 합니다."}, {"id": "E45", "book": "1", "lesson": "1.13", "topic": "생일", "vocabulary": "생일", "grammar": "V/A아/어서 + clause", "note": "- Là một tiếp vĩ từ được gắn vào sau tính từ hoặc động từ để giải thích lý do của tính chất hoặc hành động đó. \n+ Trường hợp tính từ hoặc động từ có nguyên âm tận cùng là ᅡ, ᅩ thì cộng với -아서, \n+ trường hợp nguyên âm tận cùng không phải là ᅡ, ᅩ thì cộng với -어서, \n+ trường hợp tận cùng là 하다 thì trở thành 해서. \n(*) Lưu ý, trước -아/어서 không dùng quá khứ. \n\n+ 가방이 작아서 불편해요.\n+ 늦어서 죄송합니다.\n+ 어제 피곤해서 일찍 잤습니다.\n+ 밤에 너무 더워서 잘 수 없었습니다. \n\nA : 어디에 가요? \nB : 부모님께서 베트남에서 오셔서 공항에 가요. \n\nA : 어제 왜 학교에 안 왔어요? \nB : 배가 아파서 병원에 갔어요. \n\nA : 왜 한국에 가요? \nB : 한국 친구를 만나고 싶어서 가요. \n\n(**) Trong câu mệnh lệnh hay câu đề nghị có kết thúc câu tận cùng là -(으)세요 , -(으)ᄇ시다 thì không dùng -아/어서 để diễn tả lý do. \n+ 이 가방이 예뻐서 사세요. (×) \n+ 추워서 문을 닫읍시다. (×) \n\n(*) Sau danh từ thì dùng -(이)라서. \n+ 일요일이라서 백화점에 사람이 많습니다."}, {"id": "E46", "book": "1", "lesson": "1.13", "topic": "생일", "vocabulary": "선물", "grammar": "V(으)ㄹ까요?", "note": "- Gắn vào sau động từ khi hỏi ý kiến của người nghe hoặc đưa ra một đề nghị nào đó. \n+ Những động từ kết thúc là nguyên âm thì thêm -ᄅ까요, \n+ những động từ có phụ âm cuối thì thêm -을까요. \n+ Nhưng những động từ kết thúc bằng phụ âm ᄅ thì thêm -ᄅ까요. \n\nA : (우리) 주말에 같이 영화를 볼까요? \nB : 좋아요. 영화를 봅시다. \n\nA : (우리) 점심에 뭘 먹을까요? \nB : 불고기를 먹읍시다. \n\nA : 제가 카메라를 준비할까요? \nB : 네, 남 씨가 준비하세요."}, {"id": "E47", "book": "1", "lesson": "1.13", "topic": "생일", "vocabulary": "", "grammar": "못 + V", "note": "- Đứng trước động từ để chỉ rằng chủ thể có ý chí nhưng không đủ năng lực hoặc do một lý do nào đó mà ý đồ của chủ ngữ không thể thực hiện, \n- có nghĩa là \"không thể\". \n(*) Trong trường hợp “명사 (danh từ) + 하다” thì chúng ta đặt 못 trước 하다. \n\n+ 저는 김치를 못 먹어요.\n+ 남 씨는 수영을 못 해요.\n+ 어제 시간이 없어서 숙제를 못 했어요."}, {"id": "E48", "book": "1", "lesson": "1.14", "topic": "취미", "vocabulary": "운동", "grammar": "V/A(으)ㄹ + 수 + 있다/없다", "note": "- Cấu trúc này thường kết hợp sau thân từ của động từ hoặc tính từ biểu hiện khả năng thực hiện một việc nào đó. \n+ Nếu thân từ kết thúc bằng nguyên âm thì kết hợp với -ᄅ 수 있다, \n+ còn nếu thân từ kết thúc bằng phụ âm thì kết hợp với -을 수 있다. \n+ Riêng thân từ kết thúc bằng ᄅ được kết hợp với -ᄅ 수 있다. \n- Dạng phủ định của cấu trúc này (biểu hiện nghĩa ‘không có khả năng làm một việc gì đó’) là -(으)ᄅ 수 없다. \n\nA : 토요일에 같이 등산할 수 있어요? \nB : 네, 등산할 수 있어요. 토요일에는 시간이 있어요. \n \nA : 수빈 씨, 오토바이를 탈 수 있어요? \nB : 아니요, 저는 오토바이를 탈 수 없어요."}, {"id": "E49", "book": "1", "lesson": "1.14", "topic": "취미", "vocabulary": "취미", "grammar": "V/A기  /  V는 것", "note": "- Được gắn vào sau thân từ của động từ hoặc tính từ nhằm chuyển đổi động từ hay tính từ đó thành danh từ để có thể sử dụng như chủ ngữ hay bổ ngữ trong câu. \n- Có thể gắn các tiểu từ như: 이/가, 을/를 vào sau -기, -는 것. \n\n+ 제 취미는 영화 보기예요.\n+ 저는 혼자 걷는 것을 좋아해요.\n+ 술을 많이 마시는 것은 건강에 좋지 않아요."}, {"id": "E50", "book": "1", "lesson": "1.14", "topic": "취미", "vocabulary": "빈도", "grammar": "ㄷ 불규칙", "note": "- Những động từ có thân từ kết thúc bằng ᄃ như 걷다 (đi bộ), 듣다 (nghe), 묻다 (hỏi)’ khi kết hợp với đuôi bắt đầu bằng nguyên âm thì ᄃ chuyển thành ᄅ. \n+ 듣다 : 듣+어요 → 들어요 \n\n+ 무슨 노래를 들었어요? \n+ 여러분, 어려워요? 그러면 선생님께 물어보세요. \n\n(*) Những động từ: 닫다 (đóng), 믿다 (tin), 얻다 (giành được), 받다 (nhận được) không áp dụng theo dạng bất quy tắc trên \n\n+ 누가 창문을 닫았어요? \n+ 저는 그 분의 이야기를 믿어요."}, {"id": "E52", "book": "1", "lesson": "1.15", "topic": "교통", "vocabulary": "교통 수단", "grammar": "Place1에서 + Place2까지", "note": "- Biểu hiện phạm vi từ điểm xuất phát đến điểm kết thúc của một hành động hay một trạng thái nào đó. \n\n+ 집에서 학교까지 어떻게 가요? \n\nA : 한국에서 베트남까지 시간이 얼마나 걸려요? \nB : 5시간쯤 걸려요."}, {"id": "E53", "book": "1", "lesson": "1.15", "topic": "교통", "vocabulary": "의문 부사", "grammar": "N(으)로", "note": "- Là tiểu từ chỉ phương tiện, cách thức, phương pháp thực hiện một hành động nào đó. \n+ Khi kết hợp với danh từ kết thúc bằng phụ âm, sử dụng 으로, \n+ với danh từ kết thúc bằng nguyên âm, sử dụng 로. \n+ Riêng đối với danh từ kết thúc bằng phụ âm ᄅ được kết hợp với dạng 로. \n\n+ 저는 학교까지 오토바이로 와요. \n+ 한국 사람은 보통 버스와 지하철로 회사에 가요. \n\n(*) Phía sau cấu trúc “danh từ +(으)로” biểu hiện phương tiện giao thông thường kết hợp với các động từ 가다/오다 (đi/ đến). \nKhi sử dụng động từ 타다 (lên, đi) sau cấu trúc biểu hiện phương tiện giao thông thì thường sử dụng theo dạng “danh từ 명사 + 을/를 타다.” \nVí dụ: 버스로 가다  =  버스를 타다  (đi bằng xe buýt)"}, {"id": "E54", "book": "1", "lesson": "1.15", "topic": "교통", "vocabulary": "교통", "grammar": "(Place에) + V(으)러 + 가다", "note": "- Là cấu trúc kết hợp vào sau động từ biểu hiện mục đích của hành động chỉ sự chuyển động. \n- Có thể sử dụng các động từ 오다, 나가다, 나오다, 들어가다 thay cho động từ 가다.\n+ Động từ kết thúc bằng phụ âm thì kết hợp với -으러, \n+ động từ kết thúc bằng nguyên âm thì kết hợp với -러. \n+ Nhưng đối với những động từ kết thúc bằng phụ âm ᄅ thì cũng kết hợp với -러. \n\n+ 저는 한국에 한국어 공부하러 왔어요. \n+ 우리는 지금 밥 먹으러 가요. \n+ 토요일에 공원에 놀러 갈까요?"}, {"id": "E55", "book": "2", "lesson": "2.1", "topic": "만남", "vocabulary": "관계", "grammar": "N의", "note": "- Tiểu từ thể hiện sự phụ thuộc hoặc sở hữu của danh từ đứng trước khi có hai danh từ liền kề, nghĩa tương đương trong tiếng Việt là ‘của’. \n- Trong vài trường hợp 의 có thể được giản lược. \n\n+ 오늘은 친구의 생일입니다.\n+ 김 선생님의 가방이 책상 위에 있어요. \n+ 토요일에 남 씨의 친구를 만나려고 해요. \n+ 아버지의 동생은 작은아버지입니다.\n+ 저 책이 흐엉 씨의 것입니다. \n\n(*) Từ 저의 và 나의 có thể rút gọn thành 제 và 내, nghĩa là “của tôi.” \n\n+ 제 이름은 흐엉입니다.\n+ 그 사람은 내 동생이에요. \n+ 제 가족을 소개하겠습니다. \n+ 이것이 내 전화번호예요. \n+ 내 친구의 이름은 유나예요."}, {"id": "E56", "book": "2", "lesson": "2.1", "topic": "만남", "vocabulary": "방문", "grammar": "V/A(으)ㄹ + 때 + clause", "note": "- Gắn vào sau thân của động từ hay tính từ, thể hiện thời điểm xảy ra một sự việc nào đó hoặc thời điểm tiếp tục một trạng thái nào đó. \n- Cấu trúc này có nghĩa tương đương với tiếng Việt là ‘khi’. \n+ Với những động từ hay tính từ kết thúc bằng một phụ âm thì gắn -을 때 vào, \n+ với những động từ hay tính từ kết thúc bằng nguyên âm thì gắn -ᄅ때 vào. \n+ Trong trường hợp động từ hay tính từ kết thúc bằng ᄅ thì gắn 때 vào. \n\n+ 아플 때 이 약을 드세요.\n+ 밥을 먹을 때 전화가 왔어요. \n\nA : 언제 태권도를 배웠어요?\nB : 한국에서 살 때 태권도를 배웠어요. \n\n+ 이 옷을 만들 때 정말 힘들었어요. \n+ 한국말을 들을 때 좀 어려워요. \n+ 날씨가 더울 때 수영장에 가요."}, {"id": "E57", "book": "2", "lesson": "2.1", "topic": "만남", "vocabulary": "인사말", "grammar": "V아/어 + 주다", "note": "- Gắn với thân của động từ để biểu hiện việc thực hiện một hành vi nào đó cho người khác. \n+ Khi thân của động từ kết thúc bằng nguyên âm ᅡ hay ᅩ thì thêm -아 주다, \n+ trường hợp không phải là ᅡ, ᅩ thì thêm -어 주다 và \n+ với động từ có 하다 thì dùng 해 주다. \n\n+ 창문을 좀 닫아 주세요.\n+ 나는 친구의 가방을 들어 줍니다. \n+ 초대해 주셔서 감사합니다. \n+ 이것 좀 도와주세요. \n\nA : 제가 사진을 찍어 드릴까요? \nB : 네, 부탁합니다. \n\n+ 지우개 좀 빌려 주시겠어요? \n\n(*) Nếu người tiếp nhận tác động của hành vi có vị trí cao hơn hoặc nhiều tuổi hơn chủ thể thực hiện hành động thì sử dụng -아/어 드리다 thay cho -아/어 주다."}, {"id": "E58", "book": "2", "lesson": "2.2", "topic": "역속", "vocabulary": "약속", "grammar": "N만", "note": "- Là tiểu từ biểu thị sự hạn định một vật nào đó và loại trừ những vật khác.\n- Dịch là \"chỉ\" \n\n+ 우리 반 학생은 모두 12명이에요. 저만 남자입니다. \n+ 아침에는 밥을 먹지 않습니다. 커피만 마십니다. \n+ 한국어 수업 시간에는 한국말로만 이야기합시다. \n+ 저는 과일을 다 좋아하지만 수박만 싫어합니다. \n\nA : 토요일에도 학교에 갑니까? \nB : 아니요, 평일에만 갑니다."}, {"id": "E59", "book": "2", "lesson": "2.2", "topic": "역속", "vocabulary": "장소", "grammar": "V/A(으)니까 + clause", "note": "- Là vĩ tố liên kết biểu thị nội dung ở vế trước là căn cứ của sự phán đoán hay là lý do cho nội dung ở vế sau. \n+ Thân động từ, tính từ kết thúc bằng nguyên âm thì dùng -니까, \n+ kết thúc bằng phụ âm dùng -으니까, \n+ kết thúc bằng ᄅ dùng -니까. \n- Nghĩa tiếng Việt là \"do ... nên ...\" \n\n+ 오늘은 약속이 있으니까 내일 만납시다. \n+ 날씨가 추우니까 옷을 많이 입으세요. \n\nA : 지금 이야기 좀 할 수 있어요?\nB : 미안해요. 지금 바쁘니까 이따가 이야기합시다. \n\n+ 비가 오니까 우산을 가져가세요. \n+ 배가 고프니까 지금 밥을 먹을까요? \n+ 길이 막히니까 지하철을 탑시다. \n\n(*) Trong trường hợp từ ở trước là danh từ kết thúc bằng nguyên âm thì dùng -니까 danh từ kết thúc bằng phụ âm thì dùng -이니까."}, {"id": "E60", "book": "2", "lesson": "2.2", "topic": "역속", "vocabulary": "", "grammar": "V지 + 말다", "note": "- Biểu hiện được dùng khi bảo người nghe không nên làm một hành vi nào đó. \n- Trong trường hợp là câu mệnh lệnh thì sử dụng dạng -지 마세요 hoặc -지 마십시오; \n- trong trường hợp là câu thỉnh dụ thì sử dụng dạng -지 맙시다. \n- Nghĩa tiếng Việt là \"đừng ...\". \n\n+ 버스를 타지 마세요. \n+ 사진을 찍지 마십시오. \n+ 쓰레기를 버리지 맙시다. \n+ 여기서 음식을 먹지 마세요. \n+ 수업 시간에 늦지 마세요."}, {"id": "E61", "book": "2", "lesson": "2.2", "topic": "역속", "vocabulary": "", "grammar": "V/A아/어도 + 되다", "note": "- Biểu hiện được dùng khi biểu thị sự cho phép hay đồng ý một hành động nào đó. \n+ Thân động từ kết thúc bằng nguyên âm ᅡ, ᅩ thì dùng -아도 되다, \n+ không phải là ᅡ, ᅩ thì dùng -어도 되다; \n+ với động từ, tính từ có đuôi 하다 thì dùng -해도 되다. \n- Nghĩa tiếng Việt là \"được (làm gì), làm ... cũng được.\" \n\n+ 여기에 앉아도 돼요?\n+ 여기서 사진을 찍어도 됩니다. \n\nA : 지금 집에 가도 돼요? \nB : 네, 집에 가도 돼요. \n\n+ 하숙집에서 요리해도 됩니다. \n+ 제가 좀 도와 줘도 될까요? \n\nA : 수업 시간에 사전을 봐도 됩니까? \nB : 네, 봐도 됩니다."}, {"id": "E62", "book": "2", "lesson": "2.3", "topic": "물건 사기", "vocabulary": "단위 명사", "grammar": "N보다  (+더/덜)", "note": "- Là tiểu từ sử dụng khi so sánh người hay sự vật, danh từ trước đó là tiêu chuẩn để so sánh. \n- Với ý nghĩa là “hơn”, tiểu từ này cũng được sử dụng cùng với 더 và 덜. (덜 nghĩa là ‘kém’) \n\n+ 이 옷보다 저 옷이 더 예뻐요. \n+ 버스보다 택시가 빠릅니다. \n+ 시장이 백화점보다 쌉니다."}, {"id": "E63", "book": "2", "lesson": "2.3", "topic": "물건 사기", "vocabulary": "물건 사기", "grammar": "A(으)ㄴ + Main Noun", "note": "- Gắn vào sau thân tính từ, bổ nghĩa cho danh từ đi theo ngay sau đó, được dùng để biểu thị trạng thái của người hay sự vật. \n+ Nếu thân của tính từ kết thúc bằng phụ âm thì dùng –은, \n+ kết thúc bằng nguyên âm thì dùng ᄂ, \n+ còn kết thúc bằng ᄅ thì lược bỏ đi ᄅ và gắn ᄂ vào. \n\n+ 큰 가방이 좋아요.\n+ 저 가게에 좋은 물건이 많습니다. \n+ 긴 치마를 사고 싶어요."}, {"id": "E64", "book": "2", "lesson": "2.3", "topic": "물건 사기", "vocabulary": "사물의 상태", "grammar": "V는 + Main Noun", "note": "- Gắn vào sau thân động từ, bổ nghĩa cho danh từ theo ngay sau đó, được dùng để biểu thị sự kiện hay hành động đó xảy ra ở thời điểm hiện tại.\n(*) –는 cũng được sử dụng cho cả thân tính từ kết thúc bằng 있다 hay 없다. \n\n+ 지금 찾는 장소가 어디예요?\n+ 어머니가 자주 만드는 음식은 불고기입니다. \n+ 멋있는 옷을 한 벌 사고 싶어요."}, {"id": "E65", "book": "2", "lesson": "2.4", "topic": "병원", "vocabulary": "신체", "grammar": "V(으)ㄴ + Main Noun", "note": "- Gắn vào sau động từ, bổ nghĩa cho danh từ, biểu thị hành vi hay sự kiện đã xảy ra trong quá khứ, hoặc là hành vi đó đã được hoàn thành và trạng thái đó vẫn đang được duy trì. \n+ Nếu thân của động từ kết thúc bằng phụ âm thì dùng -은, \n+ kết thúc bằng nguyên âm thì dùng ᄂ, \n+ còn kết thúc bằng ᄅthì lược bỏ đi ᄅvà gắn ᄂvào. \n\n+ 영국에서 온 마이클입니다.\n+ 어제 저녁에 먹은 음식은 불고기였습니다. \n+ 지난번에 만든 장갑을 친구에게 선물했습니다."}, {"id": "E66", "book": "2", "lesson": "2.4", "topic": "병원", "vocabulary": "증상", "grammar": "N마다", "note": "- Gắn vào sau danh từ, biểu thị ý nghĩa \"tất cả mọi thứ không loại trừ một cái gì.\" \n- Nghĩa tiếng Việt là \"mọi, mỗi, các\" \n\n+ 현우는 수요일마다 도서관에 갑니다. \n+ 저는 주말마다 공원에 갑니다. \n+ 가게마다 옷이 다릅니다."}, {"id": "E67", "book": "2", "lesson": "2.4", "topic": "병원", "vocabulary": "약", "grammar": "V/A아/어야 + 하다", "note": "- Là động từ bổ trợ sử dụng cùng với động từ và tính từ, biểu hiện tính cần thiết, nghĩa vụ hay bắt buộc về một tình huống hay sự việc nào đó. Có thể sử dụng 되다 thay cho 하다. \n+ Thân động từ hay tính từ kết thúc bằng ᅡ, ᅩ dùng -아야’, \n+ trường hợp không phải là ᅡ, ᅩ dùng -어야’, \n+ với động từ, tính từ 하다 dùng -해야. \n- Nghĩa tiếng Việt là \"phải ...\" \n\n+ 병원에 가야 합니다.\n+ 약을 먹고 푹 쉬어야 합니다. \n+ 매일 숙제를 해야 합니다."}, {"id": "E70", "book": "2", "lesson": "2.5", "topic": "편지", "vocabulary": "접속 부사", "grammar": "V지 + 못하다", "note": "-지 못하다 là động từ bổ trợ gắn vào thân động từ, thể hiện chủ ngữ có ý chí nhưng không có khả năng hoặc vì một hoàn cảnh nào đó mà ý chí của chủ ngữ không được thực hiện. \n- Ý nghĩa tiếng Việt là \"không thể ...\" \n\n+ 저는 운전을 하지 못해요. \n+ 어제는 친구를 만나지 못했어요. \n+ 배가 아파서 밥을 먹지 못했어요. \n+ 저는 한국어를 잘 하지 못해요. \n+ 감기에 걸려서 학교에 가지 못했어요. \n\nA  수영할 수 있어요? \nB  아니요, 수영하지 못해요. \n\n(*) -지 못하다 được dùng khi chủ ngữ có ý định sẽ làm một việc gì đó nhưng không có khả năng, còn -지 않다 biểu hiện chủ ngữ có năng lực nhưng không có ý định thực hiện."}, {"id": "E71", "book": "2", "lesson": "2.5", "topic": "편지", "vocabulary": "편지", "grammar": "V/A(으)면 + clause", "note": "- Là vĩ tố sử dụng khi nói giả định một sự thật chưa xảy ra, không chính xác hay nói về điều kiện giả định cho một việc nào đó. \n- Nghĩa tiếng Việt là \"nếu ... thì ...\" \n\n+ 날씨가 좋으면 여행을 갈 거예요. \n+ 감기에 걸리면 이 약을 드세요. \n+ 친구들과 같이 살면 재미있을 거예요. \n+ 내일 추우면 산에 안 갈 거예요.  \n+ 한국 뉴스를 많이 들으면 한국어를 잘할 수 있을 거예요. \n\nA : 시간이 있으면 저랑 영화 보러 갈래요? \nB : 네, 좋아요."}, {"id": "E72", "book": "2", "lesson": "2.5", "topic": "편지", "vocabulary": "", "grammar": "V(으)ㄹ + Main Noun", "note": "- Gắn vào sau động từ, biểu hiện sự dự đoán hoặc là một việc trong tương lai chưa xảy ra. \n+ Nếu thân của động từ kết thúc bằng phụ âm thì dùng -을, \n+ kết thúc bằng nguyên âm thì dùng ᄅ, \n+ còn kết thúc bằng ᄅ thì lược bỏ đi ᄅ của thân động từ và gắn ᄅ vào. \n\n+ 내일은 할 일이 많아요.\n+ 점심에 먹을 음식을 만들었어요. \n+ 여기가 바로 우리가 살 집이에요. \n+ 이게 생일 파티 때 입을 옷이에요. \n+ 내일 수업 시간에 들을 내용은 97쪽입니다. \n\nA : 풍씨, 제가 도울 일이 있어요? \nB : 네, 손님들이 마실 음료수를 좀 준비해 주세요."}, {"id": "E73", "book": "2", "lesson": "2.6", "topic": "교통", "vocabulary": "교통 수단", "grammar": "V아/어서 + clause", "note": "- Gắn vào thân động từ biểu hiện quan hệ trước sau mang tính thời gian của hai hành động. \n- Biểu hiện hành động ở mệnh đề trước không đứng độc lập mà tiếp nối hành động liên quan chặt chẽ với hành động của mệnh đề sau. \n(*) Chủ ngữ của mệnh đề trước và sau là một. \n+ Thân động từ hay tính từ kết thúc bằng nguyên âm ᅡ, ᅩ thì dùng -아서, \n+ trong trường hợp không phải là ᅡ, ᅩ thì dùng -어서, \n+ với động từ 하다 thì dùng-해서. \n- Nghĩa tương đương trong tiếng Việt là ‘rồi’. \n\n+ 사과를 씻어서 먹었습니다.\n+ 도서관에 가서 공부했습니다.\n+ 서울역에서 내려서 1호선으로 갈아타세요. \n+ 사거리에서 좌회전해서 죽 가세요.\n+ 저기 연필 좀 주워서 저에게 주세요. \n+ 내일 친구를 만나서 쇼핑하러 갈 거예요."}, {"id": "E74", "book": "2", "lesson": "2.6", "topic": "교통", "vocabulary": "교통", "grammar": "V/A/N지요?", "note": "- Gắn vào sau danh từ, thân của động từ hoặc tính từ. \n- Sử dụng khi hỏi để xác nhận lại điều mà người nói đã biết trước hoặc là người nói tin rằng người nghe đã biết trước và hỏi để tìm sự đồng tình. \n(*) Khi có những vĩ tố chỉ thời gian như 았/었, 겠 thì -지요 được gắn vào sau những vĩ tố đó. \n(*) Với danh từ kết thúc bằng phụ âm thì dùng -이지요, nguyên âm thì dùng -지요. \n- Nghĩa tương đương trong tiếng Việt là ‘ đúng không?’, ‘phải không? \n\nA : 그 영화 정말 재미있지요? \nB : 네, 정말 재미있었어요. \n\n+ 2시까지 도착할 수 있겠지요? \n+ 거기가 서울백화점이지요? \n+ 내일 산에 갈 거지요? \n+ 지원 씨, 어제 남자랑 영화 봤지요? \n+ 흐엉 씨는 베트남에서 왔지요? \n+ 요즘 매일 학교에 가지요?"}, {"id": "E75", "book": "2", "lesson": "2.6", "topic": "교통", "vocabulary": "건물", "grammar": "서수사", "note": "- Sử dụng để biểu hiện số thứ tự hoặc số lần. \n\nA : 한국에 처음 왔습니까?\nB : 아니요, 이번이 두 번째입니다. \n\n+ 우리 집은 골목에서 세 번째 집입니다. \n+ 첫 번째 사거리에서 오른쪽으로 가세요. \n+ 오늘이 제 스무 번째 생일이에요. \n+ 이번이 벌써 열 번째 이야기하는 거예요.\n \nA : 제가 몇 번째입니까?\nB : 여섯 번째니까 조금만 더 기다리세요."}, {"id": "E77", "book": "2", "lesson": "2.7", "topic": "전화", "vocabulary": "전화", "grammar": "V(으)려고 + clause", "note": "- Gắn vào sau động từ, biểu hiện ý định của chủ thể hành động. \n+ Khi gắn vào sau thân động từ kết thúc bằng nguyên âm dùng -려고, \n+ kết thúc là một phụ âm dùng -으려고, \n+ kết thúc bằng phụ âm ᄅ dùng -려고. \nNghĩa tiếng Việt là \"định, để (làm gì).\" \n\n+ 한국에서 일하려고 한국어를 배웁니다. \n+ 사진을 찍으려고 카메라를 가져왔어요. \n+ 불고기를 만들려고 고기를 샀어요. \n+ 취직하려고 공부합니다. \n+ 한국어를 잘 들으려고 매일 한국 드라마를 봅니다. \n+ 친구를 초대하려고 전화했어요."}, {"id": "E78", "book": "2", "lesson": "2.7", "topic": "전화", "vocabulary": "휴대전화", "grammar": "V기 + 전에 + clause", "note": "- Gắn vào sau động từ biểu hiện một hành động nào đó ở vế sau được thực hiện trước hành động được đề cập ở vế trước. \n- Nghĩa tiếng Việt là \"trước khi ...\". \n\n+ 자기 전에 숙제를 합니다.\n+ 밥을 먹기 전에 손을 씻어야 해요. \n+ 고향에 가기 전에 선물을 살 거예요. \n+ 수업 시작하기 전에 커피를 마셔요. \n+ 화장하기 전에 옷을 입어요. \n+ 세수하기 전에 이를 닦아요."}, {"id": "E79", "book": "2", "lesson": "2.7", "topic": "전화", "vocabulary": "", "grammar": "V(으)ㄹ게요.", "note": "- Gắn vào sau động từ, biểu hiện ý chí hoặc sự hứa hẹn của người nói sẽ làm gì. \n(*) Chủ ngữ thường là ngôi thứ nhất. \n+ Khi kết hợp với thân động từ kết thúc bằng nguyên âm thì dùng -ᄅ게요, \n+ kết thúc là phụ âm thì dùng -을게요, \n+ kết thúc bằng ᄅ thì dùng -게요. \n- Nghĩa tiếng Việt là \"sẽ....\". \n\n+ 학교 앞에서 기다릴게요. \n+ 제가 전화를 받을게요. \n\nA : 누가 케이크를 만들 거예요? \nB : 제가 만들게요. \n\n+ 내일은 늦지 않을게요. \n+ 공부를 열심히 할게요. \n+ 영화 표를 제가 예매할게요. \n\nA : 다음에는 누가 발표를 할까요? \nB : 제가 할게요."}, {"id": "E80", "book": "2", "lesson": "2.8", "topic": "영화", "vocabulary": "영화", "grammar": "V/A겠-", "note": "- Gắn vào thân động từ hay tính từ biểu hiện sự dự đoán. \n+ Trong trường hợp gắn với 았/었, là đuôi biểu hiện quá khứ, \n+ hay 시 là đuôi biểu hiện tôn trọng của động từ, thì 겠 gắn vào sau 았/었 và 시. \n\n+ 하늘에 구름이 많아요. 내일 비가 오겠어요. \n+ 선생님은 기쁘시겠다. \n\nA : 어제는 정말 바빴겠어요. \nB : 네, 하지만 지금은 괜찮아요. \n\n+ 정말 맛있겠어요!\n+ 시험을 잘 봐서 좋겠어요."}, {"id": "E81", "book": "2", "lesson": "2.8", "topic": "영화", "vocabulary": "감정", "grammar": "V/A네요.", "note": "- Gắn vào sau thân động từ và tính từ, thể hiện sự cảm thán hay ngạc nhiên của người nói khi biết một sự việc hoàn toàn mới. \n\n+ 한국말을 정말 잘하네요.\n+ 가방이 아주 예쁘네요.\n+ 오늘은 날씨가 춥네요.\n+ 이 옷은 정말 싸네요.\n+ 한국어 시험이 생각보다 어렵네요."}, {"id": "E82", "book": "2", "lesson": "2.8", "topic": "영화", "vocabulary": "", "grammar": "V아/어 + 보다", "note": "- Gắn vào thân động từ, biểu hiện một kinh nghiệm hay thử nghiệm một hành động nào đó. \n- Nghĩa tương đương trong tiếng Việt là ‘thử ...’. \n+ Thân động từ kết thúc bằng nguyên âm ᅡ, ᅩ, dùng. -아 보다, \n+ nếu không phải là.ᅡ, ᅩ dùng. -어 보다. \n+ Động từ kết thúc bằng ...하다, dùng -해 보다. \n\n+ 제주도에 한번 가 보세요. 정말 아름다워요. \n+ 이 사과가 아주 맛있네요. 한번 드셔 보세요. \n\nA : 민준 씨, 바다에서 낚시를 해 봤어요? \nB : 아니요, 하지만 강에서는 해 봤어요."}, {"id": "E83", "book": "2", "lesson": "2.9", "topic": "휴일", "vocabulary": "휴일 - 기념일", "grammar": "N(이)나", "note": "- Gắn vào sau danh từ, biểu hiện sự liệt kê hai đối tượng trở lên và chọn ra một đối tượng trong số đó. \n+ Khi kết hợp với danh từ kết thúc bằng phụ âm thì dùng 이나, \n+ khi kết hợp với danh từ kết thúc bằng nguyên âm thì dùng 나. \n- Nghĩa tiếng Việt là \"... hoặc ...\" \n\n+ 이번 토요일이나 일요일에는 영화를 보려고 해요. \n+ 학교에 갈 때 버스나 지하철을 타요. \n+ 휴일에 산이나 바다로 여행을 갈 거예요."}, {"id": "E84", "book": "2", "lesson": "2.9", "topic": "휴일", "vocabulary": "명절", "grammar": "V/A(으)면 + 좋겠다", "note": "- Gắn vào sau động từ hay tính từ, biểu hiện mong ước cho sự việc ở vế trước xảy ra hoặc hy vọng một việc gì đó xảy ra khác với thực tế. \n+ Với động từ kết thúc bằng phụ âm, kết hợp với -으면 좋겠다, \n+ động từ kết thúc bằng nguyên âm hoặc bằng ᄅ kết hợp với -면 좋겠다. - - Cấu trúc này tương đương với cấu trúc “nếu ... thì tốt” hoặc “ước gì ...” trong tiếng Việt. \n\n+ 저한테 형이 있으면 좋겠어요.\n+ 내일 비가 안 오면 좋겠어요.\n+ 다음 학기에는 학교 기숙사에서 살면 좋겠어요."}, {"id": "E85", "book": "2", "lesson": "2.9", "topic": "휴일", "vocabulary": "", "grammar": "V기 + 위해서 + clause", "note": "- Gắn vào sau động từ, biểu hiện ý đồ hoặc mục đích thực hiện một hành động nào đó. \n- Tương đương với nghĩa “vì ...”, “để ...”, “với mục đích ...” trong tiếng Việt. \n\n+ 김치를 만들기 위해서 배추를 샀어요. \n+ 통역사가 되기 위해서 한국어를 배워요. \n+ 세계 여행을 하기 위해서 돈을 모았어요. \n\n(*) Khi kết hợp với danh từ, cấu trúc này được sử dụng ở dạng 을/를 위해서."}, {"id": "E86", "book": "2", "lesson": "2.10", "topic": "외모", "vocabulary": "외모 묘사", "grammar": "A아/어지다", "note": "- Gắn vào sau thân tính từ thể hiện sự biến đổi của trạng thái. \n- Nghĩa trong tiếng Việt là 'càng ngày càng ...' , ‘trở nên ... hơn’. \n\n(*) Khi kết hợp với động từ, thì mang ý nghĩa là một hành vi nào đó được thực hiện hoặc một động tác nào đó tự nó xảy ra và đạt đến trạng thái như vậy. \n\n+ 흐엉 씨 얼굴이 예뻐졌어요. \n+ 어제보다 기분이 좋아졌어요. \n+ 요즘 날씨가 많이 더워졌어요."}, {"id": "E87", "book": "2", "lesson": "2.10", "topic": "외모", "vocabulary": "색깔", "grammar": "V/A기 + 때문에 + clause", "note": "- Gắn vào sau thân động từ hoặc tính từ, biểu hiện vế trước là nguyên nhân của vế sau. \n(*) Cấu trúc này không sử dụng với câu mệnh lệnh và câu khuyên nhủ. \n\n+ 오늘은 비가 오기 때문에 등산을 안 가요. \n+ 어제 몸이 아팠기 때문에 학교에 못 갔어요. \n+ 외국인이기 때문에 한국말을 잘 못 해요. \n\n(*) Khi kết hợp với danh từ hoặc đại từ thì sử dụng dạng 때문에. \n\n+ 감기 때문에 집에서 쉬어요.  \n+ 요즘 그 일 때문에 아주 바빠요."}, {"id": "E88", "book": "2", "lesson": "2.10", "topic": "외모", "vocabulary": "착탈 동사", "grammar": "ㅎ 불규칙", "note": "+ Trong số các tính từ có thân kết thúc bằng phụ âm ᄒ, những tính từ chỉ màu sắc và tính từ chỉ định khi kết hợp với nguyên âm thì bỏ ᄒ. \n+ Khi kết hợp với -아/어 thì ᄒ bị lược bỏ và chuyển thành ᅢ. \n\n(vd)  빨갛다  :  빨가 + -아요  →  빨개요 \n\n+ 빨간 장미가 예뻐요.\n+ 가을 하늘이 높고 파래요.\n+ 저는 까만색보다 하얀색을 더 좋아해요."}, {"id": "E89", "book": "2", "lesson": "2.11", "topic": "여행", "vocabulary": "여행", "grammar": "V/A거나 + clause", "note": "- Gắn vào sau động từ hay tính từ, \n=> biểu hiện sự lựa chọn một trong hai hoặc nhiều sự vật, trạng thái. \n- Nghĩa trong tiếng Việt là ‘hoặc là, hay là’. \n- Nó cũng được sử dụng sau 이다 và 았 với ý nghĩa ~또는 ~. \n\n+ 부모님께 전화를 하거나 이메일을 보내세요. \n+ 수업이 끝나면 숙제를 하거나 도서관에 가요. \n+ 주말에 집에서 책을 읽거나 친구와 영화를 봐요. \n+ 자기 전에 드라마를 보거나 인터넷을 해요. \n+ 시간이 있을 때 집에서 쉬거나 친구와 쇼핑해요. \n+ 점심 때 비빔밥을 먹거나 라면을 먹어요."}, {"id": "E90", "book": "2", "lesson": "2.11", "topic": "여행", "vocabulary": "여행 준비", "grammar": "V고 + 있다", "note": "- Gắn vào sau động từ, \n=> biểu hiện quá trình đang tiếp diễn của một hành động nào đó. \n- Nghĩa tiếng Việt là ‘đang’. \n- Khi kết hợp với động từ như: 입다 (mặc), 쓰다 (đội), 타다 (cưỡi, lên), nó biểu hiện kết quả của một hành động nào đó được tiếp tục. \n(*) Các đuôi chỉ thời thể không được kết hợp trước 고 mà kết hợp phía sau thân từ 있. (Ví dụ: -고 있었다/-고 있겠다). \n(*) Khi muốn thể hiện sự kính trọng đối với chủ ngữ, cấu trúc này được sử dụng ở dạng -고 계시다. \n\n+ 우리는 한국어를 공부하고 있어요.\n+ 민재 씨가 운동장에서 농구를 하고 있어요. \n+ 아버지께서는 지금 전화를 받고 계세요. \n+ 요즘 테니스를 배우고 있어요.\n+ 동생은 지금 음악을 듣고 있어요. \n+ 할아버지께서는 책을 읽고 계세요. \n\nA : 수빈 씨, 전화를 왜 계속 안 받았어요? \nB : 미안해요. 청소를 하고 있었어요."}, {"id": "E91", "book": "2", "lesson": "2.11", "topic": "여행", "vocabulary": "", "grammar": "V(으)ㄴ + 적이 + 있다/없다", "note": "- Gắn vào sau động từ, thể hiện việc có kinh nghiệm hay trải nghiệm về một việc gì đó trong quá khứ. \n- Khi muốn thể hiện nghĩa chưa có kinh nghiệm về một việc nào đó hoặc chưa trải qua việc nào đó trong quá khứ thì sử dụng dạng -(으)ᄂ 적이 없다. \n- Cấu trúc này tương đương với cấu trúc \"đã từng ...\" / \"chưa từng ...\" trong tiếng Việt. \n\n+ 고등학교 때 그 책을 읽은 적이 있어요. \n+ 저는 민재 씨 동생을 만난 적이 있어요. \n+ 저는 한국에 가 본 적이 없어요. \n+ 아주 많이 운 적이 있어요? \n+ 선생님 질문을 잘못 들은 적이 있어요. \n+ 길에서 외국인을 도와 준 적이 있어요. \n\nA : 불고기를 먹어 본 적이 있어요?\nB : 아니요, 아직 먹어 본 적이 없어요."}, {"id": "E92", "book": "2", "lesson": "2.12", "topic": "공공장소", "vocabulary": "공공장소", "grammar": "V/A(으)면서 + clause", "note": "- Gắn vào thân của động từ để biểu hiện hai hoặc nhiều sự việc đang cùng diễn ra. \n- Tương đương với nghĩa trong tiếng Việt là “vừa ... vừa ...” \n+ Nếu thân động từ kết thúc bằng nguyên âm thì kết hợp với -면서, \n+ kết thúc bằng phụ âm kết hợp với -으면서. \n+ Trường hợp thân động từ kết thúc bằng ᄅ thì kết hợp với -면서. \n\n+ 커피를 마시면서 친구와 이야기를 합니다. \n+ 신문을 읽으면서 아침을 먹습니다. \n+ 청소하면서 음악을 들어요.\n+ 영화가 너무 슬퍼서 울면서 봤어요. \n+ 쓰레기를 주우면서 산책했어요. \n+ 공원을 걸으면서 생각을 합니다."}, {"id": "E93", "book": "2", "lesson": "2.12", "topic": "공공장소", "vocabulary": "", "grammar": "N요", "note": "- Gắn vào sau danh từ, trợ từ, đuôi liên kết để trả lời cho các câu hỏi hoặc khi không cần thiết phải lặp lại lời nói giống nhau tùy theo từng tình huống hội thoại. \n\nA : 어제 어디에 있었어요? \nB : 집에요. \n\nA : 어제 왜 학교에 안 왔어요? \nB : 감기에 걸려서요. \n\nA : 이거 어디에서 샀어요? \nB : 백화점에서요. \n\nA : 누구랑 영화 봤어요? \nB : 지원 씨요.\n\nA : 무슨 영화 봤어요? \nB : 배트맨이요. \n\nA : 언제 집에 돌아왔어요? \nB : 밤 10시요."}, {"id": "E94", "book": "2", "lesson": "2.12", "topic": "공공장소", "vocabulary": "", "grammar": "V/A(으)면 + 안 + 되다", "note": "- Gắn vào thân của động từ, tính từ, \n=> biểu hiện nghĩa cấm đoán ai đó không được làm một việc gì đó. \n+ Nếu thân kết thúc bằng nguyên âm kết hợp với dạng -면 안 되다, \n+ nếu thân từ kết thúc bằng phụ âm, kết hợp với dạng -으면 안 되다. \n+ Đối với trường hợp động, tính từ có thân từ kết thúc bằng ᄅ thì kết hợp với dạng -면 안 되다. \n\n+ 여기서 담배를 피우면 안 됩니다. \n+ 수업 시간에 늦으면 안 됩니다. \n\nA : 기숙사에서 요리를 해도 돼요?\nB : 아니요, 기숙사에서 요리를 하면 안 돼요. \n\n+ 컴퓨터실에서 음료수를 마시면 안 됩니다. \n+ 이 옷은 팔면 안 돼요.\n+ 음악을 들으면 안 됩니다. \n\nA : 미술관에서 사진을 찍어도 됩니까? \nB : 아니요, 사진을 찍으면 안 됩니다."}, {"id": "E95", "book": "2", "lesson": "2.13", "topic": "도시", "vocabulary": "도시", "grammar": "Number(이)나", "note": "- Được sử dụng khi muốn biểu hiện nghĩa nhấn mạnh về số lượng cao hơn mong đợi. \n+ Khi thân động từ kết thúc bằng phụ âm, sử dụng 이나, \n+ với thân động từ kết thúc bằng nguyên âm, sử dụng 나. \n- Tương đương với nghĩa \"tới ..., đến ..., tận ...\" trong tiếng Việt. \n\n+ 커피를 4잔이나 마셨어요.\n+ 장미꽃을 20송이나 샀어요.\n+ 흐엉 씨는 저보다 5살이나 어립니다.\n+ 어제 한국어 공부를 6시간이나 했어요.\n+ 요즘 한국에서는 보통 커피가 5,000원이나 해요. \n\nA : 풍 씨, 1시간이나 늦었어요! \nB : 정말 미안해요."}, {"id": "E96", "book": "2", "lesson": "2.13", "topic": "도시", "vocabulary": "방향", "grammar": "V/A(으)ㄹ 것 같다", "note": "- Được sử dụng khi phỏng đoán một cách mơ hồ, không chắc chắn về một việc gì đó trong quá khứ, hiện tại hoặc tương lai. \n+ Khi thân từ kết thúc bằng phụ âm, sử dụng dạng -을 것 같다, \n+ với thân từ kết thúc bằng nguyên âm, sử dụng dạng -ᄅ 것 같다. \nCấu trúc này tương đương với nghĩa \"hình như ..., có lẽ ...\" trong tiếng Việt. \n\n+ 저 분은 선생님일 것 같아요. \n+ 내일은 비가 안 올 것 같아요. \n+ 이제 어머니의 마음을 알 것 같아요. \n+ 케이크가 정말 맛있을 것 같아요. \n+ 저 사람은 중국 사람일 것 같아요. \n+ 히엔 씨는 시험 때문에 내일 도서관에 갈 것 같아요."}, {"id": "E97", "book": "2", "lesson": "2.13", "topic": "도시", "vocabulary": "", "grammar": "ㅅ 불규칙", "note": "1.  Những động từ có thân từ kết thúc bằng phụ âm ᄉ như 낫다, 짓다, 붓다, 젓다, khi kết hợp với nguyên âm, phụ âm thì ᄉ bị mất đi. \n2.  Nhưng những động từ 씻다, 웃다, 벗다 khi kết hợp với nguyên âm, phụ âm thì ᄉ không bị mất đi mà vẫn được giữ nguyên. \n(vd)  낫다 : 낫 + 아요 → 나아요 \n\n+ 약을 먹고 감기가 나았어요. \n+ 얼굴이 좀 부었어요.\n+ 풍 씨는 항상 웃어요.\n+ 여기에는 쇼핑센터를 지을 거예요. \n+ 커피를 잘 저어서 드세요. \n+ 더우니까 코트를 좀 벗으세요."}, {"id": "E98", "book": "2", "lesson": "2.14", "topic": "계획", "vocabulary": "학업", "grammar": "V(으)ㄴ + 지 + time(이/가) + 되다 / 지나다 / 흐르다 / 넘다", "note": "- Gắn vào sau động từ, biểu hiện khoảng thời gian đã trải qua sau khi thực hiện một việc nào đó. \n+ Khi kết hợp với thân động từ kết thúc bằng nguyên âm, sử dụng dạng -ᄂ 지, \n+ Với thân động từ kết thúc bằng phụ âm, sử dụng dạng -은 지. \n- Dạng biểu hiện thường hay được sử dụng nhất là -(으)ᄂ 지 (thời gian) 되다. \n- Dịch \"đã làm gì ... được bao lâu ...\"\n\n+ 한국어를 배운 지 육 개월이 됐습니다. \n+ 점심을 먹은 지 두 시간쯤 됐어요. \n+ 고등학교를 졸업한 지 벌써 십 년이 됐습니다. \n+ 한국 노래를 안 들은 지 일 년이 지났습니다. \n+ 여기에서 산 지 삼 개월쯤 됐어요. \n+ 담배를 안 피운 지 사 년이 지났습니다."}, {"id": "E99", "book": "2", "lesson": "2.14", "topic": "계획", "vocabulary": "직업", "grammar": "V(으)ㄴ + 후에 + clause", "note": "- Gắn vào sau động từ, biểu hiện nghĩa một hành động nào đó được thực hiện sau một hành động khác. \n+ Khi kết hợp với động từ có thân từ kết thúc bằng nguyên âm, sử dụng dạng -ᄂ 후에, \n+ với động từ có thân từ kết thúc bằng phụ âm sử dụng dạng -은 후에. \n- Nghĩa là \"sau khi ...\"\n\n+ 점심을 먹은 후에 차를 마셨습니다.\n+ 수업이 끝난 후에 친구를 만났어요.\n+ 졸업한 후에 한국에 가려고 합니다.\n+ 세수를 한 후에 옷을 입습니다.\n+ 친구의 이야기를 들은 후에 생각해 보겠습니다. \n+ 샌드위치를 만든 후에 우유랑 먹었습니다. \n\n(*) Có thể sử dụng cấu trúc -(으)ᄂ 다음에 để biểu hiện ý nghĩa tương tự.\n\n예) 점심을 먹은 다음에 차를 마셨습니다."}, {"id": "E100", "book": "2", "lesson": "2.14", "topic": "계획", "vocabulary": "직장", "grammar": "V기로 + 하다", "note": "- Gắn vào sau động từ để biểu hiện nghĩa hứa hẹn hoặc quyết tâm, quyết định làm một việc gì đó. \n- Thường được sử dụng ở dạng -기로 했다. \n\n+ 내년에 한국에 가기로 했어요.\n+ 내일부터 운동을 열심히 하기로 했습니다. \n+ 학교 앞에서 만나기로 해요.\n+ 주말에 가족들과 식사를 하기로 해서 시간이 없을 것 같아요. \n\nA : 지원 씨랑 영화 보기로 했는데 같이 갈래요?\nB : 아, 저는 어머니랑 백화점에 가기로 했어요.\n\nA : 민재 씨, 우리가 언제 밥 먹기로 했지요? \nB : 저녁 6시에 먹기로 했어요."}, {"id": "E101", "book": "2", "lesson": "2.15", "topic": "한국 생활", "vocabulary": "한국 생활", "grammar": "Sb에게서, Sb한테서", "note": "- Gắn vào sau danh từ, thể hiện điểm xuất phát. \n- Đặc biệt, cấu trúc này có thể dùng để chỉ xuất xứ. \n+ 한테서 chủ yếu được sử dụng trong văn nói. \n+ Dạng lược bỏ 서 như 에게, 한테 cũng được sử dụng nhiều. \n\n+ 동생에게(서) 선물을 받았습니다.\n+ 고향 친구한테(서) 전화가 왔습니다.\n+ 그 이야기는 친구에게(서) 들었어요. \n+ 언니에게(서) 이메일을 받았어요. \n+ 선생님께 책을 빌렸습니다.\n+ 제 생일날 부모님께 용돈을 받았습니다. \n\nTrong trường hợp đối tượng cần phải kính trọng, sử dụng 께 thay cho 에게서, 한테서. \n\n예) 어머니께 전화를 받았어요."}, {"id": "E102", "book": "2", "lesson": "2.15", "topic": "한국 생활", "vocabulary": "집 구하기", "grammar": "A(으)ㄴ/V는데 + clause", "note": "- Gắn vào sau động từ, tính từ, sử dụng khi đưa ra trước một nội dung có liên quan tới nội dung định đề cập tới. \n- Đặc biệt, cấu trúc này thường được sử dụng khi đưa ra một bối cảnh trước khi đưa ra một đề nghị, yêu cầu nào đó. \n+ Khi kết hợp với động từ hoặc 있다, 없다, sử dụng dạng -는데, \n+ khi kết hợp với tính từ, sử dụng dạng -(으)ᄂ데. \n+ Trong trường hợp biểu hiện thời quá khứ, sử dụng dạng -았/었는데. \n\n+ 한국말을 잘 모르는데 이것 좀 가르쳐 주세요. \n+ 날씨가 좋은데 공원에 놀러 갈까요? \n+ 숙제가 어려운데 좀 도와주세요. \n+ 어제 백화점에 갔는데 영화배우를 봤어요. \n+ 방학 때 가족과 같이 여행했는데 정말 즐거웠어요. \n+ 선생님, 질문이 있는데 좀 가르쳐 주시겠어요? \n\n(*) Cấu trúc này cũng có thể được sử dụng khi nói tới hai sự thật đối lập nhau hoặc một tình huống hay kết quả ở phía sau diễn ra ngược với sự thật phía trước. \n\n+ 밥을 먹었는데 배가 고파요. \n+ 동생은 키가 큰데 저는 키가 작아요."}, {"id": "E103", "book": "2", "lesson": "2.15", "topic": "한국 생활", "vocabulary": "", "grammar": "르 불규칙", "note": "1.  Những động từ có thân từ kết thúc bằng 르 khi kết hợp với các từ sau đó bắt đầu bằng 아/어 như -아/어요, -아/어서 thì nguyên âm ᅳ bị lược bỏ và thêm vào ᄅ. \n2.  Nếu nguyên âm trước 르 là ᅡ, ᅩ thì kết hợp với -아요, nếu là các nguyên âm khác thì kết hợp với -어요. \n\n(vd)  모르다 : 몰ᄅ + 아요 → 몰라요 \n         부르다 : 불ᄅ + 어요 → 불러요 \n\n+ 다 함께 생일 축하 노래를 불렀어요. \n+ 저와 동생은 성격이 달라요.\n+ 길이 막히면 택시보다 지하철이 빨라요. \n+ 어제 미용실에서 머리를 잘랐어요. \n+ 제 친구는 강아지를 한 마리 길러요. \n+ 저는 한국어를 전혀 몰랐지만 지금은 조금 알아요."}, {"id": "E104", "book": "3", "lesson": "3.1", "topic": "학교 생활", "vocabulary": "수업", "grammar": "N밖에 + mệnh đề phủ định", "note": "- Đứng sau danh từ hoặc phó từ, \n- nghĩa tiếng Việt là 'chỉ ... ; ngoài ... ra ... không còn'. \n=> Thể hiện trường hợp không thể có lựa chọn hoặc khả năng nào khác, mà chỉ còn đó là sự lựa chọn duy nhất. \n+ Khác với 만 (chỉ), -밖에 chỉ đứng trong câu phủ định, \n+ trong khi 만 (chỉ) có thể đứng trong cả câu phủ định và câu khẳng định. \n\n+ 시험 시간이 5분밖에 안 남았어요. \n+ 보고서를 제출한 사람이 반밖에 안 돼요. \n+ 이번 시험에서 한 개밖에 안 틀렸어요. \n\nA : 볼펜 좀 빌려 주세요.\nB : 저도 볼펜이 하나밖에 없어요. 미안해요. \n\nA : 왜 그렇게 안 먹어요?\nB : 긴장이 돼서 조금밖에 못 먹겠어요."}, {"id": "E105", "book": "3", "lesson": "3.1", "topic": "학교 생활", "vocabulary": "대학 생활", "grammar": "N(이)라고 + 하다", "note": "- Đứng sau danh từ, được dùng khi người nói giới thiệu mình hay giới thiệu người khác với một người nào đó, \n- nghĩa tiếng Việt là 'là ...' hay 'được gọi là ...'. \n- Cũng có thể sử dụng khi nói về tên đồ vật . \n+ Dùng 라고 sau nguyên âm, \n+ dùng 이라고 sau phụ âm. \n\n+ 처음 뵙겠습니다. 저는 흐엉이라고 합니다. \n+ 이 사람은 제 친구 조민재라고 해요.\n+ ‘전공’을 베트남 말로 ‘쭈이엔 몬’이라고 해요. \n\nA : 한국말로 이것을 뭐라고 해요? \nB : ‘지하철’이라고 해요. \n\nA : 유진 씨가 다니는 회사 이름이 뭐예요? \nB : ‘한국상사’라고 하는 회사예요."}, {"id": "E106", "book": "3", "lesson": "3.1", "topic": "학교 생활", "vocabulary": "학교 행사", "grammar": "V/A게 + 되다", "note": "- Đứng sau động từ hoặc tính từ. \n- Trong tiếng Việt nghĩa là 'được, bị, trở nên', \n- thể hiện sự thay đổi sang một tình trạng khác hoặc dẫn tới một tình trạng nào đó do hoàn cảnh khách quan khác với mong muốn và ý chí của chủ ngữ. \n\n+ 이번 학기에는 장학금을 받게 됐어요. \n+ 컴퓨터 게임을 시작하면 계속하게 돼요. \n+ 건강이 나빠져서 운동을 하게 됐어요. \n\nA : 언제부터 아르바이트를 하게 됐어요? \nB : 지난 달부터 하게 됐어요. \n\nA : 풍 씨는 김치를 잘 먹어요?\nB : 네, 처음에 못 먹었는데 이제는 잘 먹게 됐어요."}, {"id": "E107", "book": "3", "lesson": "3.1", "topic": "학교 생활", "vocabulary": "", "grammar": "V(으)ㄹ + 생각이다", "note": "- Đứng sau động từ, \n- có nghĩa là 'định' hoặc 'có ý định ...', 'muốn ...' , \n=> thể hiện kế hoạch, ý định hay mục đích. \n+ Dùng -ᄅ 생각이다 sau nguyên âm hoặc phụ âm ᄅ; \n+ dùng -을 생각이다 sau phụ âm. \n\n+ 책을 찾으러 도서관에 갈 생각이에요.\n+ 수업 후에 점심을 먹을 생각이에요. \n+ 저는 대학원에 진학할 생각인데 조언 좀 해 주세요. \n\nA : 이번에 무슨 수업을 들을 거예요?\nB : 한국의 현대 문화 수업을 들을 생각이에요. \n\nA : 졸업 후 계획이 있어요?\nB : 저는 부모님 일을 도울 생각이에요."}, {"id": "E108", "book": "3", "lesson": "3.2", "topic": "대인 관계", "vocabulary": "대인 관계", "grammar": "V는 + 길이다", "note": "- Chủ yếu được dùng gắn vào động từ 가다 hay 오다 \n=> để biểu hiện ý nghĩa 'đang làm việc gì'. \n- Ngoài ra còn được dùng với các động từ có gốc 가다, 오다 như các động từ 나가다, 나오다, 들어가다, 들어오다, 내려가다, 내려오다, 올라가다, 올라오다 và 출근하다, 퇴근하다. \n(*) Khi được dùng dưới dạng -는 길에 thì có nghĩa là 'trong khi đang đi, đang đến hoặc trong dịp.’ \n\n+ 지금 모임에 가는 길이에요.\n+ 친구를 만나러 시내에 가는 길이에요.\n+ 집에 돌아오는 길에 서점에 가서 책을 샀어요. \n\nA : 지금 어디에 가세요?\nB : 회식이 있어서 약속 장소로 가는 길이에요. \n\nA : 시간 있으면 오늘 우리 사무실에 잠깐 들르세요. \nB : 네, 퇴근하는 길에 잠깐 들를게요."}, {"id": "E109", "book": "3", "lesson": "3.2", "topic": "대인 관계", "vocabulary": "부탁과 거절", "grammar": "V(으)ㄴ + 덕분에 + clause", "note": "- Đứng sau động từ với nghĩa \"nhờ vào ..., nhờ có ...\" \n=> nhằm thể hiện hành vi vế trước chính là nguyên nhân hay lý do của tình huống ở vế sau. \n+ Khi kết hợp với động từ tận cùng bằng ᄅ và nguyên âm dùng -ᄂ 덕분에, \n+ với các động từ kết thúc bằng các phụ âm khác dùng -은 덕분에, \n+ với các danh từ thì dùng 덕분에. \n\n+ 흐엉 씨가 도와준 덕분에 일이 잘 끝났습니다.\n+ 선생님께서 잘 가르쳐 주신 덕분에 한국어 실력이 좋아졌습니다. \n+ 선생님 덕분에 한국 생활을 무사히 마칠 수 있었습니다. \n\nA : 잘 지내고 계시지요?\nB : 네, 걱정해 주신 덕분에 잘 지내고 있습니다. \n\nA : 교수님께서 추천해 주신 덕분에 이번에 취직을 했습니다. 감사합니다. \nB : 흐엉 씨가 열심히 공부한 덕분이지요. 축하합니다. \n\n(*) 덕분에được dùng khi diễn đạt nguyên nhân mang lại kết quả tốt trong khi   때문에cũng được sử dụng khi diễn đạt nguyên nhân mang lại kết quả không tốt. \n예)  \n       친구 때문에 숙제를 못 했어요. (○) \n       친구 덕분에 숙제를 못 했어요. (×)"}, {"id": "E110", "book": "3", "lesson": "3.2", "topic": "대인 관계", "vocabulary": "안부", "grammar": "V나요 / A(으)ㄴ가요?", "note": "- Được gắn vào sau động từ hoặc tính từ, là mẫu câu hỏi lịch sự, tôn trọng người nghe. \n+ Đối với thì hiện tại dùng -나요? cho động từ , dùng -(으)ᄂ가요? cho tính từ. \n+ Đối với thì quá khứ dùng -았/었나요? cho cả động từ và tính từ. \n+ Đối với thì tương lai dùng -(으)ᄅ 건가요? cho cả động từ và tính từ. \n\n+ 이번 모임에 오시나요?\n+ 요즘도 많이 바쁘신가요?\n+ 요즘 베트남 사람들은 무슨 노래를 좋아하나요? \n\nA : 한국에 언제 오셨나요? \nB : 작년에 한국에 왔습니다. \n\nA : 언제부터 한국어를 배우셨나요? \nB : 대학교 1학년 때부터 배웠습니다."}, {"id": "E112", "book": "3", "lesson": "3.3", "topic": "건강", "vocabulary": "건강", "grammar": "V는 + 게 + 좋다", "note": "- Đứng sau động từ hay sau 있다, 없다, \n- nghĩa tiếng Việt là “tốt” “...thì tốt\", \"nên làm gì ...\" \n=> thể hiện ý làm điều gì đó sẽ tốt, là cách viết rút gọn của -는 것이 좋다. \n=> Thường dùng để khuyên người khác, tuy nhiên khi dùng -는 게 좋다 sẽ cho người nghe cảm giác hơi võ đoán, còn dùng -는 게 좋겠다 thì sẽ tạo nên cảm giác như của một lời khuyên thận trọng. \n\n+ 지금 가는 게 좋겠어요. \n+ 열이 날 때는 병원에 가는 게 좋아요. \n+ 피곤할 때는 집에 가서 쉬는 게 좋아요. \n\nA : 언제 만나는 게 좋을까요?\nB : 토요일에 만나는 게 좋겠어요. \n\nA : 컴퓨터가 고장나서 지금 김 선생님께 메일을 드릴 수 없어요. \nB : 그럼 빨리 김 선생님께 전화를 드리는 게 좋겠습니다."}, {"id": "E113", "book": "3", "lesson": "3.3", "topic": "건강", "vocabulary": "피로", "grammar": "A아/어 + 보이다", "note": "- Đứng sau tính từ và thể hiện ý phán đoán về một hiện tượng nào đó, có nghĩa là ‘trông có vẻ ...'\n\n+ 이 책은 아주 어려워 보여요. \n+ 이 교실은 좁아서 좀 답답해 보여요. \n+ 지원 씨는 대학생인데 너무 어려 보여요. \n\nA : 루이엔 씨가 많이 힘들어 보이는데 괜찮을까요?\nB : 루이엔 씨가 요즘 많이 바빴어요. 좀 쉬면 좋아질 거예요. \n\nA : 무슨 색 옷을 입을까요?\nB : 날씬해 보이고 싶으면 검은색 옷을 입으세요."}, {"id": "E114", "book": "3", "lesson": "3.3", "topic": "건강", "vocabulary": "휴식", "grammar": "A(으)ㄴ/V는 + 것 + 같다", "note": "- Đứng sau thân từ của tính từ hay động từ, \n- có nghĩa là 'hình như ..., có vẻ ..., dường như ..., chắc là ...' \n=> để diễn tả sự suy đoán về một việc nào đó xảy ra hoặc đang ở trạng thái nào đó. \n- Thường dùng khi nói lên suy nghĩ hoặc ý kiến của mình một cách nhẹ nhàng, cho cảm giác khiêm tốn. \n+ Những tính từ kết thúc bằng nguyên âm hay phụ âm ᄅ hoặc sau thân từ 이다, 아니다thì dùng -ᄂ 것 같다, \n+ các phụ âm khác thì dùng -은 것 같다. \n+ Riêng trường hợp kết thúc là 있다, 없다 thì dùng -는 것 같다. \n\n+ 최정우 씨가 많이 아픈 것 같아요. \n+ 유진 씨가 감기에 걸려서 집에서 쉬는 것 같아요. \n+ 저 사람은 학생인 것 같아요. \n\nA : 정우씨, 안색이 안 좋은데 무슨 일이 있어요? \nB : 어제 잠을 못 자서 그런 것 같아요. \n\nA : 기분이 좋은 것 같은데 무슨 좋은 일 있어요? \nB : 오늘 베트남에서 부모님과 여자친구가 와요."}, {"id": "E115", "book": "3", "lesson": "3.4", "topic": "쇼핑", "vocabulary": "의복", "grammar": "N + 대신(에) + clause", "note": "- Đứng sau danh từ, \n- biểu hiện nghĩa “thay vì ..., thay cho ..., thay vào đó ...”\n+ Được dùng khi thể hiện ý thay thế cho vị trí, đối tượng hoặc công việc mà đối tượng nào đó sẽ làm. \n+ Khi sử dụng trong câu, 에 có thể được giản lược. \n\n+ 커피 대신(에) 우유로 주세요.\n+ 선물 대신(에) 용돈을 보냈어요. \n+ 치마 대신(에) 바지로 교환해 주세요. \n\nA : 주스를 살까요?\nB : 주스 대신(에) 커피를 삽시다. \n\nA : 등산갈 때 청바지를 입어도 돼요?\nB : 아니요, 청바지는 불편하니까 청바지 대신(에) 등산복을 입으세요."}, {"id": "E116", "book": "3", "lesson": "3.4", "topic": "쇼핑", "vocabulary": "사이즈", "grammar": "A(으)ㄴ/V는 + 대신(에) + clause", "note": "- Đứng sau động từ hoặc tính từ, \n- biểu hiện nghĩa “thay vì...., thay cho...., thay bởi...., thay vào đó.......”. \n- Được sử dụng để biểu hiện nghĩa hành động ở vế trước không được thực hiện mà được chuyển thành một hành động khác hoặc một trạng thái khác với trạng thái ở vế trước. \n- Cấu trúc này cũng được sử dụng khi biểu hiện sự đền bù, bồi thường một thứ khác tương ứng với nội dung ở vế trước. \n- Khi sử dụng trong câu, 에 có thể được giản lược. \n+ Sử dụng dạng -ᄂ 대신에 với tính từ kết thúc bằng nguyên âm; \n+ sử dụng -은 대신에 với tính từ kết thúc bằng phụ âm \n+ và -는 대신에 khi kết hợp với động từ. \n\n+ 음악회에 가는 대신(에) 영화를 보는 게 좋겠어요. \n+ 그 옷은 싼 대신(에) 품질이 좋지 않아요.\n+ 제가 늦은 대신(에) 맛있는 음식을 사 드릴게요. \n\nA : 그 가게는 가까워서 물건 살 때 편하지요?\nB : 맞아요. 하지만 가까운 대신(에) 좀 비싼 것 같아요. \n\nA : 화씨,이 일 좀 도와주세요.\nB : 그럼 제가 도와주는 대신(에) 커피 한잔 사세요."}, {"id": "E117", "book": "3", "lesson": "3.4", "topic": "쇼핑", "vocabulary": "교환 / 환불", "grammar": "V/A기는 + 하다 … + clause", "note": "- Đứng sau động từ hoặc tính từ \n=> để biểu hiện ý nghĩa đồng tình với ý kiến của đối phương được nói tới ở vế trước nhưng vế sau lại đưa ra sự phủ định về một điều gì đó. \n- Trong tiếng Việt, cấu trúc này tương đương với biểu hiện “ ... thì cũng  ...  nhưng (mà) ...”. \n\n+ 마음에 들기는 하지만 좀 비싸요.\n+ 식사를 하기는 했는데 또 배고파요. \n+ 이 바지가 예쁘기는 하지만 허리가 좀 큰 것 같아요. \n\nA : 한국어 공부가 재미있지요?\nB : 재미있기는 하지만 좀 어려워요. \n\nA : 친구를 만나서 재미있게 보내셨어요?\nB : 만나기는 했지만 시간이 없어서 금방 헤어졌어요."}, {"id": "E119", "book": "3", "lesson": "3.5", "topic": "요리", "vocabulary": "음식", "grammar": "V고 + 나서 + clause", "note": "- Đứng sau động từ với nghĩa là “xong rồi thì ...” \n=> biểu hiện hành động ở vế sau được thực hiện sau khi hành động ở vế trước hoàn thành. \n- So với cấu trúc -고, trạng thái hoàn thành của hành động ở vế trước được nhấn mạnh hơn. \n\n+ 국을 끓이고 나서 밥을 지으세요. \n+ 쇠고기를 볶고 나서 채소를 넣으세요. \n+ 설명을 다 듣고 나서 질문하세요. \n\nA : 오징어를 썬 후에 어떻게 해요?\nB : 오징어를 썰고 나서 프라이팬에 넣으세요. \n\nA : 숙제 다 했어요?\nB : 아니요, TV를 보고 나서 숙제를 할 거예요."}, {"id": "E120", "book": "3", "lesson": "3.5", "topic": "요리", "vocabulary": "한국 음식", "grammar": "N(으)로", "note": "- Là tiểu từ được gắn vào sau danh từ biểu hiện nghĩa “bằng ...” \n=> chỉ phương tiện, dụng cụ, nguyên liệu....\n+ Khi kết hợp với danh từ tận cùng là nguyên âm hoặc phụ âm ᄅ, thì sử dụng dạng 로, \n+ với các danh từ tận cùng là phụ âm thì sử dụng dạng 으로. \n\n+ 삼계탕은 닭과 인삼으로 만듭니다.\n+ 숟가락과 젓가락으로 음식을 먹습니다.\n+ 닭 가슴살로 만든 음식은 칼로리가 낮아 다이어트에 좋습니다. \n\nA : 잡채를 만드는 재료가 뭐예요?\nB : 쇠고기, 당면과 여러가지 채소로 만들어요. \n\nA : 계산이 안 맞는 것 같은데요.\nB : 그럼 이 계산기로 확인해 보세요."}, {"id": "E121", "book": "3", "lesson": "3.5", "topic": "요리", "vocabulary": "요리", "grammar": "V다가 + clause", "note": "- Đứng sau động từ thể hiện ý nghĩa một hành động nào đó đang được thực hiện thì bị dừng lại và chuyển sang một hành động khác. \n(*) Chủ ngữ ở hai vế của câu có sử dụng -다가 phải giống nhau. \n\n+ 쇠고기를 볶다가 야채를 넣으세요. \n+ 된장찌개를 끓이다가 두부를 넣으세요. \n+ 학교에 가다가 친구를 만났어요. \n\nA : 손을 왜 다쳤어요?\nB : 감자를 볶다가 기름이 튀어서 데었어요. \n\nA : 지원 씨를 어디에서 봤어요? \nB : 과사무실에 가다가 봤어요. \n\n(*) Cấu trúc này có thể kết hợp với một số tính từ để biểu hiện ý nghĩa trạng thái ở vế trước bị dừng lại và chuyển đổi thành trạng thái ở vế sau. \n예)  날씨가 맑다가 갑자기 흐려졌어요. \n       밖이 조용하다가 점점 시끄러워졌어요."}, {"id": "E122", "book": "3", "lesson": "3.5", "topic": "요리", "vocabulary": "", "grammar": "V/A게  =>  Adverb", "note": "- Đứng sau tính từ và một số động từ thể hiện mức độ, phương thức của hành động, trạng thái ở vế sau. \n- Tính từ hoặc động từ khi kết hợp với đuôi này thường được sử dụng như một phó từ làm trạng ngữ cho động từ mà nó bổ nghĩa. \n\n+ 맛있게 드세요.\n+ 한국 사람들은 맵게 먹어요. \n+ 글씨를 예쁘게 쓰세요. \n\nA : 커피를 어떻게 탈까요?\nB : 저는 좀 연하게 타 주세요. \n\nA : 제 말을 이해하셨어요?\nB : 아니요, 잘 모르겠어요. 좀 더 쉽게 설명해 주세요."}, {"id": "E123", "book": "3", "lesson": "3.6", "topic": "은행", "vocabulary": "화폐", "grammar": "V기 + 쉽다", "note": "- Đứng sau động từ với ý nghĩa là “dễ ...” \n=> Biểu hiện ý nghĩa dễ dàng thực hiện một hành động nào đó hoặc có nhiều khả năng hoặc có khuynh hướng xảy ra trạng thái, tình hình nào đó. \n- Sau -기 thường dùng tiểu từ 가. \n\n+ 비밀번호는 메모하지 않으면 잊어버리기 쉬워요. \n+ 단 음식을 많이 먹으면 충치가 생기가 쉬워요. \n+ 옷을 얇게 입고 다니면 감기에 걸리기 쉬워요. \n\nA : 신용카드를 만들면 과소비하기 쉽겠지요? \nB : 맞아요. 신용카드는 안 쓰는 게 좋아요. \n\nA : 그렇게 잠을 못 자면 몸살 나기 쉬워요. \nB : 그래서 좀 일찍 집에 가려고 해요."}, {"id": "E124", "book": "3", "lesson": "3.6", "topic": "은행", "vocabulary": "은행", "grammar": "V는 + 동안 + clause", "note": "- Đứng sau động từ hoặc 있다, 없다 để thể hiện ý nghĩa “trong lúc ...”. \n=> Thể hiện thời gian mà hành động hoặc trạng thái nào đó đựợc duy trì liên tục. \n- Sau -는 동안 thường dùng với tiểu từ 에. \n\n+ 은행에서 번호표를 뽑고 기다리는 동안 커피 한잔 드세요. \n+ 어머니께서 주무시는 동안 제가 설거지를 했어요.\n+ 여기 있는 동안 저는 아주 편하게 생활했습니다. \n\nA : 신분증을 복사하는 동안 신청서를 작성해 주세요. \nB : 네, 그런데 도장 대신 사인해도 되지요? \n\nA : 베트남 여행을 도와주셔서 감사합니다.\nB : 베트남에 계시는 동안 편하게 지내시면 좋겠어요."}, {"id": "E125", "book": "3", "lesson": "3.6", "topic": "은행", "vocabulary": "은행 업무", "grammar": "V(으)려면 + clause", "note": "- Đứng sau động từ biểu hiện ý nghĩa “nếu muốn ..., nếu có ý định ...”. \n- Sử dụng khi giả định trường hợp có ý định hoặc ý tưởng làm một việc gì đó. \n+ Sau nguyên âm hoặc có phụ âm cuối ᄅ thì dùng 려면, \n+ sau động từ có phụ âm cuối thì dùng 으려면. \n\n+ 송금을 하려면 계좌 번호를 알아야 해요. \n+ 현금카드로 돈을 찾으려면 비밀번호를 알아야 해요. \n+ 주말에 쉬려면 평일에 부지런히 일하세요. \n\nA : 통장을 만들고 싶은데 뭐가 필요해요? \nB : 통장을 만들려면 도장과 신분증이 필요해요. \n\nA : 사장님을 만나고 싶은데요. \nB : 사장님을 만나시려면 오후에 다시 오세요. \n\n(*) Trong trường hợp kết hợp với động từ không thể hiện ý đồ hay ý định thì có thể dùng cho giả định tình huống xảy ra trong tương lai. \n예)  그 책이 나오려면 한 달쯤 더 걸릴 거예요. \n       컴퓨터가 켜지려면 시간이 좀 걸리니까 기다리세요."}, {"id": "E126", "book": "3", "lesson": "3.7", "topic": "성격", "vocabulary": "성격", "grammar": "N처럼  =  N같이", "note": "- Đứng sau danh từ để biểu hiện đối tượng so sánh. \n- Nghĩa tiếng Việt là “như ..., giống như ...” biểu hiện mức độ giống nhau hoặc đồng nhất với danh từ đứng trước nó. \n- Có thể thay thế bằng tiểu từ 같이. \n\n+ 지훈 씨는 운동선수처럼 운동을 잘해요. \n+ 민준 씨 딸도 아빠처럼 사교적이에요. \n+ 주인 아주머니가 어머니처럼 잘해 주세요. \n\nA : 유진 씨가 피아노 치는 거 봤어요? 저는 정말 놀랐어요. \nB : 네, 피아노를 전공한 사람처럼 잘 치지요? \n\nA : 화 씨, 한국말을 참 잘하네요.\nB : 고마워요. 그렇지만 한국 사람처럼 말하려면 아직 멀었어요."}, {"id": "E127", "book": "3", "lesson": "3.7", "topic": "성격", "vocabulary": "사람의 특성", "grammar": "V는/A군요", "note": "- Đứng sau động từ hoặc tính từ, \n- nghĩa tiếng Việt là “...thế!, ... thế cơ à!”, \n=> được sử dụng khi biểu hiện cảm thán đối với một sự thật nào đó mới mẻ hoặc có cảm giác ngạc nhiên. \n+ Sau tính từ thì dùng -군요, \n+ sau động từ thì dùng -는군요. \n+ khi nói đến sự việc trong quá khứ thì dùng -았/었군요. \n+ Khi phỏng đoán một việc gì đó thì dùng -겠군요. \n\n+ 베트남에는 한국어를 공부하는 학생이 참 많군요. \n+ 지훈 씨는 정말 잘 먹는군요.\n+ 서영 씨, 요즘 일이 많아서 피곤하겠군요. \n\nA : 남 씨는 한 학기 동안 지각이나 결석을 한 번도 안 했어요. \nB : 우와, 남 씨는 정말 성실하군요. \n\nA : 전에 한국에서 공부할 때 김치찌개를 자주 먹었어요. \nB : 어머, 루이엔 씨는 한국에서 공부했군요. \n\nKhi nói với người dưới mình hoặc với bạn bè, hoặc khi nói một mình thì dùng 구나. \n예)  민재는 정말 잘 먹는구나. \n       내가 공부를 많이 했구나."}, {"id": "E128", "book": "3", "lesson": "3.7", "topic": "성격", "vocabulary": "신체 관련 관용 표현", "grammar": "A(으)ㄴ/V는 + 편이다", "note": "- Đứng sau động từ và tính từ, \n- nghĩa tiếng Việt là “vào loại ..., thuộc diện ....”, \n=> biểu hiện đại thể thuộc vào một loại nào đó.\n+ Với tính từ tận cùng là nguyên âm hoặc tận cùng là phụ âm ㄹ, hoặc sau 이다, 아니다 thì dùng -ᄂ 편이다, tận cùng là phụ âm thì dùng -은 편이다. \n+ Sau động từ hoặc sau 있다, 없다 thì dùng -는 편이다. \n\n+ 제 동생은 조금 소극적인 편이에요. \n+ 그 사람은 말이 많은 편이에요. \n+ 저는 사람을 쉽게 사귀는 편이에요. \n\nA : 고민이 있을 때 그 친구와 자주 이야기해요? \nB : 네, 우리는 대화가 잘 통하는 편이라서요. \n\nA : 루이엔 씨는 어떤 사람이 좋아요? \nB : 제가 조용한 편이니까 활발하고 명랑한 사람을 만나고 싶어요."}, {"id": "E129", "book": "3", "lesson": "3.8", "topic": "실수", "vocabulary": "실수", "grammar": "V는 + 바람에 + clause", "note": "- Đứng sau động từ để biểu hiện ý nghĩa nguyên nhân hoặc lý do dẫn đến xảy ra một tình huống ở vế sau, \n- trong tiếng Việt có nghĩa là “bởi ..., do ...” \n- Cấu trúc này thường được sử dụng khi một tình huống nào đó phát sinh ngoài dự kiến và gây ảnh hưởng tiêu cực đến hành động ở vế sau. \n(*) Vế sau không được sử dụng ở dạng câu mệnh lệnh hoặc thỉnh dụ. \n\n+ 지갑을 놓고 오는 바람에 다시 학교로 가는 길이에요.\n+ 갑자기 컴퓨터가 고장 나는 바람에 이메일을 확인하지 못했어요. \n+ 비가 오는 바람에 옷이 다 젖었어요. \n\nA : 왜 이렇게 늦었어요?\nB : 미안해요. 지하철을 잘못 타는 바람에 늦었어요. \n\nA : 야유회는 잘 다녀오셨어요?\nB : 못 갔어요. 비가 오는 바람에 모임이 취소되었어요."}, {"id": "E130", "book": "3", "lesson": "3.8", "topic": "실수", "vocabulary": "사과", "grammar": "V는 + 중이다", "note": "- Là biểu hiện thường đứng sau động từ thể hiện một thời điểm trong quá trình của hành động nào đó đang được tiến hành, \n- tương ứng với nghĩa tiếng Việt là “đang ..., đang trong quá trình ...”. \n- Với trường hợp danh từ + 중이다. \n\n+ 숙제를 안 가지고 와서 집으로 돌아가는 중이에요. \n+ 시험 보는 중에 전화가 왔어요.\n+ 회의 중에 커피를 쏟았어요. \n\nA : 흐엉 씨, 어디에 가요?\nB : 문제가 생겨서 학교 사무실로 가는 중이에요. \n\nA : 김 교수님 좀 바꿔 주시겠어요?\nB : 교수님께서는 지금 회의 중이십니다."}, {"id": "E131", "book": "3", "lesson": "3.8", "topic": "실수", "vocabulary": "기억", "grammar": "V도록 + 하다", "note": "- Đứng sau động từ thể hiện ý nghĩa sai khiến hoặc làm cho người khác làm một việc gì đó, \n- tương đương với nghĩa “làm cho ..., khiến cho ..., sai / bảo ai đó làm gì ....”\n+ Khi sử dụng -도록 하다 ở dạng câu mệnh lệnh hoặc thỉnh dụ   -도록 하세요 : nó thể hiện nghĩa yêu cầu hoặc đề nghị đối phương làm một việc gì đó. \n+ Nếu sử dụng ở dạng -도록 하겠다 : nó thể hiện ý nghĩa người nói bộc lộ ý chí, quyết tâm làm một việc gì đó. \n\n+ 늦게 온 사람에게 청소를 하도록 했어요.\n+ 휴지를 떨어뜨린 사람에게 그것을 줍도록 했어요. \n+ 이제는 약속을 꼭 지키도록 하세요. \n\nA : 휴대전화를 찾아 주셔서 정말 감사드려요.\nB : 아니에요, 앞으로는 잃어버리지 않도록 하세요. \n\nA : 교실에서는 한국어만 써야 하나요?\nB : 네, 학생들에게 한국어만 쓰도록 합니다."}, {"id": "E132", "book": "3", "lesson": "3.8", "topic": "실수", "vocabulary": "", "grammar": "(으)ㄴ/는/(으)ㄹ + 줄 + 알았다 \n                                     + 몰랐다", "note": "- Đứng sau động từ và tính từ, \n=> được sử dụng khi thể hiện ý nghĩa “nghĩ như thế nào về việc gì” hoặc sử dụng trong trường hợp một sự thật xảy ra trái với suy nghĩ của người nói. \n+ Động từ chia ở thời quá khứ có dạng -(으)ᄂ줄 알다, ở thời hiện tại có dạng -는 줄 알다 và ở thời tương lai có dạng -(으)ᄅ 줄 알다. \n+ Đối với trường hợp của tính từ, dạng thường được sử dụng là -(으)ᄂ 줄 알다, riêng với trường hợp phỏng đoán được sử dụng ở dạng -(으)ᄅ 줄 알다. \n+ Với trường hợp của 이다, khi thể hiện một tập quán, một việc đang tiến hành ở hiện tại dùng dạng 인 줄 알다, với trường hợp phỏng đoán, dùng dạng 일 줄 알다. \n\n+ 뚜안 씨가 약속을 잊어버린 줄 알고 화를 냈어요. \n+ 루이엔 씨가 흐엉 씨보다 큰 줄 알았어요.\n+ 저보다 나이가 어린 줄 알고 반말을 했는데 저보다 나이가 많았어요. \n\nA : 유나 씨, 왜 오늘 신입생 환영회에 안 왔어요?\nB : 신입생 환영회가 오늘이었어요? 저는 내일인 줄 알았어요. \n\nA : 왜 옷을 바꿨어요?\nB : 비싼 것이 좋은 줄 알고 샀는데 품질이 안 좋았어요."}, {"id": "E133", "book": "3", "lesson": "3.9", "topic": "이사", "vocabulary": "주거 종류", "grammar": "(으)ㄹ + 줄 + 알다/모르다", "note": "- Đứng sau động từ thể hiện năng lực, biết hay không biết phương pháp làm gì, \n- tương đương với nghĩa \"biết / không biết làm gì\" trong tiếng Việt. \n- Cấu trúc này thường được sử dụng khi muốn thể hiện việc biết hay không biết một phương pháp nào đó hoặc có hay không có năng lực làm một việc gì đó. \n+ Sau nguyên âm sử dụng dạng -ᄅ 줄 알다/모르다, \n+ sau phụ âm sử dụng dạng -을 줄 알다/모르다. \n\n+ 저는 한국어로 계약서를 쓸 줄 몰라요. \n+ 화 씨는 피아노를 칠 줄 알아요? \n+ 한국에 오래 살았지만 한국 노래를 부를 줄 몰라요. \n\nA : 집들이 때 한국 음식을 준비하는 게 어때요?\nB : 저는 한국 음식을 만들 줄 모르니까 다른 음식을 준비할게요. \n\nA : 수영할 줄 아세요?\nB : 수영할 줄 알지만 요즘 다리를 다쳐서 할 수 없어요. \n\nCấu trúc này có sự khác biệt với cấu trúc -(으)ᄅ 수 있다/없다 thể hiện năng lực, khả năng thực hiện một việc nào đó. \n예)  지금 바로 떠날 수 있어요. (○) \n       지금 바로 떠날 줄 알아요. (×)"}, {"id": "E134", "book": "3", "lesson": "3.9", "topic": "이사", "vocabulary": "주거 형태", "grammar": "N에 + 비해(서) + clause", "note": "- Là cấu trúc đứng sau danh từ thể hiện sự so sánh. \n- Nó được sử dụng khi thể hiện kết quả ở vế sau trong tương quan so sánh với đối tượng ở vế trước. \n-서 có thể được lược bỏ khi sử dụng. \n\n+ 요즘은 전세에 비해(서) 월세가 더 많아요. \n+ 가격에 비해(서) 품질이 좋은 것 같아요. \n+ 풍 씨 성격에 비해 흐엉 씨 성격이 더 밝아요. \n\nA : 뚜안 씨는 왜 자취를 선택하셨어요? \nB : 하숙에 비해(서) 자취가 더 편한 것 같아서요. \n\nA : 루이엔 씨, 조금 전에 알아본 집은 어땠어요? \nB : 보증금이 싼 것에 비해(서) 넓고 깨끗해 보였어요."}, {"id": "E135", "book": "3", "lesson": "3.9", "topic": "이사", "vocabulary": "이사", "grammar": "V/A기(를) + 바라다", "note": "- Đứng sau động từ và một số tính từ \n=> để biểu hiện nghĩa mong muốn, kỳ vọng, \n- tương đương với nghĩa “mong rằng ..., hy vọng rằng ...”\n- Đây là cấu trúc biểu hiện sự cầu chúc, mong muốn cho đối tượng được đề cập ở phía trước đạt được điều gì hoặc trông mong nhờ cậy việc gì đối với đối tượng đó. \n- Nó thường được sử dụng trong văn nói và trong bối cảnh giao tiếp chính thức, lịch sự. \n\n+ 항상 건강하시기(를) 바랍니다.\n+ 도서관에서는 조용히 해 주시기 바랍니다.\n+ 포장 이사를 하시려면 이삿짐센터로 문의해 주시기 바랍니다. \n\nA : 집들이에 와 주셔서 정말 고마워요. \nB : 이사 축하드려요. 항상 행복하시기 바랍니다. \n\nA : 엘리베이터가 고장이 났는데 어떻게 하지요? \nB : 오른쪽에 있는 계단을 이용해 주시기 바랍니다."}, {"id": "E136", "book": "3", "lesson": "3.9", "topic": "이사", "vocabulary": "집 시설", "grammar": "아무 + N(이)나", "note": "- Kết hợp danh từ ở phía trước (이)나, được sử dụng khi thể hiện ý nghĩa cho dù danh từ ở vế trước là gì thì cũng không có liên quan gì đến kết quả ở vế sau. \n- Nghĩa tương đương trong tiếng Việt là \"bất cứ ...\". \nĐối với trường hợp danh từ chỉ người, sử dụng dạng 아무나. \n\n+ 옛날에는 아무 때나 이사 가지 않고 좋은 날을 선택해서 이사했어요. \n+ 배고플 때 냉장고에서 아무 음식이나 꺼내서 드세요.\n+ 그 회의는 중요하기 때문에 아무나 들어갈 수 없어요. \n\nA : 어떤 집으로 이사할 생각이에요? \nB : 글쎄요, 학교 근처라면 아무 데나 좋아요. \n\nA : 언제쯤 찾아가면 좋을까요? \nB : 요즘 좀 한가하니까 아무 때나 오세요. \n\n(*) Cấu trúc này có thể dùng thể khẳng định, khác với cấu trúc “아무도” chỉ dùng thể phủ định ở vế sau. \n예)  아무도 오지 마세요. (○) \n       아무도 오세요. (×) \n       아무나 오면 안돼요. (○) \n       아무나 오세요. (○)"}, {"id": "E137", "book": "3", "lesson": "3.10", "topic": "여행", "vocabulary": "여행 상품", "grammar": "~ 다고 + 하다", "note": "- Đứng sau động từ, tính từ biểu hiện ý nghĩa ‘nói là, nói rằng’. Được dùng để tường thuật gián tiếp một nội dung được nghe từ người khác. \n+ Động từ : sau nguyên âm và ᄅ dùng -ᄂ다고 하다, sau phụ âm dùng -는다고 하다, \n+ sau 있다, 없다, ‘tính từ’ dùng -다 고 하다, \n+ sau 이다, 아니다 dùng -(이)라고 하다. \n\n+ 흐엉 씨는 주말마다 야외로 드라이브를 간다고 해요. \n+ 지원 씨가 저한테 이번 주에는 시간이 별로 없다고 했어요. \n+ 민준 씨가 우리한테 제주도가 아주 유명한 관광지라고 했어요. \n\nA : 화 씨도 비행기 표를 예약했다고 해요? \nB : 아니요, 화 씨는 아직 비행기 표를 예약하지 않았다고 해요. \n\nA : 현장학습은 언제쯤 갈까요? \nB : 선생님께서 다음 주쯤 갈 거라고 하셨어요."}, {"id": "E138", "book": "3", "lesson": "3.10", "topic": "여행", "vocabulary": "여행지", "grammar": "~ 냐고 + 하다", "note": "- Đứng sau động từ, tính từ biểu hiện ý nghĩa ‘hỏi là, hỏi rằng’. \n- Được dùng khi tường thuật gián tiếp câu hỏi từ một người khác. \n- Sau 이다 dùng -(이)냐고 하다. \n\n+ 서영 씨가 저한테 비행기 표를 예약했냐고 해요. \n+ 민정 씨가 요즘 베트남 날씨가 어떠냐고 해요. \n+ 저한테 직업이 뭐냐고 해서 학생이라고 대답했어요. \n\nA : 와완 씨가 뭐라고 했어요? \nB : 아, 한국 여행 잘 다녀왔냐고 하는군요. \n\nA : 반 씨도 저녁에 같이 갈 거냐고 물어봤어요?\nB : 물어봤는데 반 씨는 급한 일이 생겨서 못 간다고 해요."}, {"id": "E139", "book": "3", "lesson": "3.10", "topic": "여행", "vocabulary": "여행 일정", "grammar": "V(으)ㄹ까 + 하다", "note": "- Đứng sau động từ thể hiện ý nghĩa về một hành động nào đó dù chưa quyết định nhưng có suy nghĩ hoặc dự định sẽ làm điều đó. \n- Nghĩa tương đương trong tiếng Việt là “có nên.....không” / \"tính làm gì ...\"\n+ Sau nguyên âm và ᄅ dùng -ᄅ까 하다, \n+ sau phụ âm dùng -을까 하다. \n\n+ 이번 방학에는 한국 여행을 할까 해요. \n+ 방학 때 전공 책들을 좀 읽을까 해요. \n+ 학기 끝날 때쯤 한국 친구에게 연락해 볼까 해요. \n\nA : 부산에서 얼마나 있을 거예요? \nB : 9박 10일 정도로 다녀올까 해요. \n\nA : 오후에 뭐 할 거예요?\nB : 새로 지은 도서관에 가 볼까 해요."}, {"id": "E140", "book": "3", "lesson": "3.11", "topic": "고민", "vocabulary": "고민", "grammar": "반말", "note": "- Đây là những kết thúc câu thể hiện lối nói rút gọn (nói không tôn kính), được dùng để nói với những người ít tuổi hơn hoặc với bạn bè thân thiết. \n+ Lối nói này ở thể công thức (격식체 반말) có nhiều hình thái đa dạng tuỳ theo loại hình kết thúc câu, được biểu hiện trong bảng bên dưới đây. \n+ Lối nói rút gọn không công thức (비격식체 반말) đối với động từ, tính từ thì thêm 아/ 어 vào sau thân từ, đối với danh từ thì gắn với -(이)야. \n\n+ 요즘 고민이 많아서 잠이 안 와. \n+ 학교 앞에 새로 생긴 그 커피숍 정말 예뻐. \n+ 내 친구는 운동하는 것을 좋아한다. \n+ 내일 뭐 할 거야?\n+ 한국말을 정말 잘 하는구나! \n\nA : 무슨 걱정 있어? 하루 종일 표정이 어둡네.\nB : 여자 친구와 싸웠는데, 연락을 해도 받지 않아서 그래. \n\nA : 이건 무슨 음식이야? \nB : 베트남 전통 음식이야. \n\nTrong lối nói không công thức nếu ta bỏ đi -요 trong -아/어요 thì sẽ trở thành lối nói rút gọn không công thức. \n예) 요즘 시험 때문에 스트레스가 많아요. \n→  요즘 시험 때문에 스트레스가 많아."}, {"id": "E141", "book": "3", "lesson": "3.11", "topic": "고민", "vocabulary": "감정", "grammar": "Sb아/야", "note": "- Đứng sau danh từ, được dùng để gọi những người ít tuổi hơn, gọi bạn bè hoặc dùng để gọi một sự vật như con người. \n+ Sau nguyên âm dùng 야, \n+ sau phụ âm dùng 아. \n\n+ 유진아, 무슨 고민 있어? \n+ 화, 이따 5시에 영화 보러 가자. \n+ 유진아, 이리 와. \n\nA : 민준아, 내일 시간 있으면 나랑 얘기 좀 해. \nB : 왜? 무슨 일 있니? \n\nA : 얘들아, 밥 먹자. \nB : 네, 엄마."}, {"id": "E142", "book": "3", "lesson": "3.11", "topic": "고민", "vocabulary": "상담", "grammar": "V다(가) + 보면 + clause", "note": "- Gắn vào sau động từ, được dùng để thể hiện ý nghĩa nếu thực hiện liên tục một hành động nào đó hoặc trong quá trình tiến hành một hành động nào đó thì sẽ được chuyển thành một trạng thái khác. \n+ Nghĩa tương đương trong tiếng Việt là “nếu cứ tiếp tục ... thì ...”. \n+ Trong khi sử dụng, có thể rút ngắn -다가 thành -다. \n\n+ 친구들과 이야기하다(가) 보면 스트레스가 풀려요. \n+ 열심히 공부하다 보면 한국어 실력이 늘게 될 거예요. \n+ 계속 가다 보면 왼쪽에 서점이 보일 거예요. \n\nA : 이 책을 읽고 보고서를 써야 하는데 무슨 말인지 모르겠어요. \nB : 계속 읽다 보면 이해하게 될 거예요. \n\nA : 새로 휴대전화를 샀는데 사용하기가 불편해요. \nB : 계속 쓰다 보면 금방 익숙해질 거예요."}, {"id": "E144", "book": "3", "lesson": "3.12", "topic": "인터넷", "vocabulary": "인터넷", "grammar": "V/A(으)ㅁ", "note": "- Đứng sau thân động từ hay tính từ để thông báo hoặc ghi chú một cách đơn giản về một sự việc nào đó. \n- Thường được dùng để kết thúc một câu trong bảng thông báo hay bảng ghi chú. \n+ Sau động từ hoặc tính từ tận cùng là nguyên âm hay ᄅ thì kết hợp với ᄆ, \n+ những động từ hay tính từ khác thì kết hợp với 음. \n\n+ 파일을 이메일로 보냈음.\n+ 한국학과 홈페이지에 수업 정보를 게시했음. \n+ 월요일까지 출장 중임.\n+ 지원 씨에게서 오전 10시쯤 전화가 왔음. \n+ 자카르타에는 밤늦게 도착했음.\n+ 오후부터 구름이 끼고 곳에 따라 비가 오겠음."}, {"id": "E145", "book": "3", "lesson": "3.12", "topic": "인터넷", "vocabulary": "이메일", "grammar": "V(으)라고 + 하다", "note": "Đứng sau thân động từ để truyền đạt gián tiếp lại mệnh lệnh hay yêu cầu của người khác. \n+ Sau những thân động từ có tận cùng là nguyên âm hoặc ᄅ thì dùng -라고 하다, \n+ sau những thân động từ khác thì dùng -(으)라고 하다. \n\n(*) Trong trường hợp động từ có thành phần cuối là 주다 với ý nghĩa làm điều gì đó cho người nói ở dạng “động từ + 아/어 주다,” khi chuyển sang cách nói gián tiếp hoặc lặp lại lời đã nói thì dùng -달라고 하다, nhưng nếu câu nói có ý nghĩa là làm gì đó cho người khác thì dùng -주라고 하다. \n\n(**) Ngoài ra, khi tường thuật lại -지 마세요 thì sẽ dùng -지 말라고 하다. \n\n+ 자료는 바탕 화면에 저장해 두라고 하세요. \n+ 자료는 인터넷에서 찾으라고 하셨어요. \n+ 한지원 씨가 도와 달라고 했어요.\n+ 한지원 씨가 정우 씨를 도와주라고 했어요. \n+ 정우 씨에게 모임에 늦지 말라고 전해 주세요. \n\nA : 지금 갈까요?\nB : 아니요, 오후에 오라고 하셨어요. \n\nA : 언제까지 숙제를 낼까요?\nB : 주말까지 제출하라고 했어요."}, {"id": "E146", "book": "3", "lesson": "3.12", "topic": "인터넷", "vocabulary": "문서 작성 프로그램", "grammar": "V자고 + 하다", "note": "- Đứng sau thân động từ, biểu thị cách nói gián tiếp dùng khi truyền đạt lại lời đề nghị của ai đó cho một người khác. \n\n+ 지원 씨가 메신저로 연락하자고 했어요.\n+ 정우 씨가 시험 자료를 카페에 올리자고 했어요. \n+ 선생님께서 사무실에서 만나자고 했어요. \n\nA : 저 혼자 가도 됩니까?\nB : 아니요, 선생님께서 모두 같이 가자고 하셨어요. \n\nA : 발표 자료를 어떻게 만들까요?\nB : 정우 씨가 PPT로 작성하자고 했어요."}, {"id": "E147", "book": "3", "lesson": "3.13", "topic": "희망", "vocabulary": "희망 / 꿈", "grammar": "V아/어 + 가다", "note": "- Đứng sau động từ, tính từ , nhằm thể hiện việc thay đổi một trạng thái, một hành vi nào đó đang được tiếp tục. \n- Nghĩa tiếng Việt là “sắp ..., dần ...” \n- Cấu trúc -아/어 가며, -아/어 가면서 còn dùng để thể hiện một hành động nào đó đang tiến hành cùng lúc với hành động khác cũng đang tiếp tục, tương đương với nghĩa 'vừa ... vừa.' \n\n+ 이제 숙제가 다 끝나가요. \n+ 밥 다 먹어가니까 조금만 기다려 주세요. \n+ 좀 쉬어 가면서 일합시다. \n\nA : 유학 갈 준비는 다 했어요?\nB : 네, 거의 다 되어 가요. 이제 책만 부치면 돼요. \n\nA : 몸이 빨리 회복되어 가니 다행이에요. \nB : 네, 덕분에 많이 좋아졌어요."}, {"id": "E148", "book": "3", "lesson": "3.13", "topic": "희망", "vocabulary": "장래 희망", "grammar": "V아/어 + 오다", "note": "- Đứng sau động từ, tính từ, biểu hiện ý nghĩa là “làm ...đến ..., làm ... tới ....”. \n- Sử dụng khi một hành động hay trạng thái nào đó liên tục có trạng thái chuyển biến hay đã được tiến hành đến khi nói. \n\n+ 취업 준비 때문에 컴퓨터와 외국어를 계속 공부해 왔어요. \n+ 앞으로의 진로에 대해 오랜 시간 고민을 해 왔어요. \n+ 지금까지 일해 온 직장을 떠나게 됐어요. \n\nA : 이번 방학에 뭐 특별한 계획 있어요? \nB : 네, 전부터 생각해 온 게 있어요. \n\nA : 지훈 씨는 졸업하기 전에 배낭여행을 갈 거라고 했지요?\nB : 네, 제 돈으로 가려고 1년 동안 아르바이트를 계속해 오고 있어요."}, {"id": "E149", "book": "3", "lesson": "3.13", "topic": "희망", "vocabulary": "봉사", "grammar": "V/A아/어야겠다", "note": "- Đứng sau động từ hoặc tính từ, \n- có nghĩa là ‘sẽ phải ...’, \n=> được dùng để thể hiện một ý chí nhất định sẽ phải làm hành động đó, hoặc phải ở trạng thái nào đó. \n- Cũng hay được sử dụng khi suy đoán. \n\n+ 이번 도전에서는 꼭 성공해야겠어요.\n+ 다음 학기에는 학점을 잘 받아야겠어요.\n+ 한국 회사에서 일하려면 한국어를 더 잘해야겠어요. \n\nA : 어느 회사에 원서를 낼 생각이에요?\nB : 아직 결정을 못했는데 좀 더생각해 봐야겠어요. \n\nA : 오후에 우리 영화 볼래요? \nB : 아, 저는 내일 시험이라서 도서관에 가서 공부해야겠어요."}, {"id": "E150", "book": "3", "lesson": "3.13", "topic": "희망", "vocabulary": "성공", "grammar": "V/A았/었으면 + 좋겠다", "note": "- Đứng sau động từ hoặc tính từ, \n- có nghĩa là ‘nếu được như thế thì tốt biết mấy’, ‘ước gì ...’, ‘giá mà ...’, \n=> được dùng để thể hiện sự mong đợi đối với một tình trạng nào đó hoặc giả định cho một trường hợp trái ngược lại với hiện tại hay quá khứ. \n(*) 하다 싶다 có thể dùng để thay thế cho 좋다. \n\n+ 졸업 후에 공무원이 됐으면 좋겠어요.\n+ 방학 때 한국 회사에서 인턴사원으로 일했으면 좋겠어요. \n+ 제가 좀 더 머리가 좋았으면 좋겠어요. \n\nA : 10년 후에 하고 싶은 게 있어요?\nB : 가족들과 해외여행을 할 수 있었으면 좋겠어요. \n\nA : 만약 복권에 당첨되면 뭘 하고 싶어요? \nB : 집과 차를 사고 어려운 사람들을 좀 도와줬으면 좋겠어요."}, {"id": "E151", "book": "3", "lesson": "3.14", "topic": "영화와 드라마", "vocabulary": "영화 / 드라마", "grammar": "(아무리) V/A아/어도 + clause", "note": "- Đứng sau động từ, tính từ biểu hiện nghĩa “cho dù ... nhưng ...”, \n=> được sử dụng khi nói đến một việc ở vế sau xảy ra không liên quan đến hành vi và trạng thái ở vế trước. \n+ Sau từ có nguyên âm của âm tiết cuối là ᅡ, ᅩ, sử dụng dạng -아도, \n+ sau các nguyên âm còn lại sử dụng dạng -어도. \n\n+ 저는 아무리 바빠도 일주일에 한 번씩 한국 영화를 봐요. \n+ 아무리 배가 불러도 음식을 버리면 안 돼요.\n+ 아무리 힘들어도 포기하지 마세요. \n\nA : 내일 비가 오면 행사를 안 합니까?\nB : 아니요, 내일 비가 와도 행사를 합니다. \n\nA : 어제 화 씨하고 영화 잘 봤어요?\nB : 아니요, 아무리 기다려도 오지 않아서 그냥 혼자 봤어요."}, {"id": "E152", "book": "3", "lesson": "3.14", "topic": "영화와 드라마", "vocabulary": "영화 종류", "grammar": "V/A거든(요).", "note": "- Đứng sau động từ, tính từ, tương đương với nghĩa là “vì ..., do ...” trong tiếng Việt. \n=> Được sử dụng khi trả lời câu hỏi hoặc giải thích lý do, sự thực của nội dung đã đề cập trong vế trước. \n\n+ 이 드라마 한번 보세요. 남자 주인공이 정말 멋있거든요.\n+ 그 남자 배우가 요즘 정말 인기가 있어요. 정말 잘생겼거든요. \n+ 내가 오늘 한턱낼게. 장학금을 받았거든. \n\nA : 남 씨, 같이 영화 보러 갈래요? 제가 좋아하는 배우가 나오거든요. \nB : 죄송해요. 오늘 좀 바쁘거든요. \n\nA : 오늘은 수업도 없는데 왜 학교에 가요? \nB : 유나 씨와 만나기로 했거든요. \n\n- Được sử dụng khi giải thích về một sự thật nào đó đồng thời tiếp tục kéo dài câu chuyện có liên quan đến nội dung đó ở vế sau. \n\n예)  영화 표가 두 장 생겼거든요. 같이 가실래요?\n       이번 시험이 아주 어려웠거든요. 그래서 잘 못 봤어요."}, {"id": "E153", "book": "3", "lesson": "3.14", "topic": "영화와 드라마", "vocabulary": "영화 감상", "grammar": "V/A던데요.", "note": "- Đứng sau tính từ và động từ, \n=> được sử dụng khi người nói nhớ lại một việc nào đó trong quá khứ và cảm thán về sự thật mà bản thân đã cảm nhận vào thời điểm đó. \n- Nghĩa tiếng Việt là “thật là .., rất ...” \n\n+ 그 영화 보셨어요? 지난 주말에 봤는데 정말 재미있던데요. \n+ 어제 집에 가다가 화 씨 남자친구를 봤어요. 키가 정말 크던데요. \n+ 방학 때 제주도에 갔어요. 경치가 정말 아름답던데요. \n\nA : 저 배우 정말 멋있지요? \nB : 네, 연기도 정말 잘하던데요. \n\nA : 중 씨는 책을 정말 좋아하는 것 같아요. \nB : 네, 책을 정말 많이 읽던데요."}, {"id": "E154", "book": "3", "lesson": "3.15", "topic": "예절과 규칙", "vocabulary": "사회 규범", "grammar": "N대로", "note": "- Đứng sau danh từ với nghĩa ‘theo ..., như ...’. \n- Diễn đạt ý nghĩa căn cứ theo hoặc không có gì khác với ý nghĩa của danh từ đứng trước. \n\n+ 순서대로 해 드리겠습니다. \n+ 약속대로 영화를 보여 줄게요. \n+ 친구에게 사실대로 말했습니다. \n\nA : 우리 계획대로 오후에 등산을 갈까요? \nB : 오후에 비가 온다고 하니까 다음에 가지요. \n\nA : 그렇게 마음대로 사무실에 들어오면 안 돼요. \nB : 죄송해요. 몰랐습니다."}, {"id": "E155", "book": "3", "lesson": "3.15", "topic": "예절과 규칙", "vocabulary": "예절 - 규칙", "grammar": "V/A지 + 않으면 + 안 + 되다", "note": "- Đứng sau động từ hoặc tính từ \n- với ý nghĩa là ‘nếu không ... thì không được’. \n- Diễn đạt ý nghĩa phải làm một hành động nào đó hoặc phải ở một trạng thái nào đó. \n- Đây là một biểu hiện sử dụng biện pháp phủ định kép để khẳng định ý ‘phải đạt được hành động hay trạng thái đó’. \n- Biểu hiện tương tự khác là -아야/어야 하다. \n\n+ 순서 표를 뽑고 기다리지 않으면 안 돼요.\n+ 허락을 받지 않으면 안 됩니다.\n+ 공연에 방해가 되니까 휴대전화를 끄지 않으면 안 돼요. \n\nA : 지금 가야 하나요?\nB : 네, 지금 가지 않으면 안 돼요. 안 그러면 늦을 거예요. \n\nA : 이 일을 꼭 내일까지 끝내야 돼요? \nB : 네, 기한을 지키지 않으면 안 돼요."}, {"id": "E156", "book": "3", "lesson": "3.15", "topic": "예절과 규칙", "vocabulary": "", "grammar": "V(으)려던 + 참이다", "note": "- Đứng sau động từ, \n- biểu hiện ý nghĩa “vừa mới có ý định ...”, \n=> đang định bắt đầu một hành động nào đó đúng vào ngay thời điểm nói. \n+ Dùng -려던 참이다 sau các động từ kết thúc bằng nguyên âm hay ᄅ, \n+ dùng -(으)려던 참이다 sau các động từ kết thúc bằng các phụ âm khác. \n- Thông thường được dùng với thì hiện tại hay quá khứ và còn được dùng dưới dạng -(으)려던 참에. \n\n+ 지금 막 자려던 참이에요.\n+ 제가 전화하려던 참이었어요.\n+ 내가 나가려던 참에 친구가 찾아왔어요. \n\nA : 쇼핑몰에서 전자사전을 세일한대요. \nB : 잘됐네요. 마침 전자사전을 사려던 참이었어요. \n\nA : 연락을 드리려던 참이었는데, 연락을 주셨네요. \nB : 그러셨어요? 확인할 일이 있어서 먼저 연락을 드렸어요."}, {"id": "E157", "book": "4", "lesson": "4.1", "topic": "유행", "vocabulary": "패션", "grammar": "V나             + 보다 \nA(으)ㄴ가  + 보다", "note": "- Đứng sau động từ, tính từ được dùng để suy đoán một việc dựa trên cơ sở một tình huống hay một sự việc nào đó.\n- Nghĩa tương đương trong tiếng Việt là “ trông có vẻ..., hình như là...., có vẻ như...’ \n+ Sau động từ hoặc động từ có 있다, 없다, 았/었다 thì dùng -나 보다, \n+ sau tính từ kết thúc bằng nguyên âm dùng -ᄂ 가 보다, sau tính từ kết thúc bằng phụ âm dùng -은가 보다. \n\n+ 요즘 피부 관리를 받는 사람들이 많은가 봐요. \n+ 흐엉 씨, 한국어 발음이 좋아진 걸 보니까 발음 연습을 열심히 하나 봐요. \n+ 올해도 미니스커트가 유행인가 봐요. \nA : 머리했나 봐요. 스타일이 달라 보여요. \nB : 네, 조금 자르고 염색도 했어요. \nA = 루이엔 씨가 하는 이야기가 재미있나 봐요. \nB = 그런 것 같아요. 사람들이 계속 웃고 있네요. \n\nSo sánh -나 보다/(으)ᄂ가 보다 và -(으)ᄂ/는 것 같다\n- Cả hai cấu trúc đều có thể sử dụng được trong trường hợp thể hiện sự phỏng đoán của người nói. \n+ Nhưng -(으)ᄂ/는 것 같다 có thể sử dụng được khi người nói không trực tiếp trải nghiệm \n+ còn -나 보다/(으)ᄂ가 보다 không thể sử dụng được với nội dung mà người nói không trực tiếp trải nghiệm. Nghĩa là cấu trúc này được sử dụng khi phỏng đoán trên cơ sở tình huống hoặc trạng thái mà người nói trực tiếp trải nghiệm, tức nội dung mà người nói nhìn thấy hoặc nghe được. \n예)  제 생각에는 스카프가 유행인 것 같아요. (○) \n       제 생각에는 스카프가 유행인가 봐요. (×)"}, {"id": "E158", "book": "4", "lesson": "4.1", "topic": "유행", "vocabulary": "미용", "grammar": "~ 다고요?", "note": "- Đứng sau động từ và tính từ biểu hiện nghĩa tương đương trong tiếng Việt là “... ấy à ?\"  hoặc   “ấy ... là ... ”. \n=> Được sử dụng khi dùng lại lời nói của đối phương để hỏi lại; chủ yếu là trong trường hợp người nói không nghe rõ lời của người đối thoại hoặc không đồng ý với nội dung vừa nghe hoặc khi ngạc nhiên. Trường hợp này, cuối câu thường lên giọng. \n+ Với động từ kết thúc bằng nguyên âm, sử dụng dạng -ᄂ다고요?; với động từ kết thúc bằng phụ âm, sử dụng dạng -는다고요?, \n+ với tính từ, sử dụng dạng -다고요? \n\n+ 다이어트 때문에 매일 저녁을 굶는다고요? \n+ 어머니가 어렸을 때도 미니스커트를 입었다고요? \n+ 청바지를 입으신 분이 흐엉 씨 아버지라고요? \n\nA  : 요즘 파마를 하는 남자들이 많은 것 같아요. \nB  : 남자가 파마를 한다고요? 말도 안 돼요. \n\nA  : 한달 전화 요금이 10만 원쯤 나와요. \nB  : 뭐라고요? 한달 전화 요금이 그렇게 많이 나온다고요? \nA  : 네, 국제전화를 자주 써서 그런가 봐요."}, {"id": "E159", "book": "4", "lesson": "4.1", "topic": "유행", "vocabulary": "유행", "grammar": "N에 따라(서)", "note": "- Đứng sau danh từ, tương đương nghĩa: “tùy theo ...\", “theo....” trong tiếng Việt. \n- Được sử dụng trong trường hợp biểu hiện sự phụ thuộc, dựa trên một cơ sở hoặc một tình huống nào đó. \n- Có thể sử dụng ở dạng 에 따라서. \n\n+ 사람에 따라 선호하는 스타일이 달라요. \n+ 디자이너에 따라 다른 분위기의 옷을 만들어 내요. \n+ 브랜드에 따라 가격 차이가 꽤 많이 나요. \n\nA : 네일 케어를 받고 싶은데 얼마나 해요?\nB : 네일숍에 따라 조금씩 다른데 보통 만오천 원쯤 해요. \n\nA : 뭘 신으면 키가 커 보일까요?\nB : 굽이 높은 걸 신으면 커 보이지만, 의상에 따라 다를 수도 있어요."}, {"id": "E160", "book": "4", "lesson": "4.2", "topic": "집안일", "vocabulary": "집안일", "grammar": "V/A잖아요.", "note": "- Đứng sau động từ, tính từ, biểu hiện nghĩa \"chẳng phải là.... còn gì” trong tiếng Việt. \n- Thường được sử dụng khi xác nhận lại điều người nghe hoặc người người khác biết, hoặc khi nói muốn nhấn mạnh hay nhắc lại điều mà đối phương không nhớ hoặc không biết. \n- Cấu trúc này được sử dụng nhiều trong quan hệ bạn bè, quan hệ thân thiết hoặc trong trường hợp nói với người dưới. \n\n+ 세탁기로 하세요. 손빨래를 하면 너무 힘들잖아요. \n+ 정장을 입으세요. 단정해 보이잖아요.\n+ 집에서 해 먹어요. 사 먹으면 외식비가 많이 들잖아요. \n\nA : 남편은 집안일을 자주 도와주세요?\nB : 아니요. 아주 가끔씩요. 남자들은 집안일에 관심이 없잖아요. \n\nA : 요즘은 전자사전을 더 많이 사용하는 것 같아요. \nB : 단어를 찾을 때 편리하잖아요."}, {"id": "E161", "book": "4", "lesson": "4.2", "topic": "집안일", "vocabulary": "빨래", "grammar": "V자마자 + clause", "note": "- Đứng sau động từ, biểu hiện nghĩa \"ngay khi ..., ngay sau khi ..., ... vừa ... là ...\" trong tiếng Việt. \n- Được sử dụng khi một tình huống nào đó xảy ra ngay sau một tình huống xảy ra trước đó. \n\n+ 식사를 마치자마자 설거지를 하는 게 좋아요.\n+ 아이들 때문에 퇴근하자마자 집으로 가야 해요.\n+ 많이 도와주신 덕분에 대학을 졸업하자마자 취직을 했어요. \n\nA : 어제는 집에 가서 뭐 했어요?\nB : 애들이 집을 너무 어질러 놓아서 들어가자마자 청소를 했어요. \n\nA : 시간이 너무 늦었네요. 조심해서 들어가고 집에 도착하면 연락 주세요. \nB : 네, 알았어요. 집에 들어가자마자 전화할게요."}, {"id": "E162", "book": "4", "lesson": "4.2", "topic": "집안일", "vocabulary": "청소", "grammar": "사동사 => V/A(이, 히, 리, 기, 우, 추)", "note": "- Gắn vào thân động từ, tính từ, có nghĩa tương đương trong tiếng Việt là ‘làm cho, khiến cho ai đó thực hiện hành động nào đó’. \n- Được sử dụng trong trường hợp chủ thể hành động không thực hiện hành động một cách tự phát mà do người khác sai khiến hoặc do tác động từ bên ngoài dẫn đến. \n- Tùy theo loại động từ, tính từ mà có thể kết hợp với các hậu tố 이, 히, 리, 기, 우 để tạo thành động từ gây khiến. \n\n+ 아이들이 자랄 때 음식을 골고루 먹이는 것이 좋습니다. \n+ 주말에는 보통 남편이 아이들을 재웁니다.\n+ 어른들은 음식 남기는 것을 좋아하지 않으세요. \n\nA : 뭐 하고 있었어요?\nB : 아이에게 책을 읽히는 중이었어요. \n\nA : 동생 옷 어디 있니?\nB : 여기 있어요. 제가 입힐게요."}, {"id": "E163", "book": "4", "lesson": "4.2", "topic": "집안일", "vocabulary": "", "grammar": "=> V/A게 + 하다", "note": "- Đứng sau động từ, tính từ, có nghĩa tương đương trong tiếng Việt là ‘làm cho’ được sử dụng khi chủ ngữ thông qua lời nói hoặc phương pháp nào đó tác động làm cho chủ thể hành động thực hiện một hành động nào đó. \n- Cấu trúc này là một dạng của động từ gây khiến nhưng được biểu hiện ở dạng dài bằng cách kết hợp với 게 하다, khác với cách tạo lập động từ gây khiến dạng ngắn là kết hợp hậu tố -이, -히, 리, 기, 우 vào sau thân động từ hay tính từ. \nVD: 엄마가 아이에게 옷을 입게 해요.\n        선생님께서 수영 씨에게 에어컨을 켜게 했어요.    \n        화 씨는 항상 반친구들을 웃게 해요. \nA: 아이와 외출하려고 하는데 오늘 날씨가 어때요? \nB: 매우 추우니까 아이에게 모자를 쓰게 하세요. \nA = 요즘 무슨 일 있어요? 얼굴이 안 좋아요.\nB = 친구가 나를 힘들게 해서요. 며칠 전에 싸웠거든요. \n\nChú thích \n- Động từ gây khiến dạng ngắn được sử dụng khi chủ ngữ của câu trở thành chủ thể của hành động và trực tiếp thực hiện hành động đó, \n- còn động từ gây khiến dạng dài được sử dụng khi chủ ngữ tác động đến chủ thể hành động thông qua lời nói hoặc phương pháp nào đó để chủ thể thực hiện hành động đó. Vì thế, so với động từ gây khiến dạng ngắn, động từ gây khiến dạng dài tạo cảm giác gián tiếp hơn. \n예) 엄마가 아이에게 밥을 먹였어요.\n→  엄마가 아이에게 직접 밥을 먹이는 행위를 함.   \n      엄마가 아이에게 밥을 먹게 했어요.\n→  엄마가 아이에게 밥을 먹게 시킴."}, {"id": "E164", "book": "4", "lesson": "4.3", "topic": "감정", "vocabulary": "감정", "grammar": "V/A았/었었-", "note": "- Là đuôi gắn sau động từ, tính từ biểu hiện một hành động đã được hoàn thành trong quá khứ hoặc một tình huống đã thay đổi sau khi được hoàn thành. \n- So với đuôi biểu hiện nghĩa quá khứ 았/었, đuôi 았/었었 nhấn mạnh nghĩa một việc đã được kết thúc hoàn toàn trong quá khứ. \n\n+ 처음에는 한국어 공부가 그렇게 어렵지 않았었어요. 그렇지만 3학년부터는 좀 어려워졌어요.\n+ 일을 배울 때는 힘들어서 짜증이 많이 났었지만 이제는 많이 익숙해졌어요.\n+ 어렸을 때는 만화가가 정말 되고 싶었었는데, 지금은 교사가 되고 싶습니다. \n\nA : 이제 1학기가 지났는데, 이곳 생활에 익숙해졌어요?\nB : 네, 처음에는 힘들었었는데, 지금은 많이 익숙해진 것 같아요. \n\nA : 회사에 다닌 지 오래 됐지요? 아직도 안내 창구에서 일하세요? \nB : 처음에는 안내 창구에서 손님을 맞는 일을 했었는데, 며칠전부터 사무실에서 서류를 정리하는 일을 하게 되었어요."}, {"id": "E165", "book": "4", "lesson": "4.3", "topic": "감정", "vocabulary": "", "grammar": "V던 + N", "note": "- Là đuôi gắn sau động từ biểu hiện nghĩa người nói hồi tưởng lại việc mà mình đã trải nghiệm trong quá khứ hoặc một việc nào đó được kéo dài hoặc lặp lại từ một thời điểm nào đó trong quá khứ. \n- Đuôi -던 khi kết hợp với động từ 오다, 가다 để tạo thành 오던, 가던 có ý nghĩa biểu hiện sự lặp lại. \n\n+ 제가 자주 가던 찻집이 문을 닫았어요. 그래서 조금 아쉬웠어요. \n+ 아까 제가 읽던 신문 못 보셨어요? 이 책상 위에 두었는데 잠깐 나갔다가 오니까 없어졌네요.\n+ 자주 전화를 걸어 소식을 전하던 친구가 요즘은 연락이 거의 없어요. \n\nA : 학교 근처에 음식 맛도 좋고 분위기도 좋은 한국 음식점이 있으면 좀 소개해 주시겠어요? \nB : 서울 식당이 어떨까요? 지금은 졸업해서 자주 안 가지만 제가 학교 다닐 때 베트남 친구들과 자주 가던 음식점이에요. \n\nA : 자, 일 다 끝내셨으면 나가시겠어요?\nB : 아, 잠깐만 기다려 주세요. 하던 일을 마저 끝내고요. 2분이면 돼요."}, {"id": "E166", "book": "4", "lesson": "4.3", "topic": "감정", "vocabulary": "", "grammar": "V았/었던 + N", "note": "- Là đuôi biểu hiện nghĩa hồi tưởng lại một sự việc, hành động, trạng thái đã xảy ra trong quá khứ nhưng tình huống đó không được hoàn thành và bị đứt quãng. \n- Trên thực tế, đuôi -았/었던 và đuôi -던 không có sự khác biệt lớn về ý nghĩa. Chỉ khi kết hợp với động từ 오다, 가다 thì -았/었던 biểu hiện ý nghĩa hành động xảy ra một lần còn -던 biểu hiện nghĩa hành động lặp đi lặp lại. \n\n+ 가장 기뻤던 일은 대학교에 합격했던 일이다. 그때는 너무나 기뻐서 눈물이 날 정도였다. \n+ 이 책은 전에 아이들이 많이 읽었던 책인데, 요즘 아이들은 잘 안 읽는다고 한다. \n+ 내가 작년까지 근무했던 회사가 장사가 잘 되어 직원들을 몇 명 뽑을 예정이라고 한다. \n\nA : 한국에서 생활하면서 여러 가지 일을 경험했지요?\nB : 네, 그 중에서도 여권을 잃어버렸던 일이 생각나네요. 그때는 정말 당황했었어요. \n\nA : 어렸을 때는 매일매일 정말 즐겁게 지냈어요. 지금 생각하면 그때가 가장 행복했던 때인 것 같아요. \nB : 저도 그래요. 초등학교 때가 가장 좋았던 것 같아요. 앞날에 대해서 걱정할 것이 없었고 공부 스트레스나 취직 스트레스 같은 것이 없었어요. \n\n(*) Khác với -았/었던,  -(으)ᄂ biểu hiện nghĩa 1 sự việc hoặc hành động nào đó đơn thuần là xảy ra trong quá khứ nhưng trạng thái của hành động đó sau khi được hoàn thành vẫn được duy trì. \n   \n   3년 전에 대학생이었던 지원 씨가 이제는 결혼하여 아이 엄마가 되었다. (○)\n   3년 전에 대학생인 지원 씨가 이제는 결혼하여 아이 엄마가 되었다. (×)"}, {"id": "E167", "book": "4", "lesson": "4.3", "topic": "감정", "vocabulary": "", "grammar": "A아/어하다  =>  Verb", "note": "- Gắn vào thân của các tính từ tâm lý (tính từ chỉ cảm xúc) biểu hiện tình cảm của con người như 기쁘다, 슬프다 để biến tính từ đó thành động từ. \n\n+ 내가 오랜만에 선생님을 찾아뵙고 인사를 드리니까 선생님께서 무척 좋아하셨다. \n+ 모두가 힘을 합해 과제를 훌륭하게 마무리하자 선생님께서 제일 흐뭇해하셨다. \n+ 이번 모임은 성공적이었다. 특히 함께 노래를 부를 때 모든 참가자들이 즐거워했다. \n\nA : 외국분들은 매운 한국 음식을 못 드시는데, 디엠 씨는 괜찮아요? \nB : 네, 물론이요. 저는 매운 음식을 좋아해서 자주 먹어요. \n\nA : 동아리에서 등산 가서 거의 3시간 이상 걸었다고 들었는데 힘들지 않았어요? \nB : 네, 저는 조금 힘들었는데, 다른 친구들은 별로 힘들어하지 않았어요. \n\n- Những câu có sử dụng động từ tâm lý và tính từ tâm lý chỉ khác nhau ở chỗ vị ngữ của câu đó là động từ hay là tính từ, còn nghĩa gần như giống nhau. \n예) 나는 커피가 좋다 = 나는 커피를 좋아한다. \n\n- Nhưng động từ tâm lý và tính từ tâm lý có sự khác biệt tùy thuộc vào ngôi của chủ ngữ. \n+ Động từ tâm lý không có sự hạn định về ngôi của chủ ngữ nhưng tính từ tâm lý thì có.\n+ Tính từ tâm lý chỉ được sử dụng trong câu trần thuật với chủ ngữ là ngôi thứ nhất như 나, 우리, 우리들và trong câu nghi vấn với chủ ngữ là ngôi thứ hai như 너, 너희, 너희들. \n\n나는 대학교에 합격해서 정말 기쁘다. (○)   너는 대학교에 합격해서 정말 기쁘다. (×) \n그는 대학교에 합격해서 정말 기쁘다. (○)   나는 대학교에 합격해서 정말 기뻤어? (×) \n너는 대학교에 합격해서 정말 기뻤어? (○)  그는 대학교에 합격해서 정말 기뻤어? (×)"}, {"id": "E168", "book": "4", "lesson": "4.4", "topic": "생활 정보", "vocabulary": "구매", "grammar": "~ 대요", "note": "- Đứng sau động từ, tính từ biểu hiện nghĩa tương đương với “ai đó nói là ..., nghe nói là ...” trong tiếng Việt. \n- Cấu trúc này được sử dụng khi chuyển đổi để nói một cách gián tiếp nội dung nghe được từ người khác. Đây là dạng rút gọn của -다고 해요. \n+ Với động từ kết thúc bằng nguyên âm hoặc có phụ âm cuối là ᄅ, sử dụng dạng -ᄂ대요; với động từ có phụ âm cuối là phụ âm, sử dụng dạng -는대요; \n+ sau tính từ và 있다, 없다 sử dụng dạng -대요 và \n+ sau 이다, 아니다 dùng dạng (이)래요, 아니 래요. \n\n+ 지원 씨는 생활용품을 주로 한국마트에서 산대요.\n+ 일기예보에서 이번 장마는 다 끝났대요.\n+ 생활 정보지를 봤는데 사용한 지 9개월 된 책상을 8만원에 판대요. \n\nA : 화 씨는 하숙비를 냈나요?\nB : 아니요, 아직 하숙비를 내지 않았대요. \n\nA : 유나 씨는 왜 밥 먹으러 같이 안 왔어요?\nB : 지금 꼭 해야 할 일이 있어서 나중에 혼자 먹겠대요."}, {"id": "E169", "book": "4", "lesson": "4.4", "topic": "생활 정보", "vocabulary": "주거 생활", "grammar": "~ 냬요", "note": "- Đứng sau động từ, tính từ biểu hiện nghĩa tương đương với “ai đó hỏi là ..., câu hỏi là ...” trong tiếng Việt. \n- Được sử dụng khi chuyển đổi để nói một cách gián tiếp nội dung người khác hỏi. Là dạng rút gọn của -냐고 해요. \n- Sau 이다 sử dụng dạng (이)냬요. \n\n+ 서영 씨가 어디에서 책을 싸게 살 수 있냬요.\n+ 남 씨가 어느 대학교가 한국학 전공으로 가장 유명하냬요. \n+ 지훈 씨가 베트남에 유학가면 어디에서 사는 게 제일 좋냬요. \n\nA : 아까 민재가 너한테 뭐라고 했어?\nB : 주말에 가족들과 제주도에 잘 다녀왔냬. \n\nA : 유나 씨가 오늘 마트에 갈 건데 같이 갈 거냬요.\nB : 잘됐네요. 저도 마침 마트에 가서 살 게 있었거든요."}, {"id": "E170", "book": "4", "lesson": "4.4", "topic": "생활 정보", "vocabulary": "관공서 이용", "grammar": "V(으)래요", "note": "- Đứng sau động từ biểu hiện nghĩa tương đương với nghĩa “ai đó bảo là hãy ..., ai đó đề nghị/ yêu cầu là ...”. \n- Được dùng khi người nói hỏi hoặc truyền đạt lại cho người nghe nội dung yêu cầu, đề nghị đã được nghe từ người khác. \n+ Sử dụng dạng -래요 sau động từ kết thúc bằng nguyên âm và phụ âm ᄅ, \n+ sử dụng dạng -으래요 sau động từ kết thúc bằng các phụ âm khác. \n\n(*) Tuy nhiên, đối với trường hợp của động từ 주다, nếu người đề đạt yêu cầu 주세요 là người chịu tác động của yêu cầu đó thì người truyền đạt phải dùng dạng 달래요, còn nếu người chịu tác động của yêu cầu đó không phải là người đề đạt yêu cầu thì người truyền đạt lại phải sử dụng dạng 주래요. \n\n+ 선생님께서 금요일까지 외국인 등록증이나 여권을 복사해서 제출하래요. \n+ 병원에서 이걸 가지고 약국에 가서 약을 사래요. \n+ 풍씨, 유진 씨가 전화했었는데 집에 오자마자 전화 좀 해 달래요. \n\nA : 이 서류를 직접 회사까지 가지고 가야 하나요? \nB : 아니요, 그냥 퀵서비스로 보내 달래요. \n\nA : 오늘 몇 시에, 어디에서 만나는 거예요?\nB : 란 씨가 지난 번에 만났던 서점 앞으로 저녁 6시까지 오래요."}, {"id": "E171", "book": "4", "lesson": "4.4", "topic": "생활 정보", "vocabulary": "", "grammar": "V재요", "note": "- Đứng sau động từ biểu hiện nghĩa “ai đó rủ là ..., ai đó đề nghị là cùng ...” tương đương trong tiếng Việt. \n- Được sử dụng khi người nói truyền đạt lại lời thỉnh dụ hoặc yêu cầu đã nghe được từ người khác hoặc hỏi lại nội dung lời thỉnh dụ, yêu cầu mà người nghe đã biết. \n\n+ 지원 씨가 유학 정보를 알아보러 유학원에 같이 가재요. \n+ 민재 씨가 화 씨 집들이 선물을 같이 사재요.\n+ 친구들이 오늘 저녁에는 베트남 요리를 먹재요. \n\nA : 우리 전자사전은 어디에 가서 살까요?\nB : 지훈 씨가 싸고 좋은 곳을 안다고 같이 가재요. \n\nA : 히엔 씨가 은행에 갈 때 같이 가재요. 유나씨도 시간이 돼요? \nB : 아니요, 전 친구랑 도서관에 가기로 해서 안 될 것 같아요."}, {"id": "E172", "book": "4", "lesson": "4.5", "topic": "취직", "vocabulary": "취업 정보", "grammar": "V/A아/어야 + clause", "note": "- Gắn sau động từ, tính từ để thể hiện điều kiện, \n- tương đương với biểu hiện “chỉ khi ... mới ..., chỉ có ... mới ...” trong tiếng Việt. \n- Cấu trúc này được sử dụng với ý nghĩa chỉ ra hành động hay trạng thái ở vế trước là điều kiện thiết yếu cho tình huống ở vế sau. \n- Trong văn nói, có thể sử dụng ở dạng -아/어야지. \n\n+ 요즘은 외국어를 잘해야 원하는 곳에 취직할 수 있어요. \n+ 이 일을 다 끝내야 주말에 편하게 쉴 수 있어요. \n+ 신문을 자주 읽어야 요즘 일어나는 일을 잘 알 수 있어요. \n\nA : 이번 사원 모집에는 대학 졸업자는 누구나 지원할 수 있나요? \nB : 아니요, 3년 이상의 경력이 있어야 지원할 수 있대요. \n\nA : 직장인들 사이에 영어 공부 열기가 대단해요.\nB : 네, 영어 능력 시험을 통과해야 진급할 수 있거든요."}, {"id": "E173", "book": "4", "lesson": "4.5", "topic": "취직", "vocabulary": "취업 준비", "grammar": "V아/어 + 놓다", "note": "- Đứng sau ngoại động từ để biểu hiện một hành động nào đó được kết thúc và trạng thái đó được duy trì. \n- Tương đương với nghĩa “... sẵn, ... đã có” trong tiếng Việt. \n\n+ 회사의 지원 서류를 준비할 때 이력서를 미리 써 놓으세요. \n+ 지원서에 붙일 사진을 미리 찍어 놓았어요. \n+ 오늘 오후까지 발표준비를 해 놓아야 해요. \n\nA : 졸업까지 얼마 안 남았는데 우선 뭘하면 좋을까요? \nB : 컴퓨터 관련 자격증을 따 놓으면 좋아요. \n\nA : 내일 아침 일찍 출발할 건데 준비는 다 했지요? \nB : 물론이죠. 조금 전에 가방을 다 싸 놓았어요."}, {"id": "E174", "book": "4", "lesson": "4.5", "topic": "취직", "vocabulary": "취업 절차", "grammar": "A(으)ㄴ/V는지 + 알다 / 모르다", "note": "- Thường được sử dụng cùng với từ để hỏi ở phía trước để biểu hiện nghĩa nghi vấn. Nghĩa tiếng Việt là “Không biết là .... / Có biết là...?” \n- Thể hiện việc biết hay không biết về câu hỏi có sử dụng từ để hỏi ở phía trước và được sử dụng một cách khác nhau tùy theo thì thể và loại vị ngữ. \n- Trong trường hợp không sử dụng từ để hỏi thì câu hỏi có các cặp từ đối lập nhau thường hay được sử dụng. \n\n+ 취업 시험 합격자 발표를 언제 하는지 잘 모르겠어요. \n+ 면접시험 날짜가 언제인지 몰라서 전화로 물어봤어요. \n+ 루이엔 씨가 지난 방학에 어디에 갔다 왔는지 알아요? \n\nA : 입사원서를 언제까지 내야 하는지 알아요?\nB : 네, 아마 다음 주 금요일까지 제출해야 할 거예요. \n\nA : 학교 앞에 사람들이 많던데 무슨 일 있어요?\nB : 글쎄요, 사람들이 왜 그렇게 많이 있는지 모르겠네요."}, {"id": "E175", "book": "4", "lesson": "4.6", "topic": "고장", "vocabulary": "전기 - 전자 부품", "grammar": "피동사 => V(이, 히, 리, 기)", "note": "- Là loại động từ biểu hiện với ý nghĩa chủ ngữ của câu không tự thực hiện một hành vi nào đó mà chịu tác động bởi một lực từ một người khác hay một đồ vật khác. \n- Các động từ 보다, 닫다, 듣다, 끊다 thường được thêm 이/히/리/기 vào để thành lập từ bị động. \n\n+ 문이 고장 나서 안 닫혀요.\n+ 교실이 어두워서 칠판 글씨가 안 보여요. \n+ 학교 공부 때문에 스트레스가 많이 쌓여요. \n\nA : 텔레비전 화면이 계속 흔들리는데 어떻게 하지요? \nB : 그럼 수리 센터에 전화해서 상담해 보세요. \n\nA : 히엔 씨의 휴대전화 번호가 바뀌었는데 몇 번인지 아세요? \nB : 저도 요즘 연락을 안 해 봐서 바뀐 번호는 몰라요."}, {"id": "E176", "book": "4", "lesson": "4.6", "topic": "고장", "vocabulary": "고장", "grammar": "=> V아/어지다", "note": "- Đứng sau động từ để thể hiện nghĩa bị động có nghĩa là ‘trở nên, bị, được’. \n- Đây là một cách thể hiện bị động dạng dài và nó khác với dạng bị động ngắn thêm 이/히/리/기 vào sau động từ. \n\n+ 텔레비전 전원 버튼을 눌렀는데 안 켜져요.\n+ 수업 시간에 갑자기 불이 꺼져서 깜짝 놀랐어요.\n+ 한국어 공부를 열심히 해서 제 꿈이 이루어지면 좋겠어요. \n\nA : 수리 센터에는 왜 가려고 해요? \nB : 휴대전화 버튼이 잘 안 눌러져서 고치려고요. \n\nA : 제가 선물한 컵은 왜 안 써요?\nB : 사실 며칠 전에 떨어뜨려서 손잡이가 깨졌어요. 미안해요. \n\n(*) Khi thể hiện sự biến đổi trạng thái của tính từ ta cũng dùng –아/어지다 nhưng không có nghĩa bị động như ở trên. \n\n예) 그 아이는 작년에 키가 작았는데 지금은 많이 커졌어요."}, {"id": "E177", "book": "4", "lesson": "4.6", "topic": "고장", "vocabulary": "수리", "grammar": "V/A았/었을 + 때 + clause", "note": "- Đứng sau động từ, tính từ và 이다 để thể hiện một thời điểm của một trạng thái hay một hành động nào đã xảy ra trong quá khứ. \n- Giống như biểu hiện 'khi' trong tiếng Việt. Khác với biểu hiện -(으)ᄅ 때 biểu hiện -았/었을 때 được dùng với những việc đã hoàn thành. \n\n+ 컴퓨터가 고장 났을 때 친구가 고쳐줬어요.\n+ 지난 방학에 베트남에 돌아갔을 때 한국 친구들이 너무 그리웠어요. \n+ 한국어를 처음 배웠을 때는 좀 어려웠는데 이제 괜찮아졌어요. \n\nA : 디지털카메라가 고장 난 것 같아요.\nB : 어제 제가 사용했을 때는 괜찮았는데, 다시 한번 잘 해 보세요. \n\nA : 흐엉 씨는 처음 한국에 왔을 때 기분이 어땠어요?\nB : 그때는 한국어도 잘 모르고 한국 친구도 없어서 좀 무서웠어요."}, {"id": "E179", "book": "4", "lesson": "4.7", "topic": "명절", "vocabulary": "설", "grammar": "얼마나 + A(으)ㄴ/V는지 + clause", "note": "- Đứng sau động từ, tính từ; với nghĩa ‘chẳng biết ... bao nhiêu’, được dùng như một biểu hiện nhấn mạnh. \n- Thay vì dùng 얼마나 thì cũng có thể thay bằng 어찌나. Sau động từ thì dùng -는지, sau tính từ thì dùng -(으)ᄂ지. \n\n+ 명절 음식을 얼마나 많이 먹었는지 살이 2kg이나 쪘어요. \n+ 영화가 얼마나 지루한지 보다가 중간에 나왔어요. \n+ 친구네 신혼집이 얼마나 큰지 입이 딱 벌어졌어요. \n\nA : 고향에 잘 다녀왔어요?\nB : 고속도로에 차가 얼마나 많은지 갈 때 너무 오래 걸렸어요. \n\nA : 집에 있는데 왜 또 샀어요?\nB : 점원이 얼마나 말을 잘하는지 사지 않을 수 없었어요."}, {"id": "E180", "book": "4", "lesson": "4.7", "topic": "명절", "vocabulary": "추석", "grammar": "V곤 + 하다", "note": "- Đứng sau động từ, thể hiện nghĩa tiếng Việt là ‘thường làm ...’ có nghĩa là một tình huống nào đó được lặp lại. \n\n+ 어렸을 때는 명절에 친구들과 씨름을 하곤 했어요. \n+ 운동할 시간이 없을 때는 퇴근길에 30분씩 걷곤 해요. \n+ 주말에는 대학로에 가서 연극 한 편씩 보곤 해요. \n\nA : 와, 윷이네요. 어렸을 때는 설날에 윷놀이를 하곤 했는데.......\nB : 요즘은 안 해요? 수업 때 선생님이 가르쳐줬는데 아주 재미있던데요. \n\nA : 어디 아파요? 왜 약을 드세요?\nB : 소화가 잘 안 돼서 가끔 소화제를 먹곤 해요."}, {"id": "E181", "book": "4", "lesson": "4.7", "topic": "명절", "vocabulary": "명절", "grammar": "N에다가", "note": "- Đứng sau danh từ để thể hiện một đối tượng chịu ảnh hưởng của 1 hành vi nào đó. Cũng có thể dùng ở dạng 에다. \n- Nghĩa tiếng Việt là ‘vào, lên (đâu đó)’. \n\n+ 송편에다가 밤이나 콩을 넣어요.\n+ 이름은 여기에다가 적으세요. \n+ 다 읽은 책은 책꽂이에다가 좀 꽂아 주세요. \n\nA : 어머니, 이 건 어디에다가 놓을까요? \nB : 그건 나물 옆에다가 놓아라. \n\nA : 앗, 또 잊어버렸어요. 어떡해요.\nB : 그러니까 그냥 듣지만말고 수첩에다가 메모하세요."}, {"id": "E183", "book": "4", "lesson": "4.8", "topic": "여가 생활", "vocabulary": "여가 활동", "grammar": "V/A더라고(요).", "note": "- Đứng sau động từ, tính từ, danh từ, được dùng khi nói lại với một người khác về một sự thật mà bản thân mình mới biết nhờ trải qua một kinh nghiệm trong quá khứ. \n- Khi chủ ngữ là ngôi thứ nhất thì không dùng được với biểu hiện này. \n- Nghĩa tiếng Việt là “mình nghiệm ra rằng ...”, “mình thấy rằng ...”. \n\n+ 요즘은 취미 활동을 하는 사람들이 많더라고요. \n+ 저도 그 뮤지컬을 봤는데 내용이 재미있더라고요. \n+ 화 씨는 도서관에서 공부하더라고요. \n\nA : 댄스 동호회에 가입했다는 이야기 들었는데, 어때요? \nB : 춤을 못 춰서 걱정했는데 생각보다 재미있더라고요. \n\nA : 어제 소개팅 잘 했어요?\nB : 네, 기대했던 것보다 사람이 괜찮더라고요. \n\n(*) Mặc dù chủ ngữ là ngôi thứ nhất, biểu hiện này có thể được sử dụng để thể hiện cảm xúc, tâm trạng của chủ ngữ.\n \n예) 시간이 지나니까 더 화가 나더라고요."}, {"id": "E184", "book": "4", "lesson": "4.8", "topic": "여가 생활", "vocabulary": "여가", "grammar": "N(이)야말로", "note": "- Đứng sau danh từ, dùng để khẳng định và xác nhận nội dung vừa nói trước đó. \n+ Sau nguyên âm thì dùng 야말로, \n+ sau phụ âm thì dùng 이야말로. \n- Nghĩa trong tiếng Việt là ‘đúng là ...; đúng thật là ...’. \n\n+ 등산이야말로 주말 여가 활동으로 제일 좋은 것 같아요. \n+ 비빔밥이야말로 한국을 대표하는 음식 중 하나지요. \n+ 청바지야말로 가장 편하게 입을 수 있는 옷이에요. \n\nA : 여가에 할 수 있는 활동으로는 뭐가 있을까요?\nB : 운동이야말로 가장 좋은 여가 활동이라고 생각해요. \n\nA : 한국을 대표하는 건축물은 뭐가 있어요?\nB : 경복궁이야말로 한국을 대표하는 건축물이에요. \n\n(*) Với động từ và tính từ thì biểu hiện này được dùng bằng cách danh từ hoá động từ hay tính từ và đưa về dạng -(으)ᄂ /는 것이야말로. \n\n예)  성격이 좋은 것이야말로 그 사람이 가진 가장 큰 장점이다. \n       열심히 공부하는 것이야말로 학생에게 가장 중요한 일이다."}, {"id": "E185", "book": "4", "lesson": "4.8", "topic": "여가 생활", "vocabulary": "", "grammar": "V(으)ㄹ + 만하다", "note": "- Đứng sau động từ, tương đương với nghĩa ‘xứng đáng để ...’ trong tiếng Việt, dùng để biểu hiện một hành động nào đó có giá trị để làm. \n+ Sau các động từ kết thúc bằng nguyên âm hay phụ âm ᄅ dùng -ᄅ 만하다 , \n+ sau động từ kết thúc bằng phụ âm dùng -을 만하다. \n\n+ 봉사 활동은 정말 해 볼 만한 것 같아요. \n+ 설악산과 동해는 꼭 한번 가 볼 만한 곳이에요. \n+ 배가 고프지만 참을 만하니까 신경 쓰지 마세요. \n\nA : 제주도는 어떤 곳이에요?\nB : 경치가 이국적이어서 한번 가 볼 만한 곳이에요. \n\nA : 한국에 처음 왔는데 생활하는 거 힘들지 않아요? \nB : 처음에는 힘들었는데 지금은 지낼 만해요."}, {"id": "E186", "book": "4", "lesson": "4.9", "topic": "직장", "vocabulary": "직장 생활", "grammar": "V/A(으)ㄹ + 뿐만 + 아니라 + clause", "note": "- Đứng sau động từ hoặc tính từ, \n- có nghĩa trong tiếng Việt là ‘không những ... mà còn’, \n=> để thể hiện thêm một tình huống nữa cho một sự thật nào đó. \n+ Với các động từ và tính từ tận cùng bằng nguyên âm thì dùng -ᄅ 뿐만 아니라, \n+ với các động từ và tính từ tận cùng bằng các phụ âm khác thì dùng -을 뿐만 아니라. \n\n+ 우리 회사는 월급이 많을 뿐만 아니라 휴가도 길어요. \n+ 흐엉 씨는 얼굴이 예쁠 뿐만 아니라 성격도 좋아서 인기가 많아요. \n+ 화 씨는 책을 많이 읽을 뿐만 아니라 여러 가지 경험도 많이 해서 아는 것이 많아요. \n\nA : 풍씨, 이번 행사에 오실 거지요?\nB : 그럼요, 저뿐만 아니라 저희 부서원들 모두 참석할 예정입니다. \n\nA : 한국은 여름에 날씨가 어때요?\nB : 기온이 높을 뿐만 아니라 습도도 높아서 아주 더워요."}, {"id": "E187", "book": "4", "lesson": "4.9", "topic": "직장", "vocabulary": "회사 종류", "grammar": "V/A1든지 + V/A2든지 + clause", "note": "- Đứng sau danh từ, động từ, tính từ, \n- có nghĩa tương đương trong tiếng Việt ‘hoặc là ... hoặc là ...’, \n=> được dùng để thể hiện rằng trong nhiều thứ, có thể chọn một thứ hoặc là chọn thứ nào cũng không thành vấn đề. \n\n+ 일이 끝나면 저에게 전화를 하든지 메시지를 보내세요. \n+ 이 물건들을 정리하든지 버리든지 하세요.\n+ 이번 휴가에는 부산에 가든지 제주도에 가든지 할 거예요. \n\nA : 이번 일은 누구에게 맡길까요?\nB : 화 씨든지 흐엉 씨든지 두 사람 중 한 명에게 맡기는 게 좋겠어요. \n\nA : 남 씨는 참 성실한 사람인 것 같아요.\nB : 맞아요. 남 씨는 누가 보든지 안 보든지 항상 열심히 공부해요. \n\n(*) Ngoài ra còn có thể dùng dưới dạng –든지 말든지. \n\n예) 먹기 싫으면 먹든지 말든지 마음대로 하세요."}, {"id": "E188", "book": "4", "lesson": "4.9", "topic": "직장", "vocabulary": "부서", "grammar": "V아/어 + 가지고 + clause", "note": "- Đứng sau động từ hay tính từ, được dùng để thể hiện thứ tự giữa các hành động trước sau hoặc hành động ở vế trước chính là phương tiện, nguyên nhân, lí do cho hành động ở vế sau. \n- Nghĩa tiếng Việt là ‘... rồi thì ..., ... rồi...’. \n+ Sau những động từ, tính từ có nguyên âm tận cùng làᅡ, ᅩ thì dùng -아 가지고, \n+ sau những động từ, tính từ có nguyên âm tận cùng không phải là ᅡ, ᅩ thì dùng -어 가지고. \n+ Cấu trúc này là hình thức văn nói của -아/어서 và có thể được dùng bằng cách rút gọn thành -아/어 갖고. \n\n+ 이 일을 내일까지 해 가지고 오세요. \n+ 요즘 업무가 많아 가지고 아주 바빠요. \n+ 감기에 걸려 가지고 병원에 다녀왔어요. \n\nA : 이 서류를 어떻게 할까요? \nB : 한 장씩 복사해 가지고 과장님께 갖다 드리세요. \n\nA : 왜 연락을 안 했어요?\nB : 미안해요. 너무 바빠 가지고 잊어버렸어요."}, {"id": "E191", "book": "4", "lesson": "4.10", "topic": "절약", "vocabulary": "절약", "grammar": "V/A(으)ㄹ수록 + clause", "note": "- Đứng sau động từ và tính từ, biểu hiện một trạng thái nào đó càng lúc càng theo chiều hướng của động từ, tính từ trước đó. \n- Nghĩa tiếng Việt là “càng ... càng ...”. \n(*) 갈수록 là trạng từ chỉ ý nghĩa 더욱더(càng),thời gian càng trôi đi hoặc công việc càng tiến hành thì tình trạng càng nghiêm trọng cùng nghiêm trọng. \n\n+ 돈이 많을수록 아껴 써야 해요.\n+ 가까운 사이일수록 더 예의를 지켜야 해요. \n+ 한국어 공부는 하면 할수록 재미있는 것 같아요. \n\nA : 텔레비전을 볼 때 소리를 크게 할수록 전력 소비가 커진대요. \nB : 그래요? 다음부터는 텔레비전 소리를 좀 줄여야겠군요. \n\nA : 카드값이 너무 많이 나와서 저축을 하기가 힘들어요.\nB : 우선 카드 수부터 줄여 보세요. 카드 수를 줄일수록 쓰는 돈도 줄어든대요."}, {"id": "E192", "book": "4", "lesson": "4.10", "topic": "절약", "vocabulary": "소비", "grammar": "A(으)ㄴ/V는 + 모양이다", "note": "- Đứng sau động từ hoặc tính từ, biểu hiện ý nghĩa phỏng đoán, dự tính một trạng thái nào đó bị ảnh hưởng bởi một sự việc khác. \n- Nghĩa tiếng Việt là 'hình như ... , có vẻ là ...' \n\n+ 저축을 많이 하는 걸 보니 흐엉 씨는 알뜰한 모양이에요.\n+ 이번 달에는 전기 요금이 7천 원밖에 안 나온 걸 보니 전기를 많이 아껴 쓴 모양이에요. \n+ 민재 씨가 전화를 안 받는 걸 보니 회의 중인 모양이에요. \n\nA : 기름값이 또 올랐대요.\nB : 그래요? 기름값이 오른 걸 보니 물가가 또 오를 모양이네요. \n\nA : 유진 씨가 걱정이 있는 모양이에요. 안색이 안 좋네요. \nB : 학비를 내야 하는데 아직 못 내서 그런 것 같아요."}, {"id": "E193", "book": "4", "lesson": "4.10", "topic": "절약", "vocabulary": "생활비", "grammar": "V느라고 + clause", "note": "- Đứng sau động từ, biểu hiện sự tập trung chú ý làm mệnh đề trước và gây ra lý do của mệnh đề sau. \n- Nghĩa trong tiếng Việt là ‘vì mãi lo ... nên ...’.\n- Chủ yếu dùng trong trường hợp biểu hiện lý do của một việc nào đó không làm được hoặc trái với mong muốn. \n\n+ 전자사전을 사느라고 이번 달 용돈을 다 썼어요. \n+ 컴퓨터를 고치느라고 돈을 다 써서 여행을 갈 수 없어요. \n+ 친구들하고 노느라고 숙제를 못 했어요. \n\nA : 왜 이렇게 거실이 어두워요? 전기가 나갔어요? \nB : 아, 절약하느라고 불을 하나만 켜서 그래요. \n\nA : 오늘까지 동아리 회비를 내야 한대요. \nB : 그래요? 급하게 나오느라고 지갑을 집에 놓고 왔는데......."}, {"id": "E195", "book": "4", "lesson": "4.11", "topic": "결혼", "vocabulary": "결혼", "grammar": "V(ㄴ/는)/A다면 + clause", "note": "- Đứng sau động từ hay tính từ, \n- có nghĩa tiếng Việt là \"nếu mà ... thì ...\" \n=> dùng để biểu hiện giả định một tình huống nào đó và dựa trên tình huống đó để thực hiện một hành động nào đó hoặc có một trạng thái mới nào khác. \n\n+ 서로 사랑한다면 국제결혼도 할 수 있다고 생각해요. \n+ 제가 결혼을 한다면 우리 어머니 같은 사람과 하고 싶어요. \n+ 다시 태어난다면 남자가 되고 싶어요. \n\nA : 유진 씨는 언제 결혼할 생각이에요? \nB : 아직 생각해 보지 않았는데 사랑하는 사람이 생긴다면 빨리 결혼하고 싶어요. \n\nA : 중매결혼을 한다면 어떨 것 같아요? \nB : 글쎄요, 중매결혼한다면 처음엔 좀 어색할 것 같아요."}, {"id": "E196", "book": "4", "lesson": "4.11", "topic": "결혼", "vocabulary": "남녀 교제", "grammar": "V/A(으)ㄹ + 텐데 + clause", "note": "- Dạng này là sự kết hợp giữa đuôi từ thể hiện sự phỏng đoán hoặc thể hiện ý chí -(으)ᄅ 터 và đuôi từ liên kết -ᄂ데 \n- có nghĩa trong tiếng Việt là 'chắc là ..., đáng ra là ...' \n=> được dùng khi người nói đưa ra một phỏng đoán của mình hoặc khi đề nghị tình huống mà người nói sẽ làm. Thỉnh thoảng thì có thể lược bỏ lời nói phía sau và dùng như một cách kết thúc câu. \n+ Sau nguyên âm hoặc phụ âm ᄅ thì dùng -ᄅ 텐데, \n+ sau phụ âm thì thêm -을 텐데. \n\n+ 결혼식이 끝나면 신혼여행도 가야 할 텐데 어디로 가고 싶어요? \n+ 이번 시험엔 한자도 나올 텐데 어떻게 공부하는 게 좋지요?\n+ 한국인 친구를 많이 사귀었으면 한국말을 더 빨리 배웠을 텐데....... \n\nA : 민수 씨, 결혼 축하드려요.\nB : 시험 준비로 바쁠 텐데 이렇게 와 주셔서 고맙습니다. \n\nA : 결혼 후에도 계속 직장 생활을 할거죠?\nB : 물론이에요. 하지만 아기를 낳으면 얼마 동안 일할 수 없을 텐데 그게 걱정이에요."}, {"id": "E197", "book": "4", "lesson": "4.11", "topic": "결혼", "vocabulary": "결혼식", "grammar": "V/A(으)ㄹ까 + 봐 + clause", "note": "- Đứng sau động từ hoặc tính từ có nghĩa là “sợ rằng ..., e rằng ...’ \n=> thể hiện sự phỏng đoán một tình huống hoặc một sự thực nào đó bị đình trệ. Tình huống đó gây lo ngại hoặc chuẩn bị để đối phó với khó khăn đó. \n+ Sau những động từ hay tính từ tận cùng là nguyên âm hoặc sau động từ hay tính từ có phụ âm tận cùng là ᄅthì dùng -ᄅ까 봐, \n+ sau động từ hay tính từ tận cùng là phụ âm thì dùng -을까 봐. \n\n+ 친구 결혼식에 늦을까 봐 지하철을 탔어요. \n+ 청첩장이 제날짜에 나오지 않을까 봐 걱정이 돼요. \n+ 약속을 잊어버릴까 봐 달력에 메모를 했어요. \n\nA : 왜 이렇게 음식을 못 먹어요?\nB : 결혼식 날 웨딩 드레스가 맞지 않을까 봐 못 먹겠어요. \n\nA : 이번 행사 때 사람들은 많이 왔어요?\nB : 네, 사람들이 많이 안 올까 봐 걱정했는데 생각보다 많이 왔어요."}, {"id": "E199", "book": "4", "lesson": "4.12", "topic": "사건과 사고", "vocabulary": "사건", "grammar": "V아/어 + 보니까 + clause", "note": "- Đứng sau động từ và dùng để thể hiện một sự phát hiện mới hoặc cảm nhận 1 sự thật nào đó sau khi thử làm một điều gì đó.\n- Nghĩa tiếng Việt là '.... thì ra là ..., ... thấy rằng ...' \n- Cấu trúc này là sự kết hợp giữa cấu trúc trải nghiệm -아/어 보다 và cấu trúc thể hiện nguyên nhân -(으)니까 để nói lên sự phát hiện mới. Khác với cấu trúc bình thường của -(으)니까, mệnh đề sau không thể dùng với cách nói mệnh lệnh hoặc yêu cầu. \n\n+ 밖에 나가 보니까 경찰들이 있었어요.\n+ 시장에 가 보니까 외국인들도 많았어요.\n+ 한국에 와 보니까 생각보다 교통이 편리한 것 같아요. \n\nA : 뉴스를 들어 보니까 남부지방에 큰 홍수가 났다고 하던데요. \nB : 저도 들었는데 실종자도 생겼대요. \n\nA : 혼자 생활해 보니까 어때요?\nB : 요리가 좀 힘들기는 하지만 다른 것은 다 괜찮아요."}, {"id": "E200", "book": "4", "lesson": "4.12", "topic": "사건과 사고", "vocabulary": "사고", "grammar": "V(으)ㄹ + 뻔하다.", "note": "- Đứng sau động từ thể hiện một việc dù khả năng xảy ra cao nhưng đã không xảy ra. \n- Nghĩa tương ứng trong tiếng Việt là “suýt chút nữa ..., suýt nữa thì ...” và thường được dùng với những động từ mang ý nghĩa không mong muốn nên khi những động từ đó không xảy ra là điều may mắn. \n(*) Cấu trúc này luôn dùng ở thì quá khứ. \n\n+ 학교에 오다가 교통사고가 날 뻔했어요. \n+ 아침에 늦게 일어나서 지각할 뻔했어요. \n+ 친구들과 이야기를 하다가 싸울 뻔했어요. \n\nA : 눈이 너무 많이 오지요? \nB : 네, 걸어 오다가  눈길에 미끄러질 뻔했어요. \n\nA : 풍 씨는 왜 그렇게 수영을 싫어하세요? \nB : 어렸을 때 수영하다가 물에 빠질 뻔했거든요."}, {"id": "E201", "book": "4", "lesson": "4.12", "topic": "사건과 사고", "vocabulary": "보도", "grammar": "V아/어 + 있다.", "note": "- Đứng sau động từ thể hiện một sự việc gì đó đã xảy ra và vẫn duy trì trạng thái hay kết quả đó. \n- Ý nghĩa tiếng Việt là 'đã có ...' \n- Chỉ có thể dùng được với động từ không cần bổ ngữ và thường dùng ở dạng bị động. \n\n+ 내가 갔을 때는 이미 사고가 나 있었어요. \n+ 제가 학교에 왔을 때 교실 불은 꺼져 있었어요. \n+ 매일 아침 학교에 가면 책상 위에 꽃이 놓여 있어요. \n\nA : 왜 이렇게 사람들이 많이 모여 있어요? \nB : 물에 빠진 사람을 구해서 응급처치를 하고 있대요. \n\nA : 그렇게 서 있지 말고 앉으세요. \nB : 아니에요, 금방 갈 거니까 괜찮아요."}, {"id": "E202", "book": "4", "lesson": "4.13", "topic": "교육 제도", "vocabulary": "교육 제도", "grammar": "V/A도록 + clause", "note": "- Đứng sau động từ và một số tính từ, \n- có nghĩa tương đương trong tiếng Việt là 'để mà ..., đến mức ..., đến ...' \n=> dùng để thể hiện một mức độ, tiêu chuẩn, phương thức, giới hạn về thời gian. \n\n+ 좋은 대학에 입학할 수 있도록 열심히 공부하겠습니다. \n+ 시험에 붙었다는 말을 듣고 눈물이 나도록 기뻤다. \n+ 그는 몸살이 나도록 열심히 일을 했다. \n\nA : 한국에서는 밤늦도록 학원에서 공부하는 학생들이 많다고 들었어요. \nB : 네, 대학에 진학하려면 어쩔 수 없어요. \n\nA : 부모님께서 걱정하지 않으시도록 고향에 전화를 자주 하세요. \nB : 네, 알겠습니다."}, {"id": "E203", "book": "4", "lesson": "4.13", "topic": "교육 제도", "vocabulary": "입시", "grammar": "A(으)ㄴ/V는 + 데다가 + clause", "note": "- Đứng sau động từ, tính từ, danh từ, \n- có nghĩa tương đương trong tiếng Việt là 'cộng thêm , thêm vào đó' \n=> dùng để nói lên mức độ nghiêm trọng hơn khi kết hợp trạng thái trước và trạng thái sau. \n+ Sau danh từ và tính từ không có phụ âm cuối thì dùng -ᄂ 데 다가 có phụ âm cuối thì dùng -은 데다가. \n+ Trường hợp động từ ở thì hiện tại thì thêm -는 데다가. \n+ Động từ ở thì quá khứ thì thêm -ᄂ 데다가 sau nguyên âm, thêm -은 데다가 sau phụ âm. \n\n+ 한국은 입시 경쟁이 치열한 데다가 교육열도 높아서 사교육을 많이 받아요. \n+ 교통이 불편한 데다가 멀어서 학교 근처로 이사하려고 해요.\n+ 화 씨는 예쁜 데다가 성격도 좋아서 친구들에게 인기가 많아요. \n\nA : 한국 고등학생들은 집에 너무 늦게 들어가는 것 같아요. \nB : 학교에서 늦게까지 공부하는 데다가 학원까지 다녀서 그래요. \n\nA : 왜 이렇게 늦게 왔어요? \nB : 늦게 일어난 데다가 길이 막혀서 늦었어요."}, {"id": "E204", "book": "4", "lesson": "4.13", "topic": "교육 제도", "vocabulary": "교육", "grammar": "V/A(으)며 + clause", "note": "- Đứng sau động từ, tính từ và danh từ, \n- có nghĩa tương đương trong tiếng Việt là 'và', \n=> dùng để liệt kê một cách đối xứng hai hành vi hoặc 2 trạng thái trở lên. \n+ Thêm -며vào sau từ có tận cùng là nguyên âm hoặc là phụ âm ᄅ, \n+ thêm -으며vào sau từ có tận cùng là phụ âm. \n(*) Thường dùng trong văn viết. \n\n+ 올해 대학수학능력시험 원서 마감은 9월 20일이며, 시험은 11월에 시행된다. \n+ 시민들을 위한 편의 시설이 잘 갖춰져 있으며, 이용률도 높습니다. \n+ 동해 바다는 맑으며 푸르러서 한번 보면 그 경치를 잊지 못한다. \n\nA : 지하철은 어떤 점이 좋다고 생각하십니까? \nB : 다른 교통수단에 비해 이용이 편리하며 버스나 승용차보다 빠른 것이 좋다고 생각합니다. \n\nA : 서울은 어떤 곳입니까? \nB : 한국의 수도이며 정치·경제·문화의 중심지입니다. \n\n(*) Có khi dùng để thể hiện một hành động hay một trạng thái xảy ra hoặc duy trì khi làm một hành động khác. Nếu đứng sau động từ thì có nghĩa giống như -(으)면서. \n\n예) 전국 곳곳을 다니며 어려운 이웃을 돕는 활동을 해 왔다."}, {"id": "E205", "book": "4", "lesson": "4.14", "topic": "생활과 환경", "vocabulary": "환경 문제", "grammar": "A(으)ㄴ/V는 + 반면(에) +  clause", "note": "- Đứng sau động từ, tính từ, \n- có nghĩa tương đương trong tiếng Việt là 'đối ngược với, ngược lại' \n=> dùng để thể hiện một sự thật đối ngược với sự thật phía trước, có thể lược bỏ trợ từ 에. \n+ Khi dùng ở thì hiện tại, sau động từ dùng -는 반면에, \n+ sau tính từ dùng -(으)ᄂ 반면에. \n+ Khi dùng ở thì quá khứ thì sau cả động từ và tính từ đều dùng -(으)ᄂ 반면에. \n \n+ 대기오염은 심해진 반면(에) 수질오염은 좀 줄었다. \n+ 최근 자가용 이용은 준 반면(에) 지하철 이용은 늘었다. \n+ 새로 나온 약은 효과가 좋은 반면(에) 부작용이 심하다. \n\nA : 요즘 차를 두고 자전거로 다니시지요? \nB : 네, 자전거는 조금 불편한 반면(에) 건강에도 좋고 환경보호에도 도움이 되거든요. \n\nA : 새로 취직한 회사는 어때요? \nB : 이 회사는 월급은 많은 반면(에) 일이 너무 힘들어요."}, {"id": "E206", "book": "4", "lesson": "4.14", "topic": "생활과 환경", "vocabulary": "오염원", "grammar": "V(으)ㄹ + 정도이다.", "note": "- Đứng sau động từ và có nghĩa là 'đến mức ...'. \n=> Biểu hiện sự tương ứng phù hợp với giá trị hoặc tính chất ở hành động ở trước. \n- Có thể dùng với cấu trúc‘-(으)ᄅ 정도로. \n\n+ 요즘은 황사가 아주 심해져서 마스크를 써야 할 정도이다. \n+ 어제는 두통이 너무 심해서 일을 할 수 없을 정도였어요. \n+ 비가 온 후 서울에 파란 하늘이 보일 정도로 공기가 맑아졌어요. \n\nA : 어제 야구 경기가 끝난 후 쓰레기가 아주 많이 나왔다면서요?\nB : 네, 쓰레기가 너무 많아서 자원봉사자들이 밤새도록 치워야 할 정도였어요. \n\nA : 시험문제가 아주 쉬웠어요?\nB : 네, 공부를 거의 안 했는데 틀린 것이 별로 없을 정도였어요."}, {"id": "E207", "book": "4", "lesson": "4.14", "topic": "생활과 환경", "vocabulary": "환경보호", "grammar": "N에 + 따르면", "note": "- Đứng sau danh từ, có nghĩa tương đương trong tiếng Việt là ‘nếu theo...thì ...’, \n=> dùng để thể hiện một căn cứ, một tiêu chuẩn cho một tình huống nào đó. \n- Thường dùng để trích dẫn lời của ai đó hoặc kết quả nào đó. \n\n+ 조사 결과에 따르면 최근 서울의 대기오염이 줄었다고 한다.\n+ 보도에 따르면 지구온난화 때문에 올여름 무더위가 심할 거라고 한다. \n+ 안내 방송에 따르면 비행기가 연착한다고 한다. \n\nA : 내일 등산을 가기로 했는데 날씨가 어떻다고 해요? \nB : 일기예보에 따르면 날씨는 맑지만 황사가 심할 거라고 해요. \n\nA : 디엠 씨가 한국에서 잘 지내나요? \nB : 네, 디엠 씨 이메일에 따르면 별문제가 없대요."}, {"id": "E208", "book": "4", "lesson": "4.15", "topic": "옛날이야기", "vocabulary": "이야기 / 장르", "grammar": "V자 + clause", "note": "- Đứng sau động từ, có nghĩa tương đương trong tiếng Việt là 'mới vừa ...' \n=> để thể hiện sự tiếp sau hành động trước. \n\n+ 영화 ‘춘향전’의 상영이 끝나자 관객들은 모두 박수를 쳤다. \n+ 엄마가 자장가를 불러 주자 아이는 울음을 그치고 잠을 잤다. \n+ 졸던 학생들이 쉬는 시간이 되자 책상에 엎드려 자기 시작했다. \n\nA : 도깨비는 닭이 울자 사라졌다고 해요. \nB : 맞아요. 도깨비는 새벽닭 우는 소리를 가장 싫어하지요. \n\nA : 와, 그렇게 심하게 울던 아가를 어떻게 재웠대요? \nB : 조용한 음악을 들려주자 잠이 들었대요."}, {"id": "E209", "book": "4", "lesson": "4.15", "topic": "옛날이야기", "vocabulary": "인물", "grammar": "V다 + 보니까 + clause", "note": "- Đứng sau động từ và \n- có nghĩa tương đương trong tiếng Việt là ‘thử làm gì đó thì ...’. \n=> Trong quá trình làm một việc gì đó thì phát hiện ra một sự thật mới hoặc chuyển sang một trạng thái khác. \n- Có thể dùng cấu trúc -다가 보니까, -다 보니. \n\n+ 한국 동화를 읽다 보니까 한국어 공부가 더 재미있어졌어요. \n+ 일기를 계속 쓰다 보니까 저도 모르게 쓰기 실력이 늘더라고요. \n+ 한국에 와서 김치를 먹다 보니 이제는 김치 없으면 밥을 못 먹어요. \n\nA : 뭐야? 왜 이렇게 늦은 거야?\nB : 미안, 드라마가 재미있어서 계속 보다 보니까 시간이 이렇게 많이 지났네. \n\nA : 그 사람 첫인상이 별로라고 했잖아요. \nB : 뭐, 만나다 보니까 첫인상하고 많이 다르더라고요. \n\n(*) -다 보면 và -다 보니까 có nghĩa là trong quá trình làm một việc gì đó thì phát hiện ra một sự thật mới hoặc chuyển sang một trạng thái khác. -다 보니까 mang tính kết quả thì -다 보면 mang tính phỏng đoán do đó không dùng -다 보면 ở dạng quá khứ.\n예) 계속 하다 보니까 익숙해졌어요. (○) \n계속 하다 보면 익숙해졌어요. (×) → 계속 하다 보면 익숙해질 거예요.(○)"}, {"id": "E210", "book": "4", "lesson": "4.15", "topic": "옛날이야기", "vocabulary": "", "grammar": "A(으)ㄴ/V는 + 척하다.", "note": "- Đứng sau động từ hay tính từ, \n- có nghĩa tương đương trong tiếng Việt là 'làm như ..., giả vờ ...'. \n=> thể hiện một hành động giả dối nào đó. \n+ Sau động từ dùng -는 척하다, \n+ sau tính từ không có phụ âm cuối dùng -ᄂ 척하다, \n+ sau tính từ có phụ âm cuối dùng -은 척하다. \n\n+ 호랑이 울음소리에 소년은 죽은 척했습니다.\n+ 아이는 안 먹는 척하면서 몰래 먹었다고 합니다.\n+ 왕은 자신의 신분을 감추기 위해 바보인 척했다고 합니다. \n\nA : 왜 그러고 있어요?\nB : 쉿! 자는 척해야 옛날 이야기해 달라고 안 할 거예요. \n\nA : 제가 한 이야기에 대해 모르는 척해 주세요. \nB : 알겠어요. 아무한테도 말하지 않을게요."}, {"id": "E211", "book": "5", "lesson": "5.1", "topic": "만남과 교류", "vocabulary": "만남과 이별", "grammar": "V/A게 + clause", "note": "- Đứng sau động từ hay tính từ, \n- có nghĩa tương đương trong tiếng Việt là ‘để ..., để được ...’, \n=> dùng để thể hiện mục đích hay lý do của hành động ở mệnh đề sau. Nghĩa là mệnh đề trước -게 chính là mục đích dẫn đến hành động của mệnh đề sau. \n\n+ 이 선생님께서는 제가 공부를 계속 할 수 있게 도와주셨습니다. \n+ 공부 좀 하게 조용히 해 주세요.\n+ 늦지 않게 서둘러서 출발합시다. \n\nA : 앞으로 어떤 일을 하고 싶으십니까? \nB : 한국 사람들이 베트남에 대해 제대로 알 수 있게 베트남에 대한 책을 쓰고 싶습니다. \n\nA : 아주 중요한 서류이니까 잃어버리지 않게 조심하세요. \nB : 네, 조심하겠습니다. \n\n(*) Khi diễn tả mục đích, kết quả, mức độ, phương cách của một hành động thì –게 có ý nghĩa giống như  –도록. \n예) \n+ 이 선생님께서는 제가 공부를 계속 할 수 있도록 도와주셨습니다. \n+ 아주 중요한 서류이니까 잃어버리지 않도록 조심하세요."}, {"id": "E212", "book": "5", "lesson": "5.1", "topic": "만남과 교류", "vocabulary": "교류", "grammar": "V(으)ㄹ걸.", "note": "- Đứng sau động từ, có nghĩa tương đương trong tiếng Việt là ‘phải chi’, giá mà’, \n=> diễn tả sự hối hận hay tiếc nuối của người nói. \n- Thường dùng để nói một mình. \n\n+ 부모님이 한국으로 유학을 가라고 하셨을 때 유학을 갈걸. \n+ 한국에 오기 전에 한국어 공부를 열심히 할걸. \n+ 비도 안 오는데 우산을 괜히 가지고 왔네. 가져오지 말걸. \n\nA : 아, 배고프다. 뭐 먹을 것 좀 없어?\nB : 아직도 저녁을 안 먹었어? 음식을 좀 남겨둘걸. \n\nA : 아이가 군대에 가서 마음이 허전하시지요?\nB : 그럼요. 군대 가기 전에 좀 더 잘 해 줄걸 하는 생각이 많이 들어요. \n\n(*) Ngoài ra -(으)ᄅ걸 còn đứng sau động từ hay tính từ , dùng trong trường hợp nói chuyện với bạn bè, người rất thân hay người nhỏ hơn mình để diễn tả một sự phán đoán về một việc gì đó không chắc chắn, nghĩa tương đương trong tiếng Việt là ‘chắc có lẽ là’. Thông thường sự phán đoán này khác với những gì người nghe đã biết hoặc đang mong đợi; cũng có khi là một sự phản bác nhẹ nhàng hay một sự cảm thán. \n예)  +  A  : 사무실에 아직 사람들이 있겠지? \n           B  : 벌써 여덟 시야. 모두 퇴근했을걸. \n       +  A  : 오늘 모임에 수진이도 오지?\n           B  : 아니, 오늘 못 올걸. 오늘 다른 일이 있다고 했어."}, {"id": "E213", "book": "5", "lesson": "5.1", "topic": "만남과 교류", "vocabulary": "문화", "grammar": "N(으)로 인해", "note": "- Đứng sau danh từ, có nghĩa tương đương trong tiếng Việt là ‘do, nhờ, bởi’, \n=> diễn tả nguyên nhân hay lý do của một tình trạng nào đó. \n- Chủ yếu dùng trong văn viết hoặc ở những nơi trang nghiêm. \n\n+ 저는 박 선생님과의 특별한 인연으로 인해 한국에 오게 되었습니다. \n+ 우천으로 인해 경기가 취소되었습니다.\n+ 강풍으로 인해 비행기 출발이 지연되고 있습니다. 불편을 끼쳐 죄송합니다. \n\nA : 한국에서의 유학 생활은 어떠셨나요? \nB : 처음에는 문화적 차이로 인해 어려움을 좀 겪었습니다. \n\nA : 한국에 오시게 된 계기는 무엇이었나요? \nB : 여행을 갔다가 한국 친구를 알게 되었습니다. 그 친구와의 인연으로 인해 한국에 오게 되었습니다. \n\n(*) Trong cấu trúc (으)로 인해 có thể tỉnh lược đi 인해 và chỉ dùng (으)로 cũng không làm thay đổi nghĩa. Chính vì thế (으)로 인해 đôi khi được dùng dưới dạng (으)로 hay thay bằng (으)로 해서 vẫn mang lại ý nghĩa hoàn toàn không khác biệt. \n예)  + 갑자기 내린 눈으로 교통이 마비되었다. \n       + 그 일로 해서 우리는 학교에서 유명해졌다."}, {"id": "E214", "book": "5", "lesson": "5.2", "topic": "서울", "vocabulary": "역사 및 전통", "grammar": "A(으)ㄴ/V는 + 만큼 + clause", "note": "- Đứng sau động từ, tính từ hay danh từ, \n- có nghĩa tương đương trong tiếng Việt là ‘bằng với, xứng với, giống như, đến mức’ \n=> dùng để thể hiện sự so sánh với nội dung của mệnh đề trước hay một mức độ, một số lượng tương đương giữa mệnh đề sau và mệnh đề trước. Ngoài ra, cấu trúc này có khi dùng để diễn tả nội dung của mệnh đề trước là ‘căn cứ’ hay ‘nguyên nhân’ của nội dung ở mệnh đề sau. \n\n+ 경주는 유명한 관광지인 만큼 매년 그곳을 찾는 방문객 수도 증가하고 있다. \n+ 서울은 역사가 긴 만큼 많은 변화와 발전을 해왔고 지금에 이르렀다. \n+ 서울시가 외국인 관광객을 위한 편의 시설을 늘리는 만큼 서울을 찾는 관광객도 늘어 날 것이다. \n\nA : 서울이 전보다 쾌적해진 것 같아요. 특별한 이유가 있나요? \nB : 전에는 주택, 도로, 상하수도 시설 등 도시 기능을 확충하는데 신경을 썼지만, 지금은 디자인과 편의 시설에 신경을 많이 쓰는 만큼 도시가 많이 쾌적해졌지요. \n\nA : 혹시 몽골어로도 안내해 주시나요? \nB : 네, 물론이에요. 주말에는 외국인 관람객이 붐비는 만큼 다양한 언어로   안내를 합니다."}, {"id": "E215", "book": "5", "lesson": "5.2", "topic": "서울", "vocabulary": "관광", "grammar": "V/A(으)ㄹ + 뿐이다.", "note": "- Đứng sau động từ hay tính từ, có nghĩa trong tiếng Việt là ‘chỉ, chỉ là’, \n=> diễn tả 1 sự việc không hơn không kém với mệnh đề phía trước. \n- Tương tự với cách biểu hiện này có khi dùng -(으)ᄅ 따름이다. \n- Thường thì -(으)ᄅ 뿐이다 dùng trong văn viết hay văn nói, còn -(으)ᄅ 따름이다 thì được dùng trong văn viết hay một hoàn cảnh thật trang nghiêm. \n\n+ 이곳에는 전에 작은 집들만 있었을 뿐, 큰 아파트는 찾아볼 수 없었어요. \n+ 함께 여행 온 그 친구는 쇼핑만 할 뿐이었고 다른 것에는 관심이 없었다. \n+ 이 도로는 전보다 차선을 하나 더 늘렸을 뿐인데 이렇게 차가 잘 빠지네요. \n\nA : 흐엉 씨는 서울에 가 본 적있나요? \nB : 아니요, 그냥 TV드라마나 영화에서만 서울을 봤을 뿐이에요. \n\nA : 서울이 예전에 비해서 많이 달라졌죠? \nB : 그러게 말이에요. 예전에 서울에 왔을 때는 갈 만한 곳이 몇 군데뿐이었는데 지금은 갈 곳이 너무 많아져서 어디에 갈지 고민이에요."}, {"id": "E216", "book": "5", "lesson": "5.2", "topic": "서울", "vocabulary": "사회 문제 및 변화", "grammar": "N(으)로서", "note": "- Đứng sau danh từ, có nghĩa tương đương trong tiếng Việt là ‘với tư cách là’, \n=> thể hiện thân phận, vị trí hay tư cách của danh từ đứng trước đó. \n\n+ 한강은 한국의 대표적인 강으로서 서울의 중심을 동서로 가로지른다.\n+ 서울은 한국의 수도로서 정치, 경제, 문화 등 여러 기능의 중심지이다. \n+ 평소에 한국 드라마를 즐겨 보는 팬으로서 TV에 나왔던 장소에 꼭 한번 가보고 싶다. \n\nA : 서울에 있는 명동이라는 곳이 그렇게 유명해? \nB : 당연하지. 명동은 서울의 쇼핑 일번지로서 관광객이 많이 찾는 곳이야. \n\nA : 북촌 한옥 마을은 어떤 곳인가요? \nB : 그곳은 서울 중심지에 있는 한옥 밀집 지역으로서 전통 한옥을 구경하고 옛날 문화도 직접 체험할 수 있는 곳이에요. \n\nSự khác biệt giữa (으)로서 và (으)로써\n+ (으)로서 có nghĩa là ‘với tư cách là’, \n+ còn (으)로써 có nghĩa là ‘bằng cách’, thể hiện một phương pháp hay một phương tiện. \n예) 자신의 노력으로서 그 일을 극복해 내야 한다. (×) \n       자신의 노력으로써 그 일을 극복해 내야 한다. (○)"}, {"id": "E218", "book": "5", "lesson": "5.3", "topic": "현대인의 건강", "vocabulary": "건강 관리", "grammar": "V(으)ㄴ + 채로", "note": "- Đứng sau động từ, \n- có nghĩa tương đương trong tiếng Việt là ‘giữ nguyên trạng thái, trong trạng thái, để nguyên, để y vậy’, \n=> thể hiện một hành vi nào đó vẫn được giữ nguyên trạng thái đang tiến hành và tiếp nối bởi nội dung của mệnh đề phía sau. \n- Cấu trúc này không dùng ở thì hiện tại hay dự đoán một điều gì đó sẽ xảy ra trong tương lai. \n\n책을 읽다가 눈을 감은 채로 잠시 생각에 잠겼습니다. \n그 사람은 고개를 숙인 채로 아무 말도 하지 않았어요. \n밥을 많이 먹은 채로 계속 앉아 있으니 속이 더부룩합니다. \n\nA  준비 운동을 꼭 해야 되나요? 빨리 물에 들어가고 싶은데. \nB  준비 운동을 하지 않은 채로 수영을 하면 심장에 무리가 갈 수 있습니다.  준비 운동부터 하고 들어가세요. \n\nA  흐엉 씨, 감기에 걸렸어요? \nB  네, 어제 창문을 열어 놓은 채로 자서 그런가 봐요."}, {"id": "E219", "book": "5", "lesson": "5.3", "topic": "현대인의 건강", "vocabulary": "식품", "grammar": "V/A(으)ㄹ + 수밖에 + 없다", "note": "- Đứng sau động từ hay tính từ, \n- có nghĩa tương đương trong tiếng Việt là ‘không thể nào khác được, chỉ còn có cách là ...’, \n=> diễn tả ngoài cách đó không còn cách nào khác. \n\n+ 운동을 하지 않으면 건강이 나빠질 수밖에 없지요. \n+ 아무리 참으려고 해도 너무 화가 나서 화를 낼 수밖에 없었어요. \n+ 오늘 아침에 지각을 했는데 교실에 들어갈 용기가 나지 않아 1교시가 끝날 때 까지 교실 밖에서 기다릴 수밖에 없었다. \n\nA : 요즘 아이들은 전에 비하여 체격이 참 좋아진 것 같아요. \nB : 그럼요, 전보다 잘 먹으니 체격이 좋아질 수밖에 없지요. 그런데 너무 잘 먹고 운동을 하지 않아 비만아가 되는 경우도 많아요. \n\nA : 기숙사 옆 방 친구가 시끄럽게 떠들어서 공부를 할 수 없는데 어떻게 하면 좋을까요? \nB : 여러 사람이 함께 생활하다 보면 문제가 생길 수밖에 없어요. 그 친구와 한번 이야기 해 봐야 할 것 같네요."}, {"id": "E220", "book": "5", "lesson": "5.3", "topic": "현대인의 건강", "vocabulary": "질병 및 증상", "grammar": "V/A되", "note": "- Đứng sau động từ hay tính từ, \n- có nghĩa tương đương trong tiếng Việt là ‘nhưng mà, nhưng với điều kiện là ...’ \n=> dùng để thể hiện ý công nhận một việc nào đó nhưng đồng thời cũng đưa ra thêm điều kiện cho sự việc đó. \n- Ngoài ra cấu trúc này còn được dùng để mô tả và giải thích cụ thể nội dung liên quan đến một sự thật nào đó. \n- Cấu trúc này thường được dùng trong văn viết và mang phong thái lịch sự. \n\n운동을 하되 자신에게 맞는 운동을 하는 것이 필요하다. \n하고싶은것을하되자신의행동에책임을져야합니다.\n근무 시간에 인터넷을 사용하되 채팅은 하지 못하게 되어 있다. \n\nA 고혈압인데 짠 것을 먹으면 안 되겠지요?\nB 꼭 그렇지는 않아요. 하지만 짠 음식을 드시되 너무 많이 드시지는 마세요. \n\nA 요즘엔 자식을 너무 귀하게 키워서 아이들이 버릇이 없는 것 같아요. \nB 귀하게 키우되 버릇없이 키우면 안 되지요."}, {"id": "E223", "book": "5", "lesson": "5.4", "topic": "사회와 봉사", "vocabulary": "불우이웃", "grammar": "V아/어다가", "note": "- Đứng sau động từ, có nghĩa tương đương trong tiếng Việt là ‘...rồi....’, \n=> diễn tả việc hoàn thành một hành động nào đó xong, rồi mang kết quả của hành động đó đến một nơi khác để thực hiện một hành động khác. \n- Có thể dùng thay thế cấu trúc -아/어다 가 bằng cấu trúc -아서/어서 hay -아/어 가지고, nhưng cấu trúc -아/어다가 khác với những cấu trúc khác ở chỗ không thể hiện phương pháp, phương tiện, lý do hay nguyên nhân. \n- Khi viết ngắn cấu trúc này được tỉnh lược thành -아/어다. \n\n일요일에는 집에서 밥을 지어다가 노숙자에게 주는 봉사자를 종종 볼 수 있다. \n길가에 피어 있는 꽃을 꺾어다가 꽃병에 꽂아 두었다.\n학교가 끝나면 은행에 들러서 돈을 좀 찾아다가 어머니께 드려야 해요. \n\nA  지영 씨가 아직도 도착하지 않았네요. 곧 버스가 출발할 텐데 걱정이에요. \nB  제가 조금 전에 전화해서 물어봤는데, 동생이 아파서 약을 사다가 주고 오느라 조금 늦게 출발했대요. \n\nA  주말이 다가오고 있는데 무슨 특별한 계획이라도 있으세요? \nB  아니요, 이번 주말에는 그냥 집에 있으려고요. 집에 가는 길에 DVD가게에 들러서 그동안 보고 싶었던 영화들이나 빌려다가 주말 내내 볼까 생각 중이에요."}, {"id": "E224", "book": "5", "lesson": "5.4", "topic": "사회와 봉사", "vocabulary": "복지시설", "grammar": "V았/었더니", "note": "+ một là, khi nói về một sự việc nào đó diễn ra trễ hơn so với sự việc khác trong quá khứ, có thể dịch tương đương với tiếng Việt là ‘thế nhưng...đã rồi’; \n   + hai là, khi nói về nguyên nhân hoặc lý do dẫn đến kết quả nào đó trong quá khứ, có thể dịch tương đương với tiếng Việt là ‘thế là...’ \n\n+ 이번 행사에 자원 봉사를 하려고 지원서를 보냈더니 벌써 마감이 되었다고 연락이 왔네요. \n+ 오랜만에 일찍 일어나서 학교에 갔더니 휴강되었다. \n+ 냉장고에 오래 두었던 과일을 꺼내 먹었더니 배가 아파요. \n\nA  벌써모임이시작한지1시간이지났는데지영이가안보이네.오늘여기에온다고 하지 않았어? \nB  응, 원래 오기로 했는데 아까 집에 전화해 봤더니 어젯밤에 갑자기 쓰러져서 지금 병원에 입원해 있대. \n\nA  텔레비전에서 심장병 어린이 돕기 모금 운동 광고가 나오고 있네요. ARS로 전화를 걸면 1,000원을 기부할 수 있는 거 맞지요? \nB  네, 저도 어제 그 광고를 보고 안내된 ARS 번호를 눌렀더니 1,000원이 결제되더라고요."}, {"id": "E225", "book": "5", "lesson": "5.4", "topic": "사회와 봉사", "vocabulary": "봉사자", "grammar": "V자면", "note": "- Đứng sau động từ, có nghĩa tương đương trong tiếng Việt là ‘nếu như muốn cùng, nếu như muốn’, \n=> diễn tả một sự giả định về một ý đồ hay một mục đích nào đó hay là đưa ra một tình huống dự đoán trước và nói lên điều kiện ở mệnh đề theo sau. \n- Cấu trúc này không thể dùng chung với thể phủ định như 못 hoặc -지 못하다,  지 말다. \n- Có thể được thay bằng cấu trúc -으 려면 mà không làm thay đổi nghĩa. \n\n그 나라 사람들을 배고픔에서 구하자면 지금보다 훨씬 많은 구호기금이 필요해요. \n컴퓨터 타자 속도를 늘리자면 열심히 연습하는 수밖에 없다. \n기말 시험에서 좋은 점수를 받자면 지금보다 두 배는 더 열심히 노력해야 한다. \n\nA  오늘은 아침부터 계속 비빔밥이 먹고 싶더라고요. 오늘 점심으로 비빔밥 어때요? \nB  비빔밥을 먹자면 시청 근처에 새로 생긴 식당으로 가는 게 좋을 것 같아요. 맛있다고 소문이 났거든요. \n\nA  선생님, 피아노를 잘 치자면 어떻게 연습을 해야 할까요? \nB  기초적인 테크닉을 잘 익혀야 합니다. 그리고 아무리 지루해도 참고 열심히 연습해 야피아노를잘칠수있어요. \n\nMẫu câu -자면không thể kết hợp với các cấu trúc phủ định như 못hay -지 못하다, -지 말다nhưng chỉ có thể đi với cấu trúc phủ định 안 hay -지 않다. \n예)  후회하지 말자면 열심히 공부해 두어야 합니다. (×) \n       후회하지 않자면 열심히 공부해 두어야 합니다. (○)"}, {"id": "E229", "book": "5", "lesson": "5.5", "topic": "뉴스와 신문", "vocabulary": "매체", "grammar": "V고 말다", "note": "- Đứng sau động từ, \n- có nghĩa tương đương trong tiếng Việt là ‘cuối cùng thì, kết cuộc thì’, \n=> dùng để diễn tả một sự tiếc nuối vì một việc nào đó đã xảy ra ngoài ý muốn hoặc diễn tả một kết quả đạt được sau quá trình phấn đấu vất vả. \n\n+ 급하게 뛰어가다가 옷에 커피를 쏟고 말았어요.\n+ 며칠 동안 밤을 새워서 보고서를 다 끝내고 말았어요.\n+ 오늘 신문을 보니까 결국 정부가 주민들의 반대로 쓰레기장 건설을 포기하고 말았더군요. \n\nA  이웃집에도 도둑이 들었다면서요? \nB  네, 경찰을 불렀지만 결국 놓치고 말았대요. \n\nA  왜 이렇게 늦게 왔어요? \nB  소파에 앉아 있다가 깜빡 잠이 들고 말았어요. 미안해요. \n\nCó khi dùng -고말겠다để thể hiện ý chí mạnh mẽ muốn làm một việc gì đó của người nói. Lúc này chủ ngữ luôn ở ngôi thứ nhất. \n예)  다음시험에서는꼭일등하고말겠습니다. (○) \n       너는 꼭 성공하고 말겠다. (×)"}, {"id": "E230", "book": "5", "lesson": "5.5", "topic": "뉴스와 신문", "vocabulary": "신문", "grammar": "V(ㄴ/는)/A다지요?", "note": "- Đứng sau động từ hay tính từ, \n- có nghĩa tương đương trong tiếng Việt là ‘nghe nói...phải không?’, \n=> người nói dùng để hỏi lại hoặc kiểm tra lại thông tin mà mình đã biết. \n+ Sau động từ tận cùng là nguyên âm và động từ có phụ âm cuối là ᄅ thì thêm -ᄂ다지 요?,  sau các phụ âm còn lại thì thêm -는다지요?, \n+ sau 있다, 없다 hay sau tính từ thì thêm -다지요?, \n+ sau -이다, 아니다 thì thêm -(이)라지요?. \n\n이번 주에 한 달 예정으로 대통령이 유럽 순방을 떠난다지요? \n토마토와 마늘이 세계 10대 건강 음식 중 하나라지요? \n제주도는 봄에 유채꽃이 노랗게 피어서 아주 아름답다지요? \n\nA  요즘 실업률이 좀 떨어졌다지요? \nB  네, 경기가 좋아지고 있나 봐요. \n\nA  유나 씨가 이번 방학 때 배낭여행을 갈 거라지요?\nB  그렇대요. 그래서 지도를 보면서 열심히 계획을 짜고 있대요."}, {"id": "E231", "book": "5", "lesson": "5.5", "topic": "뉴스와 신문", "vocabulary": "기사 및 기자", "grammar": "V는 한", "note": "- Đứng sau động từ, \n- có nghĩa tương đương trong tiếng Việt là ‘trong trường hợp, chỉ với điều kiện’, \n=> diễn tả điều kiện, tiền đề hay yêu cầu về 1 hành động hay 1 trạng thái nào đó. \n\n+ 양측이 서로 양보하지 않는 한 합의점에 도달할 수 없을 거예요.\n+ 뉴스에서 사실을 정직하게 보도하는 한 사람들은 언론을 신뢰할 겁니다. \n+ 신문사들이 지금처럼 발행부수를 늘리기 위해서 계속 경쟁하는 한 신문 구독료가 오를 것 같지는 않아요. \n\nA  그 사이트에서 방송이나 뉴스를 보려면 어떻게 해야 해요? \nB  유료 회원으로 가입하지 않는 한 볼 수 없어요. \n\nA  이 노트북 환불도 가능한가요? \nB  포장을 뜯지 않았고 영수증을 가지고 계시는 한 가능합니다. \n\n(*) 될수있는한hay là 가능한한có thể được dùng với ý nghĩa là 가능하면 (nếu có thể thì, nếu được thì ) và -에관한한 được dùng với ý nghĩa là -에 대해서 (về ...). \n예)  될 수 있는 한 빨리 일을 처리해 주세요. \n       퀴즈에 관한 한 정우 씨를 이길 사람이 없어요."}, {"id": "E232", "book": "5", "lesson": "5.6", "topic": "역사 속의 인물", "vocabulary": "인물", "grammar": "V다시피", "note": "- Tương đương với nghĩa tiếng Việt là \"như....đã....\", \n- thường kết hợp với các động từ biểu hiện sự cảm nhận, tri giác như: \"biết, nhìn, cảm thấy, nghe ....\" tạo nên nghĩa “như ... đã biết, như ... đã nghe, như ... đã thấy” và thường được dùng khi khẳng định sự xác nhận nội dung ở vế sau. \n- Trường hợp cấu trúc này được dùng ở cuối câu dưới dạng 다시피 하다, biểu hiện nghĩa \"Mặc dù trên thực tế không hoàn toàn giống như ý nghĩa mà động từ đứng trước cấu trúc biểu hiện nhưng cũng gần như vậy\". Trong trường hợp này, nó có thể kết hợp với mọi động từ. \n\n+ 여러분도 아시다시피 한글을 창제한 분은 세종대왕입니다.\n+ 보시다시피 한국의 돈에는 한국을 빛낸 인물의 초상이 그려져 있습니다. \n+ 졸업을 앞둔 대학생들이 좋은 회사에 취직하기 위해서 도서관에서 밤을 새우다시피 합니다. \n\nA  왜 이렇게 피곤해 보이세요? 무슨 일 있으세요? \nB  요즘 새로운 약품 개발 때문에 실험실에서 살다시피 했어요. \n\nA  민수 씨는 어떻게 사법 고시에 합격했대요? \nB  민수 씨의 공부법은 잘 모르지만 그는 항상 도서관에서 밤을 새우다시피 했어요. \n\nA  한국의 문화유산이 외국에 많이 유출되어 있네요. \nB  네, 아시다시피 식민 지배와 전쟁으로 문화유산을 잘 보존하지 못했어요."}, {"id": "E233", "book": "5", "lesson": "5.6", "topic": "역사 속의 인물", "vocabulary": "", "grammar": "V(으)ㅁ으로써", "note": "- Tương đương với nghĩa \"với việc..., bằng việc.........\", \n=> được sử dụng khi nói đến kết quả ở vế sau có được do đã thực hiện hành động nào đó ở vế trước. \n\n+ 그는 주어진 일에 최선을 다함으로써 주변 사람들로부터 좋은 평판을 얻을 수 있었다. \n+ 큰 위기에서 자신을 희생하는 길을 택함으로써 그는 위기에서 벗어날 수 있었다. \n+ 한국이 2010 월드컵에서 16강에 진출함으로써 한국 축구 실력을 세계에 널리 알릴 수 있게 되었다. \n\nA  왜 세계의 유명한 인물들이 화폐에 등장하지요? \nB  사람들은 유명한 인물을 화폐에 표시함으로써 생활 속에서 그들의 모습을 닮아가려고 하기 때문이에요. \n\nA  퇴계 이황 선생이 누구예요? \nB  퇴계 이황은 조선 중기의 학자예요. 그는 도산서원을 세워 학생들을 가르치고 학문 을 연구함으로써 한국의 교육 발전에 기여한 사람이에요."}, {"id": "E234", "book": "5", "lesson": "5.6", "topic": "역사 속의 인물", "vocabulary": "", "grammar": "N이며", "note": "- Tương đương với nghĩa tiếng Việt là \"đồng thời là..., cũng là..., còn là...\", \n=> được dùng để liên kết giữa hai danh từ biểu hiện ý nghĩa chủ thể của hai danh từ đó là giống nhau. Nói cách khác, nó được sử dụng khi một chủ thể đồng thời mang hai ý nghĩa biểu hiện bởi hai danh từ đi kèm. \n\n+ 그 사람은 사업가이며 정치가로 알려져 있다.\n+ 율곡 이이는 조선 시대의 대표적인 학자이며 위대한 정치가이다.\n+ 한국은 반도 국가이며 작은 나라이었기 때문에 외국으로부터 많은 침략을 받았다. \n\nA  신사임당은 어떤 분이세요? \nB  신사임당은 시와 그림에 뛰어난 재주를 가진 예술가이며 훌륭한 어머니예요. \n\nA  모나리자를 그린 사람이 누구예요? \nB  이탈리아 출신의 화가 레오나르도 다빈치예요. 그는 천재 화가이며 조각가이며 과학자입니다."}, {"id": "E235", "book": "5", "lesson": "5.6", "topic": "역사 속의 인물", "vocabulary": "", "grammar": "V/A았/었더라면", "note": "- Tương đương với nghĩa tiếng Việt là \"chẳng hạn như..., nếu như đã...., giả dụ như ....\". \n=> Được dùng khi giả định về một tình huống đã không xảy ra hoặc không tồn tại trong thực tế. \n- Đứng sau biểu hiện này thường là kết quả xảy ra theo giả định và thường là các dạng -(았/었)을텐데, -(았/었)을 거예요, -(았/었)지요. \n\n+ 내가 조금 더 일찍 사회에 눈을 떴더라면 그렇게 어려운 일을 겪지 않았을 거예요. \n+ 세종대왕이 백성을 생각하는 마음이 크지 않았더라면 한글을 창제하지 못했을 거예요. \n+ 부모님이 민수를 좀 더 뒷받침해 주었더라면 그는 더욱 큰 인물이 되었을 거예요. \n\nA  베트남에서 호치민이 왜 그렇게 유명해요? \nB  호치민이 프랑스와의 협상을 통해 베트남의 독립을 시도하지 않았더라면, 현재의 베트남은 존재하지 않았을 거예요. \n\nA  노예해방은 인류의 역사를 크게 바꾸어 놓았지요? \nB  네, 에이브러햄 링컨 대통령이 없었더라면 노예해방은 이루어지지 않았을 거예요. \n\nKhác biệt giữa -았/었더라면 và -았/었다면\n-았/었더라면 có thể dễ dàng đổi và sử dụng dưới dạng -았/었다면 nhưng -았/었다면 có thể sử dụng để giả định cả tình huông có thực trong quá khứ và không có thực trong quá khứ nên phạm vi sử dụng của nó lớn hơn so với -았/었더 라면. \n예)  뚜안 씨가 그것을 먹었다면 큰일인데. (○) \n       뚜안 씨가 그것을 먹었더라면 큰일인데. (×)"}, {"id": "E236", "book": "5", "lesson": "5.7", "topic": "속담과 관용표현", "vocabulary": "속담", "grammar": "V(ㄴ/는)/A다고", "note": "- Có thể dịch tương đương trong tiếng Việt là ‘có câu rằng; lời rằng...’ \n=> được dùng sau các động từ, có tác dụng trích dẫn lại một câu thành ngữ, tục ngữ hay một lời nói của ai đó, với ngụ ý ‘cũng như câu nói...’. \n\n+ 팔은 안으로 굽는다고 어느 나라나 역사 교과서에는 자기 나라에 불리한 내용은 되도 록적게쓰려고한다. \n+ 비 온 뒤에 땅이 굳어진다고 한차례 큰 시련을 겪고 나니 직원들 간의 결속력이 더욱 강화됐다. \n+ 고기도 먹어본 사람이 잘 먹는다고 여행도 자주 해 본 사람이 용기를 내서 떠나는 것 같다. \n\nA  그 병원이 그렇게 유명해요? 병을 잘 고친다고 소문이 자자해요. \nB  발없는말이천리간다고어떻게알았는지시골에서도소문을듣고찾아온환자가 있을 정도예요. \n\nA  요즘 매일 늦게까지 열심히 일하는데도 업무 실적은 안 좋아서 너무 힘들어요. \nB  너무실망하지마.고생끝에낙이온다고지금은비록고생스러워도,이다음에는 아마 웃으면서 즐거워할 때가 있을 거야. \n\n(*) Cấu trúc này có chức năng đưa ra một lời giải thích ở vế sau căn cứ vào một sự thật phổ biển hay một câu tục ngữ nào đó nêu ra ở vế trước. \n예) 열 손가락 깨물어 아프지 않은 손가락이 없다고 부모님이 자식을 사랑하는 마음은 다 똑같다.하늘이 무너져도 솟아날 구멍이 있다고 아무리 큰 재난에 부딪히더라도 그것에서 벗어날 방법은 있기 마련이다."}, {"id": "E237", "book": "5", "lesson": "5.7", "topic": "속담과 관용표현", "vocabulary": "말과 관련된 속담", "grammar": "A(으)ㄴ/V는 법이다", "note": "- Có thể dịch tương đương trong tiếng Việt ‘hiển nhiên là; chắc chắn là...’. \n- Được dùng sau các động từ và 있다/없다 thể hiện ý nghĩa rằng nội dung của vế trước là một sự đương nhiên. \n\n속담에는 그 사회 구성원의 문화와 사고방식이 반영되는 법이다. \n아무리 좋은 말도 여러번 들으면 듣기 싫은법이다.\n진정한 자유에는 반드시 그에 대한 책임이 따르는 법이다. \n\nA  지난주에 친구한테 돈을 빌렸는데, 볼 때마다 빨리 갚으라고 해서 기분이 나빠요. \nB  다른 사람 돈을 빌렸으면 당연히 갚아야 하는 법이야. 기분 나빠하지 말고 얼른 갚아. \n\nA 이번 경기에서도 당연히 우리 팀이 이기겠지?\nB 그건 모르는 일이야. 길고 짧은 것은 대봐야 아는 법이니까."}, {"id": "E238", "book": "5", "lesson": "5.7", "topic": "속담과 관용표현", "vocabulary": "동물과 관련된 속담", "grammar": "A(으)ㄴ/V는 듯이", "note": "- Có thể dịch tương đương trong tiếng Việt là ‘thiếu điều như; cứ như là...’ \n- Được dùng sau động từ thể hiện động tác ở vế câu sau gần giống như một điều gì đó nêu lên ở vế câu trước. \n\n민우는 대학에 합격했다는 소식에 뛸 듯이 기뻐했다. \n금방 빗방울이 떨어질 듯이 하늘이 어두워지기 시작한다. \n아이는 눈을 감고 자는 듯이 가만히 누워 있었다. \n\nA  무슨 얘기야? 난 잘 모르겠는데? \nB  다 알면서 아무것도 모르는 듯이 시치미 떼지 마. \n\nA  요즘 조카가 자꾸 거짓말을 해서 걱정이에요. \nB  세살 버릇 여든까지 간다는 말이 있듯이 지금 나쁜 버릇을 고치지 않으면 나중에는 고치기 더 힘들 거예요. \n\n-듯이 được dùng nhiều trong những thành ngữ như sau. \n예) 땀이 비 오듯이 쏟아진다 \tMồ hôi đổ như mưa. \n      돈을 물 쓰듯이 쓴다 \t\tTiêu tiền như nước. \n      거짓말을 밥 먹듯이 한다 \tNói dối như ăn cơm bữa.\n      불을 보듯이 뻔하다 \t\tThường như nhìn thấy lửa. \n      눈 녹듯이 사라지다 \t\tBiến mất như tuyết tan."}, {"id": "E240", "book": "5", "lesson": "5.8", "topic": "광고", "vocabulary": "광고 종류", "grammar": "V/A(으)ㄹ 테니까", "note": "- Đứng sau động từ hoặc danh từ, \n- có nghĩa tương đương trong tiếng Việt là ‘vì, vì sẽ...’, \n=> dùng để thể hiện sự phán đoán chắc chắn của người nói & nhằm lưu ý người nghe nội dung đi theo sau. Chủ ngữ không phải là người nói. Cấu trúc này có khi được viết ngắn thành -(으)ᄅ 테니. \n\n+ 인터넷에서 이삿짐센터를 검색해 보면 광고가 여럿 나올 테니까 잘 보고 참고하세요. \n+ 내일 오후부터 비가 내릴테니 아침에 우산을 챙겨 가는 것이 좋겠다.\n+ 새벽까지 일하느라 힘들었을 테니까 오늘은 일찍 들어가서 푹 쉬어도 좋아요. \n\nA  둘 다 비슷해 보이는데, 왜 이제품만 가격이 훨씬 더 비싸지요? \nB  텔레비전 광고에 나오는 제품이잖아요. 광고를 하려면 돈이 많이 들 테니까 물건 값이 올라갈 수밖에 없겠죠. \n\nA  내일 드디어 한국어능력시험을 보는데 벌써부터 긴장되네요. \nB  그동안 열심히 준비했잖아요. 반드시 좋은 결과가 있을 테니 너무 걱정하지 마세요. \n\nNgoài ý nghĩa như trên thì -(으)ᄅ 테니까 còn dùng để người nói nói ý chí, thiện ý của mình đồng thời cũng gợi ý cho người nghe làm theo ý mình một việc gì đó. Có nghĩa tương đương trong tiếng Việt là “tôi ...sẽ làm gì đó, thế còn anh/chị hãy làm gì đó đi.” \n예) 오늘 저녁 생일 파티 준비는 내가 해 놓을 테니까 나중에 점심이나 사 줘. \n      산 정상에 제가 먼저 가서 기다릴 테니까 뒤처진 학생들을 데리고 오세요."}, {"id": "E241", "book": "5", "lesson": "5.8", "topic": "광고", "vocabulary": "광고 매체와 형태", "grammar": "A(으)ㄴ/V는가 하면", "note": "- Đứng sau động từ hoặc tính từ, \n- có nghĩa tương đương trong tiếng Việt là ‘nếu có ... thì cũng có...’, \n=> dùng để diễn tả hai nội dung đối lập nhau, trong nội dung mệnh đề sau thường dùng chữ 도. \n\n+ 광고는 정보를 전달하는 등의 긍정적인 기능을 갖는가 하면 충동구매를 하게 하는 부정적인 기능도 갖고 있다. \n+ 내 친구는 주변 사람들의 말을 잘 들어 주어 착하다는 말을 듣는가 하면 우유부단하다는 말을 듣기도 합니다. \n+ 한국 사람이라도 김치를 좋아하는 사람이 있는가 하면 싫어하는 사람도 있다. \n\nA : 김 선생님의 수업을 두 번 들어 보았는데 김 선생님은 아주 무섭고 엄격한 분이신 것 같아요. \nB : 잘못 보셨네요. 전혀 그렇지 않아요. 우리에게 엄격하실 때가 있는가 하면 재미 있는 농담을 하실 때도 있어요. 그러니까 처음에는 무척 엄격해 보이시지만 좀 있으면 아주 재미있는 선생님이시라는 걸 알게 될 거예요. \n\nA : 모유는 아기의 성장 발달을 돕고 아기의 면역력을 강화시키는데, 한국의 어머니들 은 대부분 모유를 먹이시나요? \nB : 어떤 어머니들은 아기에게 열심히 모유를 먹이는가 하면 어떤 어머니들은 분유를 먹이기도 해요. 아직은 분유를 먹이는 어머니들이 많은 것 같아요."}, {"id": "E242", "book": "5", "lesson": "5.8", "topic": "광고", "vocabulary": "광고", "grammar": "~ (ㄴ/는)단/란 말이에요?", "note": "- Đứng ở cuối câu, có nghĩa tương đương trong tiếng Việt là ‘Bạn nói là ... sao?’ hay ‘Bạn nói là ... à?’, \n=> dùng để hỏi lại nội dung vừa nghe và biểu hiện sự ngạc nhiên hoặc cảm thán, hay là một sự việc không thể tin được. \n+ Sau -이다 hay 아니다 thì dùng -란 말이에요? \n+ Và trong cách nói thân thiện, cách nói trổng không thì dùng -단/란 말이야? \n\n1588-8282가 택배 회사 전화번호란 말이에요? \n여기 온 지 얼마나 되었다고 벌써 간단 말이야?\n아까 데리고 온 사람이 형이 아니라 동생이란 말이에요? \n\nA  깜박 잠이 들었는데 벌써 저녁 먹을 시간이 되었단 말이에요? \nB  많이 피곤했나 봐요. 아까 보니까 코를 골면서 자고 있던걸요. \n\nA  아까 친구에게 들었는데, 김 선생님께서 정말 교통사고로 병원에 입원하셨단 말이에요? \nB  네, 저도 믿기지 않지만 사실이래요. 이따가 문병이라도 가 봐야겠어요."}, {"id": "E243", "book": "5", "lesson": "5.9", "topic": "생활의 변화와 주거", "vocabulary": "생활의 변화", "grammar": "N(이)라도", "note": "- Đứng sau danh từ, có nghĩa tương đương trong tiếng Việt là ‘dù là...’, \n=> thể hiện một sự lựa chọn tối thiểu hoặc là dù không thích đối tượng danh từ đứng trước đó nhưng không còn giải pháp nào khác. \n- Dạng viết tắt của ‘dù không thích nhưng mà...’. \n\n+ 방 세 개짜리 집이 없다면 두 개짜리라도 한 번 알아봐 주세요.\n+ 일류 대학에 들어갈 수 없다면 이류 대학에라도 들어가면 좋을텐데....... \n+ 취업이 안 되니 부모님의 경제적 부담을 덜어드리기 위해서 아르바이트 자리라도 찾 아봐야겠어요. \n\nA  요즘 전셋값이 하늘 높은 줄 모르고 치솟아 걱정이 이만저만 아니에요. 당장 이사할 집을 알아봐야 하는데 말이에요. \nB  당분간은 전셋값이 계속 오를 것 같으니까 급하면 월세라도 알아보세요. \n\nA  시장하실 텐데 우선 과일이라도 좀 드세요. \nB  아니에요. 곧 저녁 시간이니까 조금 기다렸다가 후식으로 먹지요."}, {"id": "E244", "book": "5", "lesson": "5.9", "topic": "생활의 변화와 주거", "vocabulary": "주택/건물 관리 및 수리", "grammar": "V는 통에", "note": "- Đứng sau động từ, có nghĩa tương đương trong tiếng Việt là ‘do, bởi vì, là vì’, \n=> nói lên căn cứ hay nguyên nhân làm xảy ra một kết quả không tốt. \n- Ngoài ra còn được sử dụng đứng sau một số danh từ như 전쟁 통에, 난리 통에. \n\n집주인이 자꾸 집값을 올려 달라고 하는 통에 급하게 집을 구하게 됐어요. \n사람들이 옆에서 하도 떠드는 통에 무슨 말인지 하나도 못 들었어요. \n전쟁통에 잃어버린 부모님을 찾고자 백방으로 수소문했지만 헛일이었다. \n\nA  많이 피곤해 보이는데 주말에 못 쉬셨어요? \nB  네, 갑자기 손님들이 들이닥치는 통에 쉴 틈이 없었어요. \n\nA  퇴근 시간이 다 됐는데 집에 안 가세요? \nB  먼저 퇴근하세요. 오늘 계속해서 전화벨이 울리는 통에 그거 받느라고 아무 일도 못 했거든요. \n\n(*) -는 통에thường dùng để thể hiện nguyên nhân và kết quả không tốt. Do đó với trường hợp nói lên nguyên nhân của một việc tốt thì thường không sử dụng cấu trúc này mà phải dùng cấu trúc -는/ᄂ 덕분에. \n예) 김 선생님이 열심히 가르쳐 주시는 통에 한국어 실력이 많이 늘었습니다. (×)   \n      김 선생님이 열심히 가르쳐 주신 덕분에 한국어 실력이 많이 늘었습니다. (○) \n      따르릉, 따르릉 쉴 새 없이 전화벨이 울리는 통에 한숨도 못 잤어요.(○)       \n      따르릉, 따르릉 쉴 새 없이 전화벨이 울리는 덕분에 한숨도 못 잤어요.(×)"}, {"id": "E245", "book": "5", "lesson": "5.9", "topic": "생활의 변화와 주거", "vocabulary": "부동산", "grammar": "V기에", "note": "- Đứng sau động từ, \n- có nghĩa tương đương trong tiếng Việt là ‘để mà, với việc...’, \n=> thể hiện một tiêu chuẩn phán đoán, là dạng rút gọn của nghĩa ‘nếu mà nhìn với tiêu chuẩn đánh giá như thế.’ \n\n이 집은 우리 가족이 살기에 좀 작은 것 같군요.\n이 문제를 해결하기에는 우리 힘이 너무 부족해요.\n아무리 이 일을 되돌리고 싶어도 되돌리기에는 이미 너무 늦었어요. \n\nA  날씨도 좋은데 우리 천천히 걸어서 갈까요? \nB  거기까지 걸어서 가기에는 너무 멀지 않은가요? \n\nA  지금이라도 출발하는 게 어때요? \nB  지금 출발하기에는 시간이 너무 늦었어요. 차라리 내일 아침 일찍 출발합시다. \n\nMột số động từ trạng thái (tính từ) có thể đứng ở mệnh đề sau -기에 như 좋다, 나쁘다, 크다, 바쁘다, 적당하다, 늦다, 부족하다, 익숙하다, 지치다 v.v... \n예)  오늘은 대청소하기에 아주 좋은 날씨예요. \n        이 책은 어린이들이 읽기에 적당하겠군요."}, {"id": "E247", "book": "5", "lesson": "5.10", "topic": "대중문화", "vocabulary": "대중문화의 종류", "grammar": "V/A더니", "note": "- Có thể dịch tương đương trong tiếng Việt là ‘mới khi nào.. mà’, \n=> được dùng sau các động từ và tính từ; biểu hiện ý nghĩa về một tình huống hay sự thật trong quá khứ được tiếp nối bằng một sự thật hay tình huống mới khác. Tình huống sau có thể là một sự đối nghịch với tình huống trước cũng có thể là một hệ quả tạo ra từ nguyên nhân là tình huống hay sự thật ở vế trước. \n\n+ 처음에는 하나도 못 알아듣더니 이제 거의 다 이해하는군요.\n+ 요즘 그렇게 공격적으로 광고를 하더니 매출액이 2배나 올랐다고 들었어요.\n+ 그 영화배우는 예전에는 한국에서만 활동을 하더니 한류덕분에 해외활동도 많아졌네요. \n\nA : 루이엔 씨가 이번 주에 같이 콘서트 보러 가자고 했지?\nB : 어제는 그렇게 말하더니 갑자기 일이 생겼다고 다음에 가자는데. \n\nA = 그동안 공부를 안 하더니 오늘은 열심히 하네. 웬일이야?\nB = 며칠 후에 시험 보는데 그동안 너무 공부를 안 한 것 같아서 하고 있어. \n\nSo sánh sự khác nhau ‘thì hiện tại’+ 더니 và ‘thì quá khứ’+ 더니 \nĐộng từ gắn sau 더니có thể dùng thì quá khứ trong hai trường hợp sau : \n+ Một là, ở về thứ hai diễn đạt một sự thật hay một tình huống mới dựa vào một kinh nghiệm hay tình huống trong quá khứ; \n+ Hai là ở vế thứ hai đưa ra một kết quả mà nguyên nhân chính là từ vế thứ nhất. Tuy nhiên với trường hợp nội dung ở vế thứ hai là một sự thật hay tình huống đối nghịch với nội dung vế trước thì động từ gắn vào 더니không thể dùng ở thì quá khứ. \n예1) \n        어제뉴스를 보더니 최근 인기 있는 한류스타 인터뷰가 나왔다.(×) \n        어제 뉴스를 봤더니 최근 인기 있는 한류스타 인터뷰가 나왔다. (○) \n예2)  \n   나는 일 년 동안 하루도 빠짐없이 한국 드라마를 보더니 한국어 실력이 향상되었다.(×)    \n   나는 일 년 동안 하루도 빠짐없이 한국 드라마를 봤더니 한국어 실력이 향상되었다. (○)"}, {"id": "E248", "book": "5", "lesson": "5.10", "topic": "대중문화", "vocabulary": "대중문화 특성", "grammar": "V/A(으)ㄹ걸요", "note": "- Có nghĩa tương đương trong tiếng Việt là ‘biết đâu chừng, có lẽ’. \n=> Được dùng sau động từ, tính từ và danh từ để thể hiện sự phỏng đoán của người nói về một sự việc chưa diễn ra hay một điều không biết chắc chắn. \n- Chủ yếu có thể dùng để phản bác một cách nhẹ nhàng rằng điều mình dự đoán sẽ khác điều mà người nghe (thường là người lớn hơn) biết hay mong đợi. \n\n+ 요즘 아시아 지역에서는 그 가수를 모르는 사람이 없을걸요.\n+ 이제는 인터넷의 발달로 다른 나라의 문화도 쉽게 접할 수 있을걸요. \n+ 대중문화라고 해서 무조건 따라간다면 자기만의 개성은 곧 사라질걸요. \n\nA  뚜안 씨가 오늘 안 보이던데 무슨 일 있나 봐요. \nB  아마 집에서 인터넷으로 드라마 보고 있을걸요. 요즘 한국 드라마에 푹 빠졌거든요. \n\nA  저 영화배우를 어디에서 봤는지 기억이 안 나네요. \nB  며칠 전에 본 영화에 나왔을걸요. 주인공은 아니었지만 연기를 잘 해서 요즘 점점 유명해지고 있대요."}, {"id": "E249", "book": "5", "lesson": "5.10", "topic": "대중문화", "vocabulary": "대중문화 교류", "grammar": "V아/어 버리다", "note": "- Có nghĩa trong tiếng Việt là ‘hết sạch, hết nốt’. \n=> Dùng sau động từ, diễn tả tính hoàn toàn về kết quả của một hành động. \n- Ngoài ra còn có ý nghĩa giải phóng khỏi những nặng nề do việc thực hiện hành động, hay còn lại chút tiếc nuối do kết quả của hành động. \n\n+ 너무 배가 고파서 남은 음식을 다 먹어 버렸다. \n+ 그동안 쌓였던 일을 오늘 다 끝내 버려서 마음이 편하다. \n+ 너무 보고 싶었던 공연이어서 티켓 값이 비싸지만 사버렸어. \n\nA 이번 연휴 때 한국에 간다고 하더니 왜 안 갔어?\nB 사실 한달 전부터 비행기 표를 알아봤는데 다 매진돼 버려서 못 갔어. \n\nA  무슨 책을 그렇게 한꺼번에 많이 샀어요? \nB  요즘 베스트셀러거든요. 시리즈로 나왔는데 오늘 다 읽어 버리려고요."}, {"id": "E251", "book": "5", "lesson": "5.11", "topic": "관광과 안내", "vocabulary": "관광 유형 및 관광지", "grammar": "A(으)ㄴ/V는데도", "note": "- Được gắn vào sau động từ hay tính từ để diễn đạt nghĩa rằng bất kể tình huống hay trạng thái như thế nào nhưng kết quả mang đến hay sự thật xảy ra hoàn toàn không như điều mong đợi. \n- Có thể dịch tương đương trong tiếng Việt là ‘mặc dù, cho dù’. \n\n+ 공부를 열심히 하는데도 성적이 오르지 않아요.\n+ 체험 관광의 종류가 아주 많은데도 사람들은 아직 잘 모른다.  \n+ 그 곳은 지은 지 200년이 넘었는데도 보존이 잘 되어 있어요. \n\nA 지영 씨가 다음 주에 또 해외 여행을 간다고 하던데요?\nB 또요? 지영 씨는 특별히 하는 일이 없는데도 돈이 많은가 봐요. \n\nA  여기는 관광하러 오는 사람이 생각보다 없네요? \nB  그러게요. 세계문화유산 중의 하나인데도 홍보가 잘 안 됐나 봐요. \n\n(*) Để nhấn mạnh thêm ý nghĩa của cấu trúc -는데도, có thể dùng cấu trúc -는데도 불구하고. Ngoài ra -는데도 불구하 고 còn có thể dùng dưới’ dạng -(으)ᄆ에도 불구하고. \n예) \n      날마다 청소를 하는데도 방에 먼지가 많다.\n      날마다 청소를 하는데도 불구하고 방에 먼지가 많다. \n      날마다 청소를 함에도 불구하고 방에 먼지가 많다."}, {"id": "E252", "book": "5", "lesson": "5.11", "topic": "관광과 안내", "vocabulary": "관광 산업", "grammar": "A(으)ㄴ/V는 셈이다", "note": "- Được gắn vào sau động từ; \n=> diễn đạt nghĩa rằng nếu xét kĩ theo nhiều tình huống mà kết luận thì thấy rằng kết quả sẽ gần giống như một sự thật nào đó; \n- có thể dịch tương đương trong tiếng Việt là ‘coi như là’. \n\n+ 방학 때마다 여행을 가니까 일 년에 두 번 정도 여행가는 셈이다. \n+ 총 100페이지 중에서 다섯 페이지 남았으니까 이 책은 다 읽은 셈이다. \n+ 결혼 후 처음으로 함께 가는 여행이니까 이번 여행이 곧 신혼여행인 셈이다. \n\nA 한 지역에서 며칠 씩 머물렀어요?\nB 한 달 동안 7개 지역에 갔으니까 각 지역마다 4일 정도 머문 셈이지요. \n\nA  올해 관광학과의 경쟁률은 어느 정도 돼요? \nB  25명 뽑는데 81명이 지원했으니까 3:1 정도 되는 셈이에요."}, {"id": "E253", "book": "5", "lesson": "5.11", "topic": "관광과 안내", "vocabulary": "관광 안내", "grammar": "여간 V/A지 않다", "note": "- Được dùng với động từ hay tính từ, \n=> diễn đạt nghĩa một trạng thái mà mức độ hơn hẳn thông thường; \n- có thể dịch tương đương với tiếng Việt là ‘hết sức..., vô cùng’. \n- Với danh từ được dùng dưới dạng 여간 N이/가 아니다. \n\n+ 관광 코스가 너무 다양해서 결정하는 게 여간 어렵지 않아요. \n+ 머리가 좋아서 그런지 그 아이는 공부를 여간 잘 하지 않아요. \n+ 전에 저희 교수님 부인을 만나 뵈었는데 여간 미인이 아니에요. \n\nA 이번 방학에 베트남에 다녀온다고 했지요?\nB 네, 그래서 비행기 표를 예매하려고 하는데 가격이 여간 비싼 게 아니에요. \n\nA  애인에게서 청혼을 받았다고 하던데 정말 기쁘겠어요. \nB  기쁘기는 한데 너무 갑작스러운 일이라서 여간 놀라지 않았어요."}, {"id": "E255", "book": "5", "lesson": "5.12", "topic": "산업과 경제", "vocabulary": "산업", "grammar": "V(으)ㅁ에 따라", "note": "- Là dạng thay đổi trạng thái (-아/어지다) của động từ hoặc tính từ được sử dụng với ý nghĩa tiếng Việt là \"theo, tùy theo\". \n=> Biểu hiện ý nghĩa 1 hoàn cảnh biến đổi làm cho hoàn cảnh khác biến đổi theo. \n\n+ 사람들은 시간이 지남에 따라 과거의 일을 망각하게 된다.\n+ 인간 사회는 경제 수준이 변함에 따라 생활 수준이 달라지게 마련이다.\n+ 현대 사회는 정보통신 기술이 발달함에 따라 편리해진 점도 많지만 사생활 보호와 같은 새로운 문제가 나타나고 있다. \nA : 왜 요즘 웰빙 산업이 인기예요? \nB : 경제가 발전함에 따라 사람들은 삶의 질에 관심을 가지기 시작했기 때문이에요. \nA : 요즘 한국 농촌에는 일할 사람이 없다는데 무슨 말이에요? \nB : 1차 산업이 축소됨에 따라 많은 젊은이들이 농촌을 떠나 도시로 갔거든요. \n\n(*) Như đã nói trên -(으)ᄆ에 따라 biểu hiện ý nghĩa xuất hiện một hoàn cảnh mới sau khi có sự biến đổi của một hành động nào đó, còn -에 따라 biểu hiện ý nghĩa hoàn cảnh hoặc hành vi được tạo thành ở sau không khác với nội dung đứng trước đó. Trong trường hợp danh từ đứng trước -에 따라 mang tính tổng quát một cách rõ ràng thì vì nó có bao hàm \"đa dạng\" (다양함), biến đổi (변화) nên sau đó có thể dùng những biểu hiện mang tính đa dạng như 다르다 v.v. \n예) \n직장에서는 승진함에 따라 월급도 달라지지만 책임도 달라진다.\n많은 사람이 이 안내 책자의 내용에 따라 버스보다는 기차로 여행길에 올랐다. \n직장 분위기는 직장에 따라 다르다."}, {"id": "E256", "book": "5", "lesson": "5.12", "topic": "산업과 경제", "vocabulary": "경제", "grammar": "N만 해도", "note": "- Dùng trong trường hợp cần nhấn mạnh biểu hiện chỉ cần điều kiện tối thiểu loại trừ tất cả những điều kiện khác, \n- ý nghĩa tiếng Việt là \"chỉ cần, chỉ có, chỉ kể đến.\" \n\n+ 50년 전만 해도 한국은 경제적으로 많이 어려웠어요.\n+ 그 회사는 본사 종업원만 해도 200명이 넘어요. 공장 근로자까지 합하면 1,500명쯤 될 거예요.\n+ 그때 일은 생각만 해도 웃음이 저절로 나요. \n\nA 앞으로 남은 3일 동안 주문받은 제품을 모두 만들 수 있을까요? \nB 그럼요, 어제만 해도 이 제품을 3,000개나 생산했잖아요. \n\nA 이곳은왜이렇게공기가안좋아요?\nB 흐엉 씨가 시내에만 있어서 그래요. 이 도시 근교만 해도 공기가 많이 깨끗해요."}, {"id": "E257", "book": "5", "lesson": "5.12", "topic": "산업과 경제", "vocabulary": "경제정책", "grammar": "V는 대로", "note": "- Đứng sau động từ, biểu hiện ý nghĩa \"như hành vi đang xẩy ra đứng trước đó\" hoặc là \"xẩy ra ngay tức khắc sau hành vi nào đó đứng trước nó\". \n- Khi nói về trạng thái hoặc hành động trong quá khứ thì dùng -(으)ᄂ 대로. \n- Có thể sử dụng sau danh từ với ý nghĩa không khác với nội dung của danh từ đứng trước nó. \n- Ý nghĩa tiếng Việt là \" như, cứ như, theo như.., ngay khi...\" \n\n+ 크게 성공한 기업이 하는 대로 우리 회사도 따라 하면 성공할 수 있을까요? \n+ 소비자 보호 기관은 무슨 일이든지 소비자가 원하는 대로 일을 처리해 주나요? \n+ 이 설명서대로 하면 사용하는 데에 문제가 없겠지요?\n+ 회사에 도착하는 대로 전화 주시면 바로 현관으로 내려가겠습니다. \n\nA 한국의 산업에 대해 흐엉 씨가 아는 대로 말해 주세요.\nB 네, 한국은 무엇보다도 IT산업과 자동차 산업이 발달한 나라인 것 같아요. \n\nA  베트남의 주요 산업에 대한 조사가 다 끝났나요? \nB  네, 김 팀장이 베트남 출장에서 돌아오는 대로 보고드릴 것입니다."}, {"id": "E259", "book": "5", "lesson": "5.13", "topic": "한국인의 사고방식", "vocabulary": "사고방식", "grammar": "V/A(으)면서도", "note": "- Được gắn sau động từ hoặc tính từ, \n- có thể dịch trong tiếng Việt là ‘mặc dù...nhưng’. \n- Thông thường diễn đạt ý nghĩa là dẫn đến một sự đối ngược, một sự đối ứng với động tác hay trạng thái nêu ra ở vế trước. \n\n+ 나는 부르는 소리를 들었으면서도 못 들은 척 가만히 있었다. \n+ 이번 일에 대해서는 냉정하면서도 단호하게 대처해야 합니다. \n+ 한국 사람들은 아는 사람에게는 친절하면서도 낯선 사람에게는 차갑게 대한다는 말을 들을 때가 있습니다. \n\nA 아직도 그 친구하고 사이가 안 좋니?\nB 네, 제가 잘못한 줄 알면서도 너무 부끄러워서 사과를 못했거든요. \n\nA 요즘 그 드라마가 정말 인기가 많더라고요. 서영 씨도 봤어요?\nB 네, 중간 중간 웃음을 주면서도 감동까지 느낄 수 있는 괜찮은 드라마예요. \n\n(*) Trường hợp kết hợp với ‘이다‘ thì sẽ trở thành -(이)면서도, và danh từ trước đó làm một danh từ chỉ người. \n예) \n형은 전기 기술자이면서도 고장 난 텔레비전을 못 고쳤어요. \n그는 학생이면서도 밤에는 무료로 아이들을 가르치는 선생님이라고 합니다."}, {"id": "E260", "book": "5", "lesson": "5.13", "topic": "한국인의 사고방식", "vocabulary": "민족 특성", "grammar": "V/A기가  무섭게", "note": "- Được gắn vào sau động từ hoặc tính từ. \n- Có thể dịch tương đương trong tiếng Việt là ‘ngay sau khi; vừa sau khi’. \n=> Dùng để thể hiện ý nghĩa một hành động gì đó diễn ra liền ngay sau khi hành động ở vế trước kết thúc. \n\n+ 그는 자리에 앉기가 무섭게 새로 시작하는 사업 이야기를 꺼냈다. \n+ 그 작가가 쓴 책은 서점에 나오기가 무섭게 다 팔려서 금세 베스트셀러가 되었다. \n+ 한국 사람들은 만나기가 무섭게 나이를 묻는 경우가 많아 외국인들이 예의가 없다고 오해하는 경우가 있습니다. \n\nA  무슨 전화인데 벨이 울리기가 무섭게 받아? \nB  지난 번 면접시험 결과를 전화로 알려준다고 했었거든. \n\nA  와, 그 신문 기사에 댓글이 벌써 100개나 달렸어요. \nB  그래요? 요즘엔 정말 기사가 올라오기가 무섭게 사람들이 댓글을 다는군요."}, {"id": "E261", "book": "5", "lesson": "5.13", "topic": "한국인의 사고방식", "vocabulary": "정", "grammar": "V/A아/어서 그런지", "note": "- Gắn vào sau động từ. \n- Có thể dịch nghĩa tương đương trong tiếng Việt là ‘vì... hay sao mà’, ‘chẳng biết có phải vì....hay không mà’. \n=> Dùng để thể hiện ý nghĩa ‘vì vế trước mà dẫn đến xảy ra vế sau mặc dù lý do này có thể không chắc chắn’. \n- Nếu dùng với động từ 이다 thì sẽ ở dạng -(이)라서 그런지. \n\n+ 요즘 제일 인기 있는 배우가 출연한 영화라서 그런지 극장에 사람이 많다. \n+ 한국 텔레비전을 통해서 명동을 자주 봐서 그런지 처음 왔지만 익숙한 느낌이 들어요. \n+ 한국 사람들은 정이 많아서 그런지 지하철에서 무거운 가방을 들고 있는 사람을 보면 가방부터 받아 주려고 합니다. \n\nA  민재 씨, 무슨 일이에요? 컴퓨터가 고장 났어요? \nB  컴퓨터가 바이러스에 감염돼서 그런지 자꾸 다운이 되네요. \n\nA  이번 시험에는 꼭 합격할 자신 있지요? \nB  저는 왠지 이번에도 떨어질 것 같아요. 지난 번 시험에 떨어져서 그런지 자꾸 자신 이 없어지네요."}, {"id": "E263", "book": "5", "lesson": "5.14", "topic": "한국인의 일생", "vocabulary": "통과 의례", "grammar": "V(ㄴ/는)/A다면서요?", "note": "- Đứng sau động từ hoặc tính từ, \n- có nghĩa tương đương trong tiếng Việt là ‘Nghe nói là...có đúng không?/phải không?’, \n=> dùng để hỏi lại nhằm xác nhận nội dung mà người nói đã nghe từ người khác. –다면서요? có thể dùng dưới dạng rút gọn là –다며?. \n- Ngoài ra, nếu đứng sau danh từ thì dùng –이라면서요?, -(이)라면서? hay -(이)라며?. \n\n한국은 1월에 눈도 많이 내리고 엄청나게 춥다면서요?\n지난주에 열린 한국어 말하기 대회에서 대상을 받은 사람이 흐엉 씨라며?\n박 선생님이 남자 친구와 3년 동안 사귀시더니 드디어 이번 가을에 결혼을 하신다면서요? \n\nA  김 과장님, 아까 영숙 씨한테서 들었는데 다음 주 워크숍에 참석 못 하신다면서요? 무슨 일 있으세요? \nB  네, 실은 다음 주에 저희 아버님께서 환갑이시거든요. 그래서 식구들끼리 3박 4일 동안 제주도 여행을 가기로 했어요. \n\nA  이리로 500미터쯤 가다 보면 행복 예식장이 나온다면서? 그런데 왜 안 보이는 거야? \nB  이상하다. 틀림없이 약도에는 그렇게 나와 있었어. 잠깐만 기다려 봐. 내가 청첩장을 다시한번확인해볼게. \n\n(*) Giống như -(ᄂ/는)다면서, khi biểu hiện ý muốn xác nhận với đối phương sau khi nghe một thông tin từ người khác thì có dạng -(ᄂ/는)다지요?. \nNếu dùng dạng -(ᄂ/는)다지요? để trực tiếp hỏi đối phương về sự việc cần xác nhận thì hơi ngại, nên trong trường hợp này có thể dùng -(ᄂ/는)다면서요? \n예) \n      수빈 씨가 이번 봄에 결혼한다면서요? (○) \n      (당신은) 이번 봄에 결혼한다면서요? (○) \n      수빈 씨가 이번 봄에 결혼한다지요? (○) \n      (당신은) 이번 봄에 결혼한다지요? (×)"}, {"id": "E264", "book": "5", "lesson": "5.14", "topic": "한국인의 일생", "vocabulary": "생일", "grammar": "V/A게 마련이다", "note": "- Đứng sau động từ hoặc tính từ với nghĩa “ tất nhiên\", \"đương nhiên là..\" \n=> biểu hiện ý nghĩa một sự việc đương nhiên xẩy ra. \n- Thường sử dụng với châm ngôn, tục ngữ, hoặc những sự việc hợp với lẽ tự nhiên. Có thể thay thế bằng -기 마련이다. \n\n결혼 날짜는 보통 여자 쪽 집에서 정하게 마련입니다.\n언어를 배우는 능력이 뛰어난 사람이 있는가하면 그렇지 않은 사람도 있게 마련이다. \n장례를 치를 때 상을 당한 가족들은 계속 빈소를 지키며 문상을 받게 마련이지요. \n\nA : 사기를 당해서 전 재산을 잃었어요. 이제 앞으로 어떻게 살아야 하지요? \nB : 옛날 속담에 하늘이 두쪽 나도 솟아날 구멍은 있게 마련이라고 했어요.너무 걱정 하지 말고 희망을 가지세요. \n\nA : 지난 일 년 동안 열심히 준비해서 TOPIK 시험 5급에 도전했는데 떨어졌어요. 속상 해요. \nB : 너무 속상해 하지 마세요. 흐린 날이 있으면 반드시 맑은 날도 있게 마련이에요. 다음에 도전하면 꼭 합격할 거예요. 힘내세요! \n\n(*) Tương tự -게마련이다 còn có thể dùng -(으)ᄂ/는법이다. Hai cách biểu hiện này có thể thay thế cho nhau, tuy nhiên trong trường hợp hành vi hoặc trạng thái đứng trước là thói quen hay tập quán thì dùng -(으)ᄂ/는법이다 hợp hơn. \n예) \n칭찬을 들으면 누구나 좋아하게 마련이다. (○) \n칭찬을 들으면 누구나 좋아하는 법이다. (○) \n일반 쓰레기통에는 음식물 쓰레기를 버리지 않게 마련이야. (×) \n일반 쓰레기통에는 음식물 쓰레기를 버리지 않는 법이야. (○)"}, {"id": "E265", "book": "5", "lesson": "5.14", "topic": "한국인의 일생", "vocabulary": "혼례", "grammar": "N조차", "note": "- Đứng sau danh từ, có nghĩa tương đương trong tiếng Việt là ‘thậm chí’, ‘đến’, \n=> thể hiện nội dung bao hàm cả danh từ trước đó và thậm chí còn vượt qua ý nghĩa của danh từ trước đó. Thông thường nó thể hiện những trường hợp cực đoan mà người nói không trông đợi hoặc khó dự đoán trước. \n\n수빈 씨가 중국 남자와 결혼을 할 것이라고는 상상조차 못했어요.\n이번 중간시험이 너무 어려워서 우등생인 루이엔조차 점수가 많이 떨어졌다. \n서울에서는 집값이 계속 오르고 있어서 지금 받는 월급을 쓰지 않고 3년을 모아도 전세조차 얻기 힘들 것 같다. \n\nA : 한국을 떠난지 20년 만에 서울에 다시 돌아왔더니 어렸을 때 친구들은 물론이고 친척들조차 저를 알아보지 못 하더라고요. \nB : 10년이면 강산도 변하게 마련인데 20년이 지나면서 얼굴이 많이 바뀌었을 테니 못 알아보는 것이 당연하지요. \n\nA : 은지 씨가 오늘 회사에 3살 된 아들을 데려왔다면서요? 저는 여태까지 은지 씨가 미혼인 줄 알았어요. \nB : 저도 오늘 처음 알았어요. 같은 부서에 있는 가까운 지인들조차 은지 씨가 결혼한 사실을 모르고 있었다고 하네요. 너무 어려 보이는 데다가 항상 처녀처럼 꾸미고 다녀서 깜박 속았지 뭐예요. \n\n(*) -조차 có nghĩa tương tự như -까지, -마저 tuy nhiên nếu dùng -조차 trong câu khẳng định thì nghĩa không được tự nhiên lắm, nên tốt nhất là dùng trong câu phủ định. \nTrái lại, -마저, -까지 nếu dùng để nhấn mạnh nghĩa chỉ còn lại mỗi một thì có thể dùng được cả trong câu phủ định và khẳng định. \n예) \n이제는 편의점에서 전기료조차 낼 수 있게 되었네요. (×) \n이제는 편의점에서 전기료마저 낼 수 있게 되었네요. (○) \n이제는 편의점에서 전기료까지 낼 수 있게 되었네요. (○)"}, {"id": "E269", "book": "5", "lesson": "5.15", "topic": "한국 유학", "vocabulary": "대학 입학", "grammar": "V/A거든 + mệnh đề", "note": "- Đứng sau động từ, tính từ và 이다, \n- có nghĩa tương đương trong tiếng Việt là ‘nếu, nếu như...’, \n=> dùng để thể hiện điều kiện hay một sự giả định. Mệnh đề phía sau thường là thể mệnh lệnh, nhờ cậy, khuyên nhủ, hứa hẹn (으)세요, -(으)ᄇ시다, -(으) ᄅ게요 hay là thể hiện sự suy đoán -겠, -(으)ᄅ 것이다, -(으)려고 하다. \n\n유학 수속에 필요한 서류가 모두 갖춰지거든 곧바로 신청하세요.\n이따가 교환 학생 지원자들이 오거든 제출 서류들을 잘 받아 두세요. \n저는 여기에서 조금 더 기다렸다가 김 교수님이 오시거든 모시고 갈게요. \n\nA : 안녕하세요? 저는 이틀 전에 베트남에서 온 투안이라고 합니다. 잘 부탁드립니다. \nB : 반가워요. 한국에서 생활하면서 어려운 점이 있거든 언제든지 이야기하세요. \n\nA : 한국에 가서 김 교수님을 만나거든 저 대신 안부 좀 전해 주세요. \nB : 네, 꼭 전해 드릴 테니까 걱정하지 마세요. \n\n(*) Nếu -거든 được dùng để thể hiện một tính khả thi có thể thực hiện được thì -(으)면 còn có thể dùng trong trường hợp tính khả thi rất kém hoặc không thể thực hiện được. Do đó mệnh đề theo sau 거든 thì thường không dùng hình thái quá khứ hay hiện tại, còn -(으)면 thì không có hạn chế này. \n예) \n나에게 타임머신이 있거든 공룡시대로 돌아가 직접 한 번 보고 싶어요. (×) \n나에게 타임머신이 있으면 공룡시대로 돌아가 직접 한 번 보고 싶어요. (○) \n(**) Hơn nữa, -(으)면 có thể dùng cho cả giả định và điều kiện nhưng -거든 không thể dùng trong việc giả định về một sự thật đã được định trước. \n예) \n나이가 들거든 누구나 죽는다. (×) \n나이가 들면 누구나 죽는다. (○)"}, {"id": "E270", "book": "5", "lesson": "5.15", "topic": "한국 유학", "vocabulary": "대학 생활", "grammar": "V아/어 내다", "note": "- Đứng sau động từ, có nghĩa tương đương trong tiếng Việt là ‘động từ + được’, \n=> thể hiện một sự hoàn thành hay cuối cùng cũng kết thúc hay đạt được một điều gì đó. Về mặt ý nghĩa thì không dùng thể bị động của động từ mà chỉ kết hợp với những động từ thể hiện sự khắc phục khó khăn hay thể hiện một ý chí mạnh mẽ. \n\n+ 유학 생활을 하다 보면 힘든 일도 많겠지만 제 꿈을 위해 반드시 이겨 내겠습니다. \n+ 한국 전자는 십 수 년의 노력과 연구 끝에 또 한 번의 기적을 이루어 냈습니다. \n+ 그 사람의 행방을 찾고자 여기 저기 수소문해 봤지만 결국은 알아 내지 못했어요. \n\nA  김 교수님의 논문이 학계에서 호평을 받는 이유는 뭔가요? \nB  그것은 물질이 유전자 활동을 조절한다는 사실을 증명해 냈기 때문이지요. \n\nA  세종대왕의 업적으로는 어떤 것이 있습니까? \nB  여러 가지가 있지만 그 중에서도 가장 빛나는 것은 아무래도 한글을 창제해 낸 것이 아닐까요? \n\n(*) Để thể hiện mạnh mẽ hơn một chút thì đôi khi còn kết hợp dùng chung với -고 말다. \n예) 나는 어떠한 역경이 온다고 해도 반드시 이 일을 이루어 내고 말 것이다. \n      이번에는 무슨 일이 있어도 꼭 사건의 내막을 알아내고 말테다."}, {"id": "E271", "book": "5", "lesson": "5.15", "topic": "한국 유학", "vocabulary": "수강 신청", "grammar": "N(이)라든가", "note": "- Đứng sau danh từ, có nghĩa tương đương trong tiếng Việt là ‘hay, hay là’, \n=> dùng để thể hiện việc chọn một trong nhiều sự việc nào đó hay là việc chọn một điều gì đó cũng không có liên quan gì cả. \n+ Nếu trước đó là động từ thì dùng -ᄂ/는다든가, \n+ trước đó là tính từ thì dùng -다든가. \n+ Có thể dùng (이)라든지, -ᄂ/는다든지, -다든지 để thay thế. \n\n+ 제 의견에 대해 이의가 있다든가 또는 궁금한 사항이 있으신 분은 말씀해 주십시오. \n+ 어디가 불편하다든가 아니면 피치 못할 사정이 있다든가 하는 게 아니면 꼭 모임에 참석하세요.\n+ 전공 선택이라든가 유학이라든가 하는 일들은 일생을 좌우할 수 있는 일이기 때문에 신중하게 결정해야 해요. \n\nA  다음 주에 집들이 초대를 받았는데 무슨 선물을 가지고 가는 게 좋을지 모르겠어요. \nB  한국 사람들은 보통 세제라든가 휴지라든가 하는 실용적인 선물을 가지고 가요. \n\nA  한국에서 생활하면서 어려운 일이 있다든가 아니면 의논할 사람이 필요하다든가 하면 망설이지 말고 언제든지 찾아오세요. \nB  네, 알겠습니다. 항상 신경 써 주셔서 감사합니다."}, {"id": "E274", "book": "6", "lesson": "6.1", "topic": "가족 제도", "vocabulary": "가족 제도", "grammar": "V/A(으)ㄴ 나머지", "note": "- Gắn vào sau tính từ và động từ, \n- có nghĩa tương đương với tiếng Việt là \"kết quả của việc quá ... nên, do quá ... nên ...\", \n=> dùng để biểu thị kết quả được tạo ra do thực hiện một hành động nào đó hoặc bởi sự tiến triển của một trạng thái nào đó. \n- Chủ yếu được dùng trong trường hợp thể hiện hành động hoặc trạng thái đó trở nên thái quá dẫn đến kết quả tiêu cực. \n\n+ 자녀 양육의 문제로 출산을 기피한 나머지 출산율이 급격히 떨어졌다. \n+ 핵가족화가 급속히 이루어진 나머지 가족에 대한 가치관이 붕괴되었다.\n+ 그 영화배우는 상을 받고 너무 기쁜 나머지 사람들 앞에서 울음을 터뜨렸다. \n\nA : 요즘에는 가족 간 범죄에 대한 뉴스가 많이 나오는 것 같아요. \nB : 그러게 말이에요. 사람들이 물질적인 욕구에만 집착한 나머지 가족은 안중에도 없나 봐요. \n\nA : 어제 저녁 비행기로 간다더니 왜 안 갔어요? \nB : 강풍이 너무 심한 나머지 비행기가 결항됐거든요. \n\n(*) -(으)ᄂ 나머지 và -(으)ᄂ 결과\n-(으)ᄂ 나머지 được sử dụng trong trường hợp biểu thị kết quả tiêu cực, \ncòn -(으)ᄂ 결과 có thể sử dụng trong cả hai trường hợp biểu thị kết quả tích cực và tiêu cực. \n예) \n시험을 앞두고 밤새워 공부한 결과 합격의 영광을 얻었다. (○) \n시험을 앞두고 밤새워 공부한 나머지 합격의 영광을 얻었다. (×)"}, {"id": "E275", "book": "6", "lesson": "6.1", "topic": "가족 제도", "vocabulary": "호칭 - 지칭", "grammar": "A기 짝이 없다", "note": "- Gắn vào sau tính từ, có nghĩa tương đương trong tiếng Việt là \"thật là, không còn gì...hơn, quá ư là...\", \n=> dùng để nhấn mạnh mức độ trầm trọng không gì so sánh được. \n\n저출산·고령화 문제에 대한 정부의 정책은 실망스럽기 짝이 없다. \n어제 TV에 독거노인의 생활이 나왔는데 정말 애처롭기 짝이 없더라. \n젊은 부부들이 자기 자식만 감싸고도는 걸 보면 한심하기 짝이 없어. \n\nA : 숙모님, 곧 명절인데 친척들을 부를 때 어떻게 해야 하지요? 너무 복잡해요. \nB : 맞아. 한국은 호칭이 너무 다양해서 잘 모르면 난감하기 짝이 없지. 내가 도와줄 테니까이번기회에외워둬. \n\nA : 요즘 부모 대신에 할머니, 할아버지와 생활하는 아이들이 많다면서요? \nB : 네, 어린 나이니까 부모의 사랑도 받으면 좋을 텐데. 안쓰럽기 짝이 없어요."}, {"id": "E276", "book": "6", "lesson": "6.1", "topic": "가족 제도", "vocabulary": "가족 유지 및 가족 문제", "grammar": "V/A았/었더라면", "note": "- Gắn vào sau động từ hay tính từ, \n- có nghĩa tương đương trong tiếng Việt là \"giá mà, giá như mà\", \n=> dùng để đưa ra giả định ngược lại với sự thực đã xảy ra trong quá khứ nhằm thể hiện sự hối tiếc hoặc tiếc nuối. \n\n+ 부모님께서 계속 살아계셨더라면 자주 찾아뵙고 효도했을 겁니다.\n+ 대가족 제도가 좀 더 유지되었더라면 가정불화가 심해지지는 않았을 텐데.\n+ 정부가 출산 장려 정책을 빨리 마련했더라면 저출산 문제가 발생하지는 않았을 거야. \n\nA : 오랜만에 친척분들이 모인 자리에 갔는데 잘 몰라서 너무 어색했어. \nB : 그러게 말이야. 자주 찾아뵙고 연락했더라면 낯설거나 어색하지 않았을 텐데. \n\nA : 유나 씨는 남편하고는 사이가 좋았는데 고부갈등 문제로 이혼했대요. \nB : 그래요? 시어머니하고 갈등이 커지기 전에 서로 대화를 많이 했더라면 이혼까지는 안했을것같은데정말안타깝네요."}, {"id": "E277", "book": "6", "lesson": "6.1", "topic": "가족 제도", "vocabulary": "가정 분위기", "grammar": "N더러 = N보고", "note": "- Gắn vào sau danh từ chỉ đối tượng hướng đến của động từ, \n- có nghĩa tương đương trong tiếng Việt là \"với\" hoặc có khi không có từ tương ứng với tiếng Việt. \n\n시부모님이 나보고 빨리 아기를 가지라고 하셔서 스트레스를 많이 받고 있어. \n사촌 동생보고 이번 주말에 같이 외할머니 댁에 가자고 해야겠다.\n맞벌이를 하게 돼서 장모님더러 아기를 봐 달라고 할 수밖에 없었다. \n\nA  요즘은 장인어른하고 장모님더러 아버님, 어머님이라고 부른다면서요? \nB  네, 예전과는 달리 처가 식구들을 가족처럼 가깝게 생각하고 자주 왕래하기 때문에 호칭도 아버님, 어머님처럼 친근하게 바꿔 부르는 사람이 많아졌어요. \n\nA  한국에서 생활하면서 불편한 점은 없었어요? \nB  없긴요. 요즘도 호칭 문제 때문에 자주 실수하는데 어제도 형님보고 아가씨라고 했지 뭐예요. \n\n더러/보고 và 에게/한테\n더러/보고 được dùng giới hạn trong trường hợp động từ tác động đến đối tượng biểu hiện nghĩa liên quan đến hành động nói và có thể thay thế được bằng 에게/한테. \nNhưng khi đi với các động từ biểu hiện hành vi, hành động, tình huống chung khác không phải là hành động nói thì không thể dùng cho đối tượng chịu tác động của hành động đó. Sau 더러 /보고 thường là hình thức gián tiếp. \n예) \n수빈이가 민재더러(보고/에게/한테) 같이 밥 먹자고 했다. (○) 유나에게(한테) 애인이 생겼다. (○)\n유나더러(보고) 애인이 생겼다. (×)"}, {"id": "E278", "book": "6", "lesson": "6.2", "topic": "과학과 미래", "vocabulary": "과학", "grammar": "V고자", "note": "- Gắn vào sau động từ hoặc danh từ, \n- có nghĩa tương đương với tiếng Việt là “để/ nhằm mục đích...”, \n=> dùng để thể hiện mục đích của một hành động, ý đồ hoặc hy vọng của người nói. Cấu trúc này chủ yếu được dùng trong văn viết hoặc lời nói mang tính nghi thức như diễn văn, phỏng vấn, báo cáo... -고자 cũng được viết dưới dạng -고자 하다. \n\n인간 생활에 다양한 혜택을 주고자 끊임없이 연구하고 있습니다.\n오늘 저는 첨단 과학의 영향에 대해 발표하고자 이 자리에 섰습니다.\n인간 수명을 연장하고 불치병을 고치기 위해 복제 기술을 이용하고자 합니다. \n\nA : 가장 영향력 있는 교사로 뽑히셨는데 그 이유가 무엇일까요? \nB : 저는지금까지좋은선생이되고자항상노력을해왔는데그것을좋게봐주신것 같습니다. \n\nA : 정부에서는 불경기에 어떻게 대처하고 계십니까? \nB : 실업률을 낮추고자 일자리를 계속 창출할 계획입니다. \n\n(*) -고자 chỉ dùng trong trường hợp vế trước và vế sau của câu có cùng chủ ngữ. \n예) \n나는 시험에 합격하고자 열심히 공부했다. (○) \n나는 시험에 합격하고자 그가 열심히 공부했다. (×)"}, {"id": "E279", "book": "6", "lesson": "6.2", "topic": "과학과 미래", "vocabulary": "생활과학", "grammar": "V(ㄴ/는)다기에", "note": "- Gắn vào sau động từ, có nghĩa tương đương trong tiếng Việt là \"vì nghe nói là... nên...\" là dạng viết rút gọn của -는다고 하기에, \n=> dùng khi muốn thể hiện rằng một sự việc nghe được từ 1 người khác, là căn cứ của sự phán đoán hay nguyên nhân của hành vi của câu sau. \n- Tùy vào lời nói ở vế trước mà dùng -ᄂ다기에, -라기에, -다기에, hoặc -자기에. \n\n친구가 요즘 너무 바쁘다기에 약속을 다음으로 미뤘다.\n위대한 발명가가 되려면 고정관념을 깨야 한다기에 그렇게 하려고 노력하고 있어요. 동생이 그 신제품이 마음에 든다기에 그것을 사 주기로 약속했다. \n\nA  정우 씨도 발명왕 콘테스트에 참가하기로 했다면서요? \nB  네, 철수 씨가 콘테스트에 참가를 하고 싶다며 함께 신청하자기에 참가 신청서를 냈어요. \n\nA  왜 여기서 밥을 혼자 먹고 있어요? \nB  친구들이 벌써 다 밥을 먹었다기에 그냥 혼자 먹으러 왔어요."}, {"id": "E280", "book": "6", "lesson": "6.2", "topic": "과학과 미래", "vocabulary": "발명", "grammar": "N마저", "note": "- Gắn vào sau danh từ, có nghĩa tương đương trong tiếng Việt là “kể cả, ngay cả, thậm chí...”, \n=> dùng để thể hiện sự cộng thêm nội dung khác ngoài nội dung của danh từ trước đó. Cấu trúc này cũng được dùng khi muốn nói về một việc còn lại sau cùng. \n\n+ 동물 복제에 이어 인간 복제마저 행해진다면 인류 사회는 큰 혼란에 빠질 것이다. \n+ 자유무역이 확대됨에 따라 농업마저 위협받는 상황이 되어 농민들의 반발이 크다. \n+ 그 아이는 지난해에 아버지가 병으로 세상을 뜨셨는데 지난주에 어머니마저 교통사고 를 당하여 돌아가셔서 고아 신세가 되었다. \n\nA : 이제 집에 아이들이 없어서 좀 쓸쓸하시겠어요.\nB : 네, 큰딸은 결혼했고 둘째는 유학 갔고 막내마저 군대에 가버려서 참 허전해요. \n\nA : 그 두 사람이 유학 때문에 오랫동안 떨어져 있더니 결국 헤어지고 말았다지요? \nB : 원래 눈에서 멀어지면 마음마저 멀어진다고 하잖아요. \n\n(*) Có thể dùng 까지 để thay thế 마저 nhưng 마저 chỉ dùng trong các trường hợp tiêu cực còn 까지 thì có thể dùng cả trong trường hợp tích cực. \n예) \n지수는 공부도 잘하고 노래도 잘하는데 운동마저 잘한다. (×) \n지수는 공부도 잘하고 노래도 잘하는데 운동까지 잘한다. (○) \n(**) Ngoài ra, 마저có thể dùng thay thế với 조차, nhưng 조차 thì phù hợp với câu phủ định. \n예) \n날씨도 추운데 바람마저 불었다. (○) \n날씨도 추운데 바람조차 불었다. (×)"}, {"id": "E281", "book": "6", "lesson": "6.2", "topic": "과학과 미래", "vocabulary": "화학", "grammar": "V/A(으)ㄴ 탓", "note": "- Gắn sau động từ hoặc tính từ, \n- có nghĩa tương đương trong tiếng Việt là “do, tại...”, \n=> dùng khi thể hiện một nguyên nhân hay nguồn gốc dẫn đến một hiện tượng mang tính phủ định, \nCấu trúc này thường được dùng dưới dạng -(으)ᄂ 탓에, -(으)ᄂ 탓으로, -(으)ᄂ 탓이다. \nTrong trường hợp dùng sau danh từ hay đại từ, chỉ cần thêm 탓 vào sau danh từ hay đại từ. \n\n+ 과학이 발달해도 윤리 의식이 부족한 탓에 부작용이 생긴다. \n+ 맛있는 음식만 보면 무조건 많이 먹는 탓에 살이 자꾸 찐다. \n+ 로봇이 사람들의 일을 대신하는 탓에 일자리가 점점 줄고 있다. \n\nA  이제는 정말 우주 관광의 시대가 열린 것 같지요? \nB  그렇기는 하지만 우주선 탑승 비용이 워낙 비싼 탓에 아직은 일부 부자들에게만 해당되는 이야기인 것 같아요. \n\nA  민수 씨가 시골에 갔다가 아직도 서울에 돌아오지 못하고 있다면서요? \nB  네, 버스 운행이 전혀 안 되고 있대요.며칠 전에 내린 폭설 탓인가 봐요."}, {"id": "E283", "book": "6", "lesson": "6.3", "topic": "한국어와 사회", "vocabulary": "어휘", "grammar": "V(으)ㄹ 겸", "note": "- Gắn vào sau động từ, \n- có nghĩa tương đương với tiếng Việt là \"kiêm, đồng thời\", \n=> dùng để biểu hiện hai hành vi, động tác được thực hiện cùng nhau. \n\n+ 요즘은 한국어 실력도 기를 겸 시험 문제 유형도 익힐 겸 해서 TOPIK 문제집을 풀고 있어요. \n+ 앞으로는 운동도 할 겸 돈도 아낄 겸 가까운 거리는 걸어 다니기로 했어요. \n+ 어제는 옷도 살 겸 한국 사람들의 생활도 구경할 겸 동대문시장에 다녀왔어요. \n\nA : 지난 주말에는 민속촌에 다녀오셨다면서요?\nB : 네, 이번 기회에 한국 문화도 한번 체험해 볼 겸 해서 갔다 왔지요. \n\nA : 이 늦은 시간에 어디 갔다 오는 길이에요?\nB : 머리 좀 식힐 겸 해서 산책하고 오는 길이에요. \n\n겸 cũng được sử dụng để kết hợp cùng với hai danh từ nhưng danh từ lúc này phải là những từ chỉ chức năng, thường là hai chức năng của một sự vật hoặc một người. \n예) \n이 사람은 감독 겸 영화배우입니다. \n이곳은 차고 겸 창고로 사용하고 있습니다"}, {"id": "E284", "book": "6", "lesson": "6.3", "topic": "한국어와 사회", "vocabulary": "발음", "grammar": "V고말고요", "note": "- Gắn vào sau động từ, \n- có nghĩa tương đương với tiếng Việt là \"chắc chắn là.....rồi, .... chứ\", \n=> dùng để biểu hiện ý chí mạnh mẽ của của bản thân về một việc gì đó hoặc đồng tình mạnh mẽ về lời nói, ý kiến của đối phương. \nNó thường được sử dụng kèm với các phó từ biểu hiện sự nhấn mạnh như: 그럼, 물론. \n\nA : 한국어의 높임말을 배우기가 어렵지요? \nB : 그럼요, 어렵고말고요. 저 같은 외국 사람한테는 얼마나 복잡한지 몰라요. \n\nA : 이번 장학금은 디엠 씨에게 주려고 하는데 괜찮을까요? \nB : 물론이지요. 괜찮고말고요. 디엠 씨만큼 성실한 사람도 없어요. \n\nA : 열심히 하면 틀림없이 좋은 학교에 진학할 수 있겠지요? \nB : 그럼요, 그렇고말고요. 열심히만 하면 틀림없이 잘될 거예요."}, {"id": "E285", "book": "6", "lesson": "6.3", "topic": "한국어와 사회", "vocabulary": "문법", "grammar": "V(ㄴ/는)/A다고", "note": "- Gắn vào sau động từ, tính từ, danh từ , \n- có nghĩa tương đương với tiếng Việt là \"cứ lấy lý do là....., chỉ vì lý do....\", \n=> dùng để biểu hiện lý do, nguyên nhân của hành động hoặc tình huống nào đó (theo dạng câu gián tiếp). \nCấu trúc này thường được dùng để biểu hiện nghĩa không nên lấy hành động hoặc tình huống ở vế trước làm lý do để thực hiện hành động ở vế sau. \nThường được sử dụng nhiều trong tục ngữ hoặc quán ngữ. \n\n+ 어렵다고 자꾸 얘기를 안 해 버릇하면 결국에는 끝까지 한국말을 잘할 수 없을 거예요. \n+ 다른 사람보다 조금 더 능력이 있다고 잘난 척 하는 것은 옳은 행동이 아니에요. \n+ 한국어 실력이 좀 늘었다고 단어와 문법 공부를 게을리 하면 안 됩니다. \n\nA : 저는 아무래도 언어에 소질이 없나 봐요. 다른 사람들에 비해 실력이 느는 속도가 너무 느려요. \nB : 조금 느리다고 좌절할 필요는 없어요. 포기하지 않고 최선을 다 하는 것이 중요해요. \n\nA : 아무리 봐도 우리 반에서 저만큼 똑똑한 사람은 없는 것 같아요. 이번에도 장학금은 따 놓은 당상이에요. \nB : 조금 잘한다고 그렇게 자만하다가는 언젠가 큰코다칠 거예요."}, {"id": "E286", "book": "6", "lesson": "6.3", "topic": "한국어와 사회", "vocabulary": "문자", "grammar": "V/A더라도", "note": "- Gắn vào sau động từ, tính từ, danh từ, \n- có nghĩa tương đương với tiếng Việt là \"dù, dù rằng...\", \n=> dùng để biểu hiện ý nhượng bộ hoặc giả định và được sử dụng khi biểu hiện rằng mặc dù có công nhận sự thật ở vế trước nhưng hành động được yêu cầu ở vế sau hoàn toàn không liên quan đến vế trước. \n\n+ 이번 일에 실패하더라도 좌절하지 말고 용기를 내서 다시 도전해 보세요.\n+ 시험에 모르는 것이 나오더라도 당황해 하지 말고 침착하게 풀어 나가세요. \n+ 다소 기분 나쁜 일이 있더라도 손님들 앞에서는 항상 미소를 잃지 말아야 합니다. \n\nA : 외국어를 배운다는 게 정말 보통 일이 아닌 것 같아요. 너무 힘들어서 포기하고 싶어요. \nB : 힘들더라도 포기하지 말고 끝까지 하세요. \n\nA : 미안해요. 우리 사이에 이 정도 말은 할 수 있다고 생각했는데 제 말이 좀 심했나 봐요. \nB : 아무리 친한 친구라고 하더라도 지켜야 할 예의가 있는 거예요."}, {"id": "E289", "book": "6", "lesson": "6.4", "topic": "한국 문학", "vocabulary": "문학 장르", "grammar": "V고서", "note": "- Là đuôi liên kết, gắn sau động từ, \n- có nghĩa tương đương với tiếng Việt là 'sau khi', \n=> dùng để thể hiện mối quan hệ hữu cơ giữa hai sự việc của mệnh đề trước và mệnh đề sau. So với đuôi liên kết thể hiện sự tiếp nối -고 thì sự việc ở mệnh đề trước -고서 được nhấn mạnh là tiền đề của sự việc ở mệnh đề sau. \n\n+ 다음 주 월요일까지 황순원의 소설 ‘소나기’를 읽고서 독후감을 써 오세요.\n+ 그가 전쟁에서 죽지 않고 살아서 돌아왔다는 소식을 전해 듣고서 그녀는 겨우 안도의 한숨을 내 쉬었다.\n+ 그는 오랫동안 난치병으로 고생했는데 친구의 소개로 찾아간 한의원에서 지어준 약을 먹고서 금방 다 나았다. \n\nA  아까 점심 먹기 전까지만 해도 수빈이가 옆방에서 공부하고 있는 것을 봤는데 지금 가 보니까 없네요. \nB  아, 수빈이요? 방에 없을 거예요. 무슨 일인지는 모르겠는데 방금 전에 걸려온 전화를 받고서 급히 뛰어 나가더라고요. \n\nA  ‘위기에 처한 지구’라는 다큐멘터리를 보고서 환경문제의 심각성에 대해 다시 한 번 생각해 보게 되었어요. \nB  저도 그 다큐멘터리를 봤는데, 앞으로는 일회용품의 사용을 줄여야겠다는 생각을 했어요."}, {"id": "E290", "book": "6", "lesson": "6.4", "topic": "한국 문학", "vocabulary": "문학 작품", "grammar": "V/A고요", "note": "- Là đuôi kết thúc, gắn sau tính từ hoặc động từ, \n- có nghĩa tương đương trong tiếng Việt là 'và, còn... nữa, không những thế..', \n=> dùng để liên kết hai sự việc đồng đẳng trở lên hay liên kết và thể hiện mối quan hệ hữu cơ giữa mệnh đề trước và mệnh đề sau. \n-고 đi cùng với -요 để thể hiện sự tôn trọng đối với người nghe. Có khi -고요 kết thúc một câu mà lược bỏ đi nội dung phía sau, nhưng cũng có khi thêm một câu độc lập chứa đựng thông tin đồng đẳng ở đằng sau. \n\n+ 김소월의 시 ‘진달래꽃’은 어조가 여성적이고요. 한국의 보편적인 정서인 ‘한(恨)’을 노래한 시예요. \n+ 수빈이는 화가인 아버지를 닮아서 그림을 참 잘 그려요. 그리고 피아니스트인 어머니 를 닮아서 피아노도 잘 치고요. \n+ 서울은 겨울에 기온이 영하로 떨어지면서 굉장히 추워요. 한겨울에는 눈도 많이 내리고요. \n\nA : 민준 씨는 팔방미인이라면서요? 공부도 잘하는 데다가 학교 농구 팀에서 주장을 할 정도로 운동도 잘한다고 들었거든요. \nB : 맞아요. 외국어에도 능통해서 특히 영어와 중국어를 잘해요. 베트남어도 할 줄 안다 고 들었고요. \n\nA : 어디 가세요? 웬일로 정장을 다 차려 입으시고요. \nB : 사실은 맞선 자리에 나가는 길이었어요. 평소에 정장을 안 입어 버릇해서 그런지 아까 거울을 봤더니 좀 어색하던데 이상해 보이지 않아요?"}, {"id": "E291", "book": "6", "lesson": "6.4", "topic": "한국 문학", "vocabulary": "소설", "grammar": "V/A던가요?", "note": "- Là đuôi kết thúc, gắn vào sau động từ hoặc tính từ, \n- có nghĩa tương đương với tiếng Việt là '....không ạ?', '....sao ạ?', \n=> dùng để thể hiện sự phỏng đoán hay hỏi về một sự thật xảy ra trong quá khứ. \nSau danh từ dùng (이)던가요?. \n\n+ 한국의 대표적인 저항 시인으로 유명한 분들이 윤동주 시인과 이육사 시인이던가요? \n+ 흐엉 씨, 일요일에 한국어능력시험을 보았다고 들었는데 문제가 쉽던가요?\n+ 아까 호텔에서 저녁 식사로 나온 메뉴가 한정식이던데 드실 만하던가요? \n\nA : 점심시간에 김 선생님께 전화는 해 보셨나요? 사무실에 계시던가요? \nB : 아니요, 다섯 번도 넘게 전화를 걸었는데 계속 전화를 안 받으시던데요. 오늘은 사무실에 출근하지 않으신 것 같아요. \n\nA : 어제는 수빈 씨와 함께 국립현대미술관에 다녀왔는데 아주 재미있었어요. 하지만 미술관이 너무 커서 만약에 혼자 갔더라면 길을 잃었을 거예요. \nB : 저도 몇 번 가 본 적이 있는데 처음 갔을 때 미술관 안에서 길을 잃어버릴 뻔했어요. 특히 그때는 관람객들이 많았거든요. 어제도 사람들이 많던가요?"}, {"id": "E292", "book": "6", "lesson": "6.4", "topic": "한국 문학", "vocabulary": "문예 사조", "grammar": "N1(이)나 N2(이)나 할 것 없이", "note": "- Gắn vào sau danh từ có ý nghĩa đối lập, chủ yếu dùng để nhấn mạnh sự không phân biệt hay loại trừ một hiện tượng, hành động nào cả, có nghĩa tương đương với tiếng Việt là 'bất kể là..., (이)나 (이)나 có thể được lược bỏ. \n\n+ 허균의 ‘홍길동전’은 아이나 어른이나 할 것 없이 누구에게나 잘 알려진 소설이다. \n+ 수빈이는 책이라면 비싼 것이나 싼 것이나 할 것 없이 모두 사들인다. \n+ 유명한 가수의 공연을 보기 위해 모여든 관중들은 젊은이나 노인이나 할 것 없이 흥분 해 있었다. \n\nA : 수빈씨, 이번에 인사과에 새로 입사한 김민준 씨가 수빈 씨의 고등학교 동창이라고 들었어요. 김민준 씨는 어떤 분이에요? \nB : 민준이랑 3학년 때 같은 반이었는데, 우리 반 반장이었거든요. 쉬운 일이나 어려운 일이나할것없이항상열심히하는성실한아이였어요. \n\nA : 저기 좀 보세요. 기와집이나 초가집이나 할 것 없이 온통 하얀 눈으로 덮여 있는 게 마치 영화 속의 한 장면 같아요. \nB : 정말 멋진 풍경이네요. 그림을 보고 있는 것처럼 정말 아름다워요."}, {"id": "E294", "book": "6", "lesson": "6.5", "topic": "한국의 문화유산", "vocabulary": "문화재의 유형", "grammar": "V/A기는커녕", "note": "- Gắn vào sau động từ hay tính từ, diễn tả ý nghĩa phủ định tuyệt đối nội dung nêu ra ở vế trước và lại thêm vào một cấp độ nhấn mạnh hơn ở vế sau; \n- có thể dịch tương đương trong tiếng Việt là ‘chẳng những không.... mà lại còn'. \n- Khi đứng sau động từ và tính từ thì dùng ở dạng -기는커녕 còn khi đứng sau danh từ thì dùng ở dạng 는커녕. \n\n+ 국토 개발을 이유로 문화재를 보호하기는커녕 훼손하고 있어서 큰일이에요. \n+ 주말에 편히 쉬기는커녕 회사에서 늦게까지 일만 했어요.\n+ 여행을 가기는커녕 감기가 심해 자리에서 일어나지도 못했다. \n\nA : 한국에 왔으니까 세계 자연유산으로 지정된 제주화산섬과 용암 동굴에 꼭 한번 가 보세요. \nB : 저도 그러고 싶지만 시간이 없어서 제주도에 가기는커녕 설악산에도 못 가 볼 것 같아요. \n\nA : 다음 학기에 졸업하면 유학을 간다고 하더니 준비는 잘 돼요? \nB : 유학은커녕 기말 시험을 망쳐서 졸업도 못 할까 봐 걱정이에요. \n\n(*) -기는커녕thường được dùng kèm với các trợ từ bỗ nghĩa là 도, 조차, 마저. \n예) \n목이 너무 아파서 밥을 먹기는커녕 물조차 마시기 힘들어요. \n돈을 많이 벌기는커녕 투자를 잘못해서 남아 있던 돈마저 날렸어요."}, {"id": "E295", "book": "6", "lesson": "6.5", "topic": "한국의 문화유산", "vocabulary": "한국의 문화재 분류", "grammar": "V/A(으)니만큼", "note": "- Gắn vào sau động từ hay tính từ, được dùng để diễn đạt ý nghĩa công nhận sự thật ở vế trước và căn cứ vào mức độ của sự thật đó để đưa ra một đề nghị (phán đoán, mệnh lệnh, yêu cầu); \n- có thể dịch tương đương trong tiếng Việt là 'do là ... nên', 'bởi vì ... nên', 'vì đã....nên', ' đến mức ....cho nên..' \n\n+ 이것은 삼국 시대의 유물이니만큼 소중하게 보존해야 합니다.\n+ 오늘은 설날이니만큼 창덕궁이나 경복궁 같은 고궁에 가는 게 어때? \n+ 그동안 열심히 공부했으니만큼 이번에는 시험에 꼭 합격할 수 있을 거예요. \n\nA : 우리 지난번에 얘기했던 대로 내일 등산 가는 거야?\nB : 바람이 불고 날씨가 추우니만큼 밖에 나가지 말고 집에서 쉬자. \n\nA : 내일 전공 수업 발표라서 너무 긴장돼요. \nB : 걱정 마세요. 며칠 동안이나 심혈을 기울여서 준비했으니만큼 잘 할 수 있을 거예요. \n\nVới những danh từ nơi chốn hay danh từ thời gian đặc biệt, được hiểu giữa người nói và người nghe, thì cấu trúc này được dùng với dạng -이/가 -(이)니만큼. \n예) \n나이가 나이니만큼 건강에 신경 써야 해요.\n때가 때이니만큼 다들 취직 준비하느라 바쁘군요."}, {"id": "E296", "book": "6", "lesson": "6.5", "topic": "한국의 문화유산", "vocabulary": "문화재 보호", "grammar": "V(으)ㄹ 따름이다", "note": "- Gắn vào sau động từ, diễn tả ý nghĩa ngoài tình huống hiện tại thì không có một khả năng nào khác hay một sự chọn lựa nào khác nữa; \n- có thể dịch tương đương trong tiếng Việt là ‘chỉ có ....', 'chỉ còn biết ...', 'không thể khác là ...' \n\n+ 우리가 보존해야 할 유적지가 지진으로 훼손된 현장을 보니 안타까울 따름입니다. \n+ 저를 믿고 이렇게 큰일을 맡겨 주시니 그저 감사할 따름입니다. \n+ 저는 아직 배우는 과정에 있으니까 제가 할 일을 열심히 할 따름이에요. \n\nA : 서울 시의원에 당선되신 소감 한 말씀 부탁드리겠습니다. \nB : 그동안 성원해 주신 시민 여러분께 감사할 따름입니다. 우리 시의 발전을 위해 최선을 다하겠습니다. \n\nA : 지역 주민들을 위한 적극적인 사회 복지 활동으로 대통령상을 수상하신 것 축하드립니다. \nB : 보이지 않는 곳에서 열심히 봉사하시는 분들이 얼마나 많은데요. 제가 상을 받게 되어 그분들께 죄송할 따름입니다."}, {"id": "E297", "book": "6", "lesson": "6.5", "topic": "한국의 문화유산", "vocabulary": "유네스코 등재 한국의 \n문화유산 명칭", "grammar": "V는 수가 있다", "note": "- Gắn vào sau động từ, diễn tả ý nghĩa có một ít khả năng xảy ra một hành vi hay sự thật nào đấy; \n- có thể dịch tương đương trong tiếng Việt là 'có khả năng sẽ...', 'có thể sẽ...' \n\n+ 이대로 방치하다가는 우리의 소중한 문화재가 사라져 버리는 수가 있어요.\n+ 국제 관계에서는 언제나 예상 밖의 변수가 작용하는 수가 있다. \n+ 지나치게 욕심을 부려 운동을 무리하게 하다 보면 오히려 병에 걸리는 수가 있다. \n\nA : 지원 씨는 워낙 똑똑한 사람이니까 이번 일도 무리 없이 잘 해 낼 거예요. \nB : 똑똑한 사람도 실수하는 수가 있으니까 우리가 옆에서 도와줘야 돼요. \n\nA : 이번 대회에서는 평소에 너무 조용해서 있는지도 잘 몰랐던 그 학생이 대상을 받았어요. \nB : 때로는 기대하지 않았던 사람이 탁월한 능력을 발휘하는 수도 있지요."}, {"id": "E299", "book": "6", "lesson": "6.6", "topic": "국제 사회", "vocabulary": "교류와 협력", "grammar": "V/A(으)ㄹ 법하다", "note": "- Gắn vào sau động từ hoặc tính từ, \n=> dùng để diễn đạt sự phán đoán của người nói về một tình huống hay một sự thật nào đó cũng đáng, cũng đến mức như thế; \n- có thể dịch nghĩa tương đương trong tiếng Việt là ‘đáng lẽ ra.../ lẽ ra....’ \n\n+ 이번 분쟁에는 국제연합이 개입할 법한데 아직 움직임이 없지요?\n+ 그 지역에서 전쟁이 10년이나 계속되었으니 국민들이 다른 나라로 이주하고 싶은 마음이 생길 법도 하네요.\n+ 요즘 세상에 그만한 조건이면 마음이 흔들릴 법한데 그 친구가 그러지 않았다니 정말 대단한 사람인 것 같아요.\n\nA : 지금까지 수 차례의 실무 회담이 열렸으니 이제 정상. 회담이 열릴 법한데 아직 그런 소식은 없지요? \nB : 네. 그동안 두 나라의 관계가 너무 나빠서 관계를 회복하는 데에 시간이 많이 걸리는 것 같아요."}, {"id": "E300", "book": "6", "lesson": "6.6", "topic": "국제 사회", "vocabulary": "국가 간 회담", "grammar": "N(이)나마", "note": "- Gắn vào danh từ có phụ âm cuối (Patchim), được dùng để thể hiện ý nghĩa rằng dù không vừa lòng nhưng cũng là mức độ chấp nhận được hoặc trong tình huống hiện tại thì không còn sự lựa chọn nào khác, \n- có thể dịch nghĩa tương đương trong tiếng Việt là ‘mặc dù chỉ là’ \n\n+ 아프리카 빈민을 돕는 일에 작은 정성이나마 보태려고 돼지 저금통을 들고 오는 사람 들이 있었어요. \n+ 별로 하는 일 없이 1년이 다 지나가는데 남은 시간이나마 후회 없이 살려고 합니다. \n+ 저도 대학교에 다닐 때 어려운 사람들에게 조금이나마 도움이 되고 싶어서 봉사 활동을 한 일이 있어요. \n\nA : 주말에 쉬지도 못하고 여기까지 오셨군요. 감사합니다. \nB : 이번 홍수로 인한 피해 복구에 미력이나마 힘이 되어 드리고 싶어서 왔습니다."}, {"id": "E301", "book": "6", "lesson": "6.6", "topic": "국제 사회", "vocabulary": "국제 문제", "grammar": "V/A더라고요", "note": "- Được dùng khi truyền đạt với người khác một nội dung hồi tưởng về một sự thật mà bản thân mình đã trực tiếp trải nghiệm trong quá khứ mà biết được. \n- Khi nhận thức đó là một sự thật đã hoàn tất thì dùng cấu trúc -았/었더라고요. \n\n+ 오늘 아침 신문을 보니 요즘 기후변화 문제가 국제사회에서 가장 큰 쟁점이 되어 있더 라고요. \n+ 어제 기아 문제를 다룬 TV프로그램을 봤는데 지구상에서 매년 600만 명의 어린이가 영양실조로 목숨을 잃더라고요. \n+ 1년쯤 가족과 떨어져서 살아보니 가족이 얼마나 소중한지를 알겠더라고요. \n\nA : 이번 방학에 외국으로 봉사 활동을 하러 간다면서요? \nB : 네, 방학에 뭔가 보람있는 일을 하고 싶었는데 마침 친구가 해외 봉사 활동을 가보 라고 하더라고요. 그래서 며칠 동안 망설이다가 가기로 결정했어요."}, {"id": "E302", "book": "6", "lesson": "6.6", "topic": "국제 사회", "vocabulary": "외교 공관 및 외교관", "grammar": "V/A(으)련마는", "note": "- Gắn vào sau động từ và tính từ, gắn với 았 để diễn đạt sự giả định một mong đợi về một tình huống thỏa mãn điều kiện nào đó, nhưng sự thật tiếp theo đó lại không được như vậy. \n- Chủ yếu dùng với dạng -(으)면 -(으)련마는, nhưng cũng có khi yếu tố thể hiện điều kiện -(으)면 được tỉnh lược đi. \n- Có thể dịch nghĩa tương đương trong tiếng Việt là ‘nếu mà ... thì ... nhưng / giá mà được ... thì ... nhưng ...’ \n\n+ 지구상에서 전쟁, 가뭄, 질병이 사라지면 좋으련마는 아직도 해결할 수 있는 좋은 방법 이 없네요. \n+ 그 정도 했으면 그만 할 때도 됐으련마는 아직도 포기하지 않고 계속하고 있네요. \n+ 이번에는 아시아 지역으로 발령이 나면 좋으련마는 또 다른 지역으로 발령이 날 것 같아요.\n\nA : 요즘도 여기저기에서 전쟁 때문에 고통 받는 사람이 많은 것 같아요. \nB : 글쎄 말이에요. 지구상에서 전쟁이 사라졌으면 좋으련마는 크고 작은 전쟁이 끊이 지 않네요. \n\nSo sánh -(으)련마는 và -(으)ᄅ 텐데\n-(으)련마는 được dùng khi có sự mong đợi và hi vọng về một tình huống nào đó nhưng lại không được thỏa mãn hoặc chưa chắc chắn, \ncòn -(으)ᄅ 텐데 chỉ thể hiện sự dự đoán trong một tình huống không có sự mong đợi hay hi vọng. Vì thế, sau -(으)련마는 không thể là câu đề nghị hay câu mệnh lệnh, còn với -(으)ᄅ 텐데thì không có sự hạn chế này. \n예) \n지구상에서 분쟁이 사라지면 좋으련마는 그럴 가능성이 없어요. (○) \n지구상에서 분쟁이 사라지면 좋을 텐데 그럴 가능성이 없어요. (○) \n오후에 비가 오련마는 우산을 가지고 오지 않았어요. (×) 오후에비가올텐데우산을가지고오지않았어요.(○)"}, {"id": "E305", "book": "6", "lesson": "6.7", "topic": "현대사회와 스포츠", "vocabulary": "경기 종목 및 대회", "grammar": "V기 십상이다", "note": "- Gắn vào sau các động từ, thể hiện ý tình huống được biểu thị bởi động từ đứng trước cấu trúc này sẽ dễ dàng xảy ra hoặc khả năng xảy ra lớn. \n- Có nghĩa tương đương với tiếng Việt là \"sẽ dễ dàng...\" \n- Cấu trúc -기 십상이다 có thể dùng thay bằng -기가 쉽다. \n\n+ 아무런 준비운동 없이 훈련에 돌입하면 부상 당하기 십상이다.\n+ 수준 미달인 선수들이 대회에 참가했다가는 망신 당하기 십상이다.\n+ 자신에게 맞는지 살펴보지 않고 무턱대고 장비를 구입했다가는 낭패 보기 십상이다. \n\nA : 심판에게 가장 중요한 것은 운동경기에서 얼마나 정확한 판정을 내리느냐하는 것 이에요. \nB : 물론이죠. 심판의 잘못된 판정이 경기 전체의 흐름을 망치기 십상이거든요. \n\nA : 운동을 잘못해서 그런지 어깨 통증이 심해졌어요. 스포츠마사지를 받아 볼까요? \nB : 좋은 생각이네요. 그런데 전문가에게 받는 것이 좋을 거예요. 마사지를 잘못 받으면 어깨 통증이 더 심해지기 십상이거든요."}, {"id": "E306", "book": "6", "lesson": "6.7", "topic": "현대사회와 스포츠", "vocabulary": "경기 진행", "grammar": "V/A(으)ㄹ뿐더러", "note": "- Gắn vào sau động từ hay tính từ, thể hiện ý nghĩa cộng thêm một sự thật hay tình huống khác vào một sự thật hay tình huống nào đó. \n- Có nghĩa tương đương với tiếng Việt là \"không những chỉ....mà còn\". \n- Chủ ngữ của vế trước và vế sau là một, phần nhiều trường hợp thì tình huống hay sự thật ở vế sau nghiêm trọng hơn hay mức độ cao hơn so với vế trước. \n- Có thể thay bằng cấu trúc -(으)ᄅ 뿐만 아니라 mà không có khác biệt lớn. \n- Được dùng chủ yếu trong văn viết hơn là văn nói, khi dùng sau danh từ thì có dạng 일뿐더러. \n\n+ 국가 대표 선수들은 연속되는 훈련에 적응해야 할뿐더러 식사 조절도 해야 한다. \n+ 스포츠 중계권의 단독 구매로 경제적 손실이 클뿐더러 사회적 파장도 적지 않다. \n+ 컨디션 조절을 못한다면 좋은 성적을 거둘 수 없을뿐더러 동료 선수들과도 마찰이 생길 수 있다. \n\nA : 영화 ‘국가 대표’에 나왔던 스키 점프라는 종목은 이제 인기가 많아졌나요? \nB : 별로 그렇지도 않아요. 스키 점프는 영화로 인해서 인지도가 높아지긴 했지만 아직까 지는 대중적인 스포츠가 아닐뿐더러 큰 관심은 받지 못하고 있어요. \n\nA : 요즘은 지역마다 스포츠 센터가 있어서 평소에 운동하기 좋겠어요. \nB : 물론 그렇기는 하지만 주민들이 선호하는 운동은 한정되어 있기 때문에 빨리 마감될 뿐더러 선택할 수 있는 시간도 다양하지 않아요."}, {"id": "E307", "book": "6", "lesson": "6.7", "topic": "현대사회와 스포츠", "vocabulary": "스포츠 직업 및 산업", "grammar": "V(ㄴ/는)/A다거나", "note": "- Gắn vào sau động từ hay tính từ với dạng ‘động từ +ᄂ/는다거나’ hay 'tính từ +다거나'. \n- Có nghĩa tương đương với tiếng Việt là 'hay là', 'hoặc là', dùng khi vừa giải thích vừa liệt kê bằng ví dụ của nhiều hành vi. \n- Khi dùng sau danh từ thì có dạng (이)라거나. \n- Ngoài ra, trường hợp mang ý nghĩa chọn lọc chỉ một trong hai hay nhiều sự thật hay hành vi đối lập nhau thì nó chỉ dùng gắn vào sau động từ. \n\n+ 운동을 시작한다고 해서 바로 근육이 늘어난다거나 체력이 증진되는 것은 아니다. \n+ 스포츠의 인기는 선수들의 인지도가 높아진다거나 대회 입장권 판매량이 증가하는 것으로알수있다.\n+ 국가 대표 선수로 뽑힌다거나 탈락된다는 것은 노력 여하에 달린 거예요. \n\nA : 이번겨울에스키를배워볼까하는데다칠까봐좀무섭기도해. \nB : 넘어지는 것 때문에 두려움을 갖는다거나 불안하다는 생각을 하면 배울 수가 없어. 오히려 어떻게 해야 다치지 않고 잘 넘어질 수 있는가를 생각해야지. \n\nA : 대표선수 선발 경기를 통과했으니 이제 걱정이 없어졌어요. \nB : 합숙 훈련에 빠진다거나 건강관리를 잘 못하면 탈락될 수도 있으니까 주의하도록 하세요."}, {"id": "E308", "book": "6", "lesson": "6.7", "topic": "현대사회와 스포츠", "vocabulary": "스포츠 문화", "grammar": "V/A(으)ㄹ지라도 \n= V/A(으)ㄹ지언정", "note": "- Gắn vào sau động từ và tính từ. \n- Có nghĩa tương đương với tiếng Việt là 'cho dù có ...'. \n=> Thể hiện ý nghĩa nhấn mạnh mặc dù vế trước đưa ra một tình huống nào đó và công nhận hay giả định điều đó nhưng kết quả vế sau đối lập hay khác với sự mong đợi của vế trước. Khi đứng sau danh từ thì được dùng với dạng 일지라도 / 일지언정. \n- Ngoài ra, khi vế trước giả định một tình huống phủ định hay cực đoan và nhấn mạnh nội dung vế sau thì nó được gắn vào sau động từ. \n\n+ 스포츠에서는 라이벌과 함께 우승을 다툴지라도 페어플레이 정신을 지켜야 한다.\n+ 그 선수가 아무리 세계적으로 유명할지라도 도덕적으로 문제가 있다면 대중으로부터 외면 받게 마련이다.\n+ 아무리 바쁠지언정 꾸준히 운동하는 습관을 길러야 체력을 증진시킬 수 있다. \n\nA : 전에다쳤던발목이아직다안나아서그런지운동하기가쉽지않네. \nB : 통증은 물리 치료로 가라앉을지라도 약해진 근력은 쉽게 회복되기 힘들대. 그러니까 얼마 동안은 재활 운동을 꾸준히 해야 할 거야. \n\nA : 이번 경기로 부상이 심각해질지언정 난 출전을 포기하지 않을 거야. \nB : 이번 출전이 아니더라도 너에게는 더 많은 기회가 주어질 테니까 그런 바보 같은 소리하지 마."}, {"id": "E310", "book": "6", "lesson": "6.8", "topic": "정치 제도", "vocabulary": "정치 일반", "grammar": "V(으)ㄹ 바에야", "note": "- Kết hợp sau động từ biểu hiện nghĩa tương đương với cấu trúc \"đối với việc..... mà nói thì.....\" trong tiếng Việt. \n=> Được dùng khi đưa ra một phương án thay thế khác tốt hơn so với một tình huống nào đó đang được đề cập đến hoặc so với một tình huống được giả định trong tương lai. \n\n+ 선거 결과가 불확실한데 집을 팔아서 선거에 출마할 바에야 그 돈으로 사업을 하는 것 이더낫겠다. \n+ 그 돈으로 서울에서 작은 아파트를 살 바에야 서울 근교에 있는 큰 아파트를 사는 것이 더 좋을 것이다. \n+ 대학 졸업장이 필요하여 적성을 생각하지 않고 아무 전공이나 선택할 바에야 고등 학교를 졸업하자마자 회사에 취직을 하는 편이 더 낫겠다. \n\nA : 이번 선거에 출마한 후보들이 다 마음에 안 드는데 어떻게 하지요? 그래도 누군가를 찍어야겠죠? \nB : 마음에 안 드는 사람을 찍을 바에야 기권하는 게 낫지 않아요?"}, {"id": "E311", "book": "6", "lesson": "6.8", "topic": "정치 제도", "vocabulary": "정치 제도", "grammar": "A(으)ㄴ/V는 만큼", "note": "- Được dùng khi dự tính một kết quả tương ứng với một lý do hay một nguyên nhân đang tồn tại nào đó. \n- Tương đương với nghĩa \"bằng việc........, với việc........., do.......\" trong tiếng Việt. \n\n+ 그 나라는 대통령을 중심으로 하여 국민 모두가 힘을 합치고 있는 만큼 곧 빈곤에서 벗어나게 될 것이다. \n+ 이번에 출마한 후보들이 공정하게 선거운동을 한 만큼 선거 결과에 불복하는 사람은 없을 것으로 예상된다. \n+ 그 회사는 근무 조건도 좋고 월급도 많은 만큼 취업 준비 생들에게 인기가 높다. \n\nA : 올해 국회는 큰 문제 없이 잘 돌아가는 것 같네요.\nB : 여당과 야당이 조금씩 양보한 만큼 국회가 순조롭게 운영되고 있어요. \n\nSo sánh -(으)ᄂ/는 만큼 và -(으)니까\nCấu trúc -(으)ᄂ/는 만큼 thường được dùng trong trường hợp người nói đưa ra lý do hoặc một nguyên nhân nào đó và do có nguyên nhân, lý do đó mà sẽ có kết quả tương ứng sau đó. So với cấu trúc đó, -(으)니까 thường được dùng trong việc biểu hiện mối quan hệ nhân quả tất yếu hoặc khi chỉ đơn giản đề cập đến một nguyên nhân nào đó. \nMặt khác, ngoài việc chỉ nguyên nhân, lý do, -(으)니까 còn đựợc sử dụng khi biểu hiện sự phát hiện thông qua kết quả của một hành vi nào đó. \n예) \n전에 비하여 더욱 열심히 공부한 만큼 좋은 성적이 나올 것이다.(○) \n전에 비하여 더욱 열심히 공부하니까 좋은 성적이 나올 것이다. (○) \n밖을 보세요. 바람이 분 만큼 잎이 떨어져요. (×) \n밖을 보세요. 바람이 부니까 잎이 떨어져요. (○) \n그분이 오라고 해서 가 보니까 이미 술에 취해 정신이 없더군요.(○) \n그분이 오라고 해서 가 본 만큼 이미 술에 취해 정신이 없더군요.(×)"}, {"id": "E312", "book": "6", "lesson": "6.8", "topic": "정치 제도", "vocabulary": "정당", "grammar": "V고 들다", "note": "- Biểu hiện dáng vẻ thực hiện một hành động nào đó ẩn bên trong về mặt không gian, sâu sắc về mức độ. \n- Tương đương với nghĩa \"cứ.., tập trung vào, xoáy vào... \" trong tiếng Việt. \n\n+ 여당은 이번 사건이 빨리 해결되기를 바라고 있지만 야당은 사건의 원인이 무엇이고 책임이 누구에게 있는지를 계속 따지고 든다. \n+ 날씨가 추우니까 아기가 엄마 품속으로 계속 파고드는 것 같아요.\n+ 별 것도 아닌 문제에 대하여 그렇게 따지고 들지 마세요. 사람들이 싫어합니다. \n\nA :  저 친구는 작은 문제라도 있으면 늘 원인을 파고드는 성격인데 기자를 하면 딱 맞을 것 같아요. \nB :  글쎄요, 파고드는 게 늘 좋은 건 아니지요. 오히려 진실과 다른 결론에 도달하는 경우도 있을 거예요."}, {"id": "E313", "book": "6", "lesson": "6.8", "topic": "정치 제도", "vocabulary": "선거 제도", "grammar": "V(ㄴ/는)/A다마는", "note": "- Kết hợp với động từ, tính từ biểu hiện nghĩa mặc dù công nhận sự thật được đề cập ở vế trước nhưng vẫn đặt trọng tâm nhấn mạnh hơn vào sự thật ở vế sau. \n- Tương đương với nghĩa \"đúng là ... nhưng ..., công nhận là ... nhưng ...\" trong tiếng Việt.\n-(ᄂ/는)다마는 là dạng giản lược và được sử dụng nhiều trong văn nói và trong trường hợp không lịch sự nên trong tình huống cần phải lịch sự thì sử dụng ở dạng -ᄇ/습니다마는. \n\n+ 경제가 발전하여 중산층이 형성되면 민주주의가 자리를 잡는다마는 나라에 따라서는 경제가 발전해도 민주주의가 뿌리를 내리지 못하는 경우도 있는 법이다. \n+ 선거에서 이기면 큰 명예를 얻는다마는 떨어지게 되면 경제적으로 어려운 상황에 빠 지게될테니좀더신중하게생각해보는게좋겠다. \n+ 전 세계가 합심해서 기후변화에 대처한다고 합니다마는 결과를 낙관하기는 어려울 것 같아요. \n\nA  : 아버지, 민주정치를 하면 국민의 뜻이 정치에 다 반영되는 거 아닌가요? \nB  : 꼭 그렇지는 않단다. 민주주의가 국민에 의한 정치라고는 한다마는 서로의 이익이 충돌할 때에는 어느 한쪽의 이익은 반영되지 못하게 되지."}, {"id": "E315", "book": "6", "lesson": "6.9", "topic": "생활과 경제", "vocabulary": "경기", "grammar": "V(으)ㄹ락 말락 하다", "note": "- Kết hợp sau một số động từ biểu hiện một việc nào đó gần như xảy ra nhưng rồi lại không xảy ra. Qua đó để chỉ trạng thái của hành động gần đạt đến mức độ nào đó. \n- Tương đương với biểu hiện chỉ trạng thái chập chờn của hành động dạng “dọa...lại thôi, tưởng......mà lại không, gần như....rồi lại thôi” trong tiếng Việt. \n\n+ 계속 흐리더니 비가 내릴락 말락 하네요.\n+ 채권형 펀드가 주식형 펀드의 수익률을 따라잡을락 말락 해요. \n+ 이번 달에는 가족 행사 때문에 돈을 많이 썼더니 적자가 될락 말락 해요. \n\nA : 요즘 주가가 오르고 있다던데 저도 주식 투자를 해 볼 걸 그랬어요. \nB : 네, 꽤 오르고 있어요. 그동안 묵묵히 기다렸는데 제가 산 주식도 흑자가 될락 말락 합니다. \n\nA : IT관련 주식을 사라고 해서 샀는데 도대체 언제 오를까요? \nB : 그러게요. 오를락 말락 하는데 통 오르지를 않네요."}, {"id": "E316", "book": "6", "lesson": "6.9", "topic": "생활과 경제", "vocabulary": "무역", "grammar": "V/A(으)ㄹ 리가 없다", "note": "- Kết hợp sau động từ và tính từ thể hiện một việc nào đó không có khả năng xảy ra. \n- Có thể thay 없다 bằng 있다 để chuyển thành dạng -(으)ᄅ 리가 있다 được dùng trong câu nghi vấn. -(으)ᄅ 리가 없다 có thể chuyển thành dạng -(으)ᄅ 턱 이 없다 để sử dụng với nghĩa tương đương. \n- Nghĩa tiếng Việt là “không có lý nào...” \n\n+ 그런 일로 그 회사 주가가 떨어질 리가 없어요. \n+ 주식 투자를 한다고 해서 모두 부자가 될 리가 있겠어? \n+ 평소에 노력을 안 했으니 시험 결과가 좋을 리가 없어요. \n\nA : 촛불 집회를 한다고 해서 소고기 수입을 안 할 리가 없어요. \nB : 이렇게 해서라도 우리들의 의견을 정부에 알려야 해요. \n\nA : 안정된 투자로는 뭐가 있을까요? \nB : 글쎄요, 저는 저축이 제일이라고 생각해요. 주식이나 펀드 투자는 손해를 볼 수가 있지만 저축을 해서는 손해 볼 리가 없잖아요."}, {"id": "E317", "book": "6", "lesson": "6.9", "topic": "생활과 경제", "vocabulary": "투자", "grammar": "A(으)ㄴ/V는 마당에", "note": "- Kết hợp với động từ hoặc tính từ biểu hiện một hoàn cảnh hoặc một tình huống tạo điều kiện cho một việc nào đó xảy ra. \n- Tương đương với nghĩa \"trong hoàn cảnh ..., với tình hình ...\" trong tiếng Việt. \n\n+ 환율이 이렇게 오른 마당에 어떻게 해외여행을 가겠어요?\n+ 학기가 끝나는 마당에 열심히 공부하지 않은 걸 후회해도 소용이 없죠. \n+ 공공요금까지 오를 것으로 전망되는 마당에 물가 상승 부담은 더욱 커져 갈 것이다. \n\nA:  흐엉 씨,투자 보고서 준비는 잘 되어가요? \nB : 아니요, 한시가 급한 마당에 아직까지 드러나는 성과가 없어서 큰일입니다. \n\nA : 방사능 유출 때문에 그 나라 구조대원들도 떠나가는 마당에 한국인 구조대원 백여 명이 남아 아직도 활동하고 있대요. \nB : 구조대원들의 희생정신이 정말 대단하네요. \n\n(*) Khi nói về một tình huống hay một hoàn cảnh mà một sự việc nào đó xảy ra trong quá khứ thì dùng dạng -(으)ᄂ 마당 에 ở sau động từ nhưng cấu trúc -(으)ᄅ 마당에 thì không được sử dụng để chỉ thời tương lai. Lúc đó người ta thường dùng dạng -는 마당에. \n- Cấu trúc -는 마당에có thể được sử dụng ở dạng -는 마당이라, -는 마당이니. \n예) \n대학 입학도 포기하는 마당에 유학은 어떻게 가겠니? (○) \n대학 입학도 포기한 마당에 유학은 어떻게 가겠니? (○) \n대학 입학도 포기할 마당에 유학은 어떻게 가겠니? (×)"}, {"id": "E318", "book": "6", "lesson": "6.9", "topic": "생활과 경제", "vocabulary": "", "grammar": "V느니 차라리", "note": "- Kết hợp sau động từ thể hiện tình huống ở vế sau tốt hơn tình huống ở vế trước cho dù tình huống ở phía sau cũng không phải là tình huống đáng để thỏa mãn. Có thể sử dụng 아예 thay cho 차라리. \n- Tương đương với nghĩa \"thà......... còn hơn\" trong tiếng Việt. \n\n+ 차 안에서 시간을 보내느니 차라리 걷는 게 낫겠어요.\n+ 계속 폭락하는 주식을 그냥 두느니 차라리 손해를 봐도 팔겠어요.\n+ 요즘 은행 금리도 낮은데 저축을 하느니 차라리 위험하더라도 주식 투자를 하겠어요. \n\nA : 요즘 주식 투자가 인기던데 민수 씨도 주식 투자해요? \nB : 아니요, 저는 손해 볼까 봐 불안해서 그런 거 못해요. 주식 투자를 하느니 차라리 돈을 써 버리겠어요. \n\nA : 뚜안 씨, 요즘도 자전거로 통학해요? \nB : 아니요, 요즘은 버스로 통학해요. 이렇게 자전거를 집에만 세워 두느니 아예 팔까 싶어요."}, {"id": "E319", "book": "6", "lesson": "6.10", "topic": "한국의 역사", "vocabulary": "시대", "grammar": "V1(으)랴 + V2(으)랴", "note": "- Gắn sau động từ, có nghĩa tương đương trong tiếng Việt là “vừa lo (làm việc..)... vừa lo (làm việc)...”\n=> dùng để thể hiện sự bận rộn khi phải thực hiện 2 hành động trở lên. Do đó ở mệnh đề sau chỉ có những từ thể hiện sự bận rộn. \n\n+ 그 당시 국왕은 외세의 침략을 막아내랴 국내 정치에 힘쓰랴 여념이 없었다.\n+ 오늘은 하루 종일 바이어 접대하랴 사장님께 상황 보고 드리랴 정신이 하나도 없었어요. \n+ 그 분은 주중에는 회사 다니랴 주말에는 봉사 활동하러 다니랴 하루도 쉴 날이 없어요. \n\nA : 요즘 TV를 보니까 어떤 나라에서 전쟁으로 피난길에 오르는 사람들의 모습이 나오 더라고요. 보고 있자니 마음이 얼마나 안 좋던지요. \nB : 한국전쟁 때에도 정말 난리였대요. 우리 할머니 말씀으로는 당시에 폭격을 피해 허 둥지둥 짐 보따리 싸랴 애들 챙기랴 온 나라가 그야말로 난장판이었대요. \n\nA : 결혼식 때 뵙고는 처음이지요? 요즘 어떻게 지내세요? \nB : 결혼만 하면 남편과 함께 여유로운 시간을 보낼 수 있을 것 같았는데 막상 하고 나니까 일하랴 살림하랴 오히려 더 눈코 뜰 새 없이 바빠졌어요."}, {"id": "E320", "book": "6", "lesson": "6.10", "topic": "한국의 역사", "vocabulary": "역사 개관", "grammar": "V기 일쑤다", "note": "- Gắn sau động từ mang nghĩa nghiêng về chiều hướng không tốt, có nghĩa tương đương trong tiếng Việt là “thường xuyên, thường, hay...”, \n=> biểu hiện việc thực hiện thường xuyên một hành vi không mong muốn. \n\n+ 그 나라는 지리적 특성으로 인해 주위 국가로부터 약탈과 침략을 당하기 일쑤였다. \n+ 요즘은 나이가 들어서 그런지 조금 전에 생각했던 일도 금방 잊어버리기 일쑤다. \n+ 아무리 마음이 잘 통하는 사람이라고 해도 일을 하다가 보면 본의 아니게 의견 차이가 나기 일쑤랍니다. \n\nA : 역사 은 같은 사건에 대해 써 놓은 책인데 왜 나라마다 내용이 다를까요? \nB : 역사라는 것은 그 자체가 지극히 주관적인 것이기 때문에 자국의 입장과 이익에 따라 달리 해석되지요. 경우에 따라서는 왜곡되기도 일쑤고요. \n\nA : 요즘 수빈 씨가 어디에 정신이 팔려 있는지 툭하면 실수하기 일쑤예요. \nB : 차라리 조용히 불러서 수빈 씨와 이야기를 해 보는 게 어떨까요?"}, {"id": "E321", "book": "6", "lesson": "6.10", "topic": "한국의 역사", "vocabulary": "전쟁", "grammar": "V(ㄴ/는)/A다는 점에서", "note": "- Gắn sau động từ, tính từ, danh từ, \n- có nghĩa tương đương trong tiếng Việt là “với đặc trưng, về điểm...”, \n=> dùng khi nói lên một đặc trưng hay một sự thật nào đó ở mệnh đề trước và ở mệnh đề sau thì đưa ra kết luận hoặc đánh giá về điều đó. \n\n+ 창덕궁은 조선 시대의 궁궐로서 무엇보다 그 원형이 거의 그대로 남아 있다는 점에서 문화유산으로서의 가치가 크다. \n+ 이 수술법은 수술 후에도 외관상 흉터가 남지 않는다는 점에서 여성들에게 인기가 많 은데비용이좀비싼점이흠이다. \n+ 한글은 독창적이고 과학적인 문자 체계를 갖고 있다는 점에서 여러 언어학자들로 하 여금높은평가를받고있다. \n\nA  인간과 동물의 가장 큰 차이점이 뭐라고 생각하십니까? \nB  글쎄요, 아무래도 인간의 가장 큰 특징으로는 사고와 언어를 꼽을 수 있을 테니 바로 그런 점에서 동물과 구별되지 않을까요? \n\nA  과학적 근거가 없는 샤머니즘에 대한 저의 관점은 상당히 회의적입니다. \nB  그러나 세계사 속에서도 쉽게 찾아 볼 수 있듯 불확실한 미래, 불안한 현실에 진정 제 역할을 해 줬다는 점에서 샤머니즘의 긍정적인 측면도 살펴 볼 수있어요."}, {"id": "E322", "book": "6", "lesson": "6.10", "topic": "한국의 역사", "vocabulary": "역사적 사건", "grammar": "N(으)로 말미암아", "note": "- Gắn sau danh từ, có nghĩa tương đương trong tiếng Việt là “vì, do...”, \n=> dùng để thể hiện nguyên nhân hay lý do của sự vật hay một hiện tượng nào đó ở mệnh đề trước làm xuất hiện một kết quả không tốt xảy ra ở mệnh đề sau. \n\n+ 그는 대통령 취임 후 여러 개혁을 시도했으나 정계의 부패로 말미암아 인기를 잃고 말 았다. \n+ 그 나라는 잦은 내전으로 말미암아 국토의 2/3 이상이 황폐화 되었고 인구의 1/3 이상 이 난민 신세가 되었다. \n+ 요즘 무분별한 개발로 말미암아 생태계 파괴 현상이 심각하여 UN 등 국제기구에서는 생태계 보존을 주요 의제로 채택하고 있다. \n\nA : 어제 일어난 남동부 지역의 지진 피해 소식 들어 보겠습니다. 이유진 기자, 나와 주 십시오. \nB  네, 이유진입니다. 어제 일어난 지진의 영향으로 말미암아 이곳의 가옥 이십여 채와 도로 일부가 파손되었습니다. 하지만 다행히 인명 피해는 없는 것으로 알려졌습니다. \n\nA  그림자처럼 붙어 다니던 사람들이 이젠 아예 모르는 사람들처럼 지내고 있더군요. \nB  대수롭지않은말한마디로말미암아두사람의사이가멀어질대로멀어진거지요."}, {"id": "E325", "book": "6", "lesson": "6.11", "topic": "현대의 의학", "vocabulary": "진단 및 치료", "grammar": "V/A(으)ㄴ들", "note": "- Kết hợp với động từ và tính từ, biểu hiện nghĩa cho dù nội dung giả định ở vế trước được công nhận thì kết quả xảy ra ở vế sau cũng khác với dự kiến. \n- Tương đương với nghĩa \"cứ cho là....... thì..........\" trong tiếng Việt. \n- Khi kết hợp với danh từ có thể sử dụng ở dạng (이)ᄂ들. \n\n+ 이제 와서 운동을 시작한들 무슨 소용이 있겠어요?\n+ 의학이 발달한들 모든 질병을 극복할 수는 없을 것이다.\n+ 이미 시기를 놓쳐서 지금 치료한들 완치되기는 어려울 거예요. \n\nA : 최근 보건 의료 산업에 대한 관심이 높다면서요? \nB : 맞아요. 하지만 의료 산업에 관심이 높은들 그에 대한 정부의 지원이 부족하다면 의료선진국가로가는길은멀다고할수있겠죠. \n\nA : 요즘은 수술 후유증이 적은 로봇 수술이 다양한 분야에서 시도되고 있대요. \nB : 아무리 로봇 수술이 효과적인들 비용 부담이 크다면 어떤 환자가 좋아하겠어요?"}, {"id": "E326", "book": "6", "lesson": "6.11", "topic": "현대의 의학", "vocabulary": "의료 보험 및 의료 산업", "grammar": "V/A(으)면 몰라도", "note": "- Kết hợp sau động từ và tính từ, tương đương với biểu hiện \"nếu là trường hợp / nếu ... thì chưa biết nhưng ...\", \"nếu ... thì tính sau nhưng ...\" trong tiếng Việt. \n- Thường được dùng trong trường hợp tình huống ở vế sau có khả năng thực hiện khi giả định một tình huống không xảy ra hoặc trái ngược với tình huống hiện tại. \n- Khi kết hợp với danh từ, có thể sử dụng dạng (이)면 몰라도. \n- Vì đây là cấu trúc biểu hiện nghĩa giả định nên có thể sử dụng được cả ở dạng -는다면 몰라도 nhưng lúc này ý nghĩa giả định mạnh hơn nên việc hiện thực hóa tình huống ở vế sau càng khó khăn hơn. \n\n+ 몸에 이상이 있으면 몰라도 병원에 가고 싶지 않아.\n+ 위중한 상태면 몰라도 가벼운 증상은 우선 개인병원으로 가세요.\n+ 건강 보험이 적용되면 몰라도 그렇지 않다면 의료비 부담이 클 거예요. \n\nA : 규칙적으로 운동을 하면 몰라도 그렇게 게을러서 어떻게 다이어트를 한다는 거야? \nB : 채식 위주로 식생활 습관을 바꾸면 다이어트도 되고 인체 면역력도 높아져서 일석 이조래. 그래서 오늘부터 채소만 먹을 거야. \n\nA : 요즘 미용 성형에 대해서 알아보고 있는데 가격이 만만치 않아서 고민이야. \nB : 미용성형? 얼굴에 무슨 문제가 있으면 몰라도 단지 미용을 목적으로 성형을 하겠 다는거야?다시한번잘생각해봐."}, {"id": "E327", "book": "6", "lesson": "6.11", "topic": "현대의 의학", "vocabulary": "의학 분야", "grammar": "V/A길래", "note": "- Kết hợp sau động từ và tính từ, được sử dụng khi biểu hiện nguyên nhân, lý do hoặc cơ sở cho hành động của vế sau. \n- Khi kết hợp với danh từ, có thể kết hợp với dạng (이)길래. \n- Vế sau của câu không được sử dụng với dạng câu mệnh lệnh hoặc thỉnh dụ. \n- Cấu trúc này chủ yếu thường được sử dụng trong văn nói, trong văn viết thường dùng ở dạng -기에. \n- Nghĩa tiếng Việt là: “vì .....nên”, “gì.....mà”, “nào.....mà”. \n\n+ 어제부터 감기 기운이 있길래 병원에 갔다 왔지.\n+ 동의보감은 어떤 책이길래 현대 의학에서도 주목을 받고 있을까? \n+ 현대사회에서 성인병 발병률이 어느 정도길래 사회문제로도 대두되는 걸까요? \n\nA : 요즘 안색이 안 좋은데 무슨 일 있어? \nB : 사실 얼마 전부터 허리가 좀 안 좋길래 병원에 갔더니 증상이 좀 더 심해지면 수술 해야 한다고 해서 그래. \n\nA : 사상의학이 뭐길래 사람들이 그렇게 관심을 갖는 거야? \nB : 사상의학은 사람을 체질에 따라서 네 가지로 분류하고 각 체질에 맞는 음식이나 약을 알려주는 생활 속 의학이라고 보면 이해하기 쉽지."}, {"id": "E328", "book": "6", "lesson": "6.11", "topic": "현대의 의학", "vocabulary": "의료윤리", "grammar": "V/A기나 하면", "note": "- Kết hợp sau động từ và tính từ, biểu hiện nghĩa nuối tiếc, đáng tiếc vì khó có thể kỳ vọng, mong đợi vào một việc gì đó mặc dù đó chỉ là điều nhỏ nhất. \n- Tương đương với nghĩa tiếng Việt là “chỉ cần ... thôi thì ...”, “ít nhất là nếu ... thì ...”. \n- Được sử dụng nhiều khi người nói ở trạng thái mong mỏi việc gì đó. \n- Được sử dụng ở dạng (이)기나 하면 khi kết hợp sau danh từ. \n\n+ 건강검진 비용이 싸기나 하면 한 번 받아 보라고 할 텐데.......\n+ 수술 후 재발률이 낮기나 하면 시도라도 할 텐데.......\n+ 식습관이 좋기나 하면 다행이지만 그렇지 않기 때문에 건강이 염려된다. \n\nA : 최근 존엄사에 대한 논란이 계속되고 있는데, 네 생각은 어때? \nB : 내가 생각하기에는 연명 치료를 계속해서 환자가 조금이라도 호전되기나 하면 다행이겠지만, 그렇지 않다면 존엄사를 인정해 줘야 할 것 같아. \n\nA : 이번 해외 의료봉사단 모집에 같이 지원해 볼래? \nB : 봉사 기간이 짧기나 하면 괜찮은데 우리나라도 아닌 다른 곳에서 1년 동안 생활해 야한다니까 난 엄두가 안 나."}, {"id": "E329", "book": "6", "lesson": "6.12", "topic": "인간과 자연", "vocabulary": "지방 구분", "grammar": "V(으)나 마나", "note": "- Gắn vào sau động từ, có nghĩa tương đương trong tiếng Việt là 'có cũng như không, dù có làm cũng như không'\n=> thể hiện một việc vô ích hoặc sự không cần thiết phải làm hành vi nào đó vì dù có làm hay không cũng không có gì khác nhau. \n\n+ 더운 지방은 보나 마나 온돌보다 마루가 발달하지 않았을까요? \n+ 울릉도는 겨울에 눈이 하도 많이 와서 눈을 치우나 마나예요. \n+ 다른 사람의 보고서를 베끼는 숙제는 하나 마나예요. \n\nA : 제주도 집의 특징에 대해 아세요? \nB : 제주도는 아무래도 바람이 많이 부니까 확인해 보나 마나 담이 발달했을 거예요. \n \nA :영화표 예매를 깜빡 했는데 오늘 저녁에 극장에 가면 그 영화를 볼 수 있을까요?\nB : 그 영화는 요즘 인기가 많아서 극장에 가나 마나 표가 없을 거예요. 다음에 봅시다. \n\nCó nhiều trường hợp kết hợp với động từ bổ trợ thể hiện sự thử nghiệm và dùng theo thói quen. \n예) \n전화해 보나 마나 이미 출발했을 거예요. \n물어 보나 마나 뻔해."}, {"id": "E330", "book": "6", "lesson": "6.12", "topic": "인간과 자연", "vocabulary": "지형 특성", "grammar": "V/A건마는", "note": "- Gắn vào sau động từ và tính từ, có nghĩa tương đương trong tiếng Việt là 'thế nhưng, nhưng mà' \n=> thể hiện sự xuất hiện của một sự kiện hay động tác nào đó ngược lại với những điều mong đợi hay lý giải từ một sự thật của mệnh đề trước đó. \n\n+ 겨울에 눈이 오는 것은 당연한 일이건마는 올해는 예년보다 눈이 자주 내리는 것같아 힘드네요. \n+ 할 일은 많건마는 일이 손에 잡히지 않아 큰일이에요.\n+ 이제는 부모님 마음을 이해할 만도 하건마는 아직도 철없는 행동을 하네요. \n\nA  이 지역에 조력 발전소가 들어온다는 것이 사실입니까? \nB  물론 이 지역이 조수간만의 차가 크건마는 갯벌을 훼손할 수 있어 발전소가 세워지는 것은 당분간 어려울 것 같습니다. \n\nA  앞으로의 계획이 있으시면 한 말씀 해 주시죠. \nB  어렸을 때는 꿈이 많았건마는 이제는 그 꿈도 다 사라졌습니다. 그저 사회에 봉사하 며 살고 싶은 마음뿐입니다."}, {"id": "E331", "book": "6", "lesson": "6.12", "topic": "인간과 자연", "vocabulary": "기후", "grammar": "N(은/는) 고사하고", "note": "- Gắn vào sau danh từ, có nghĩa tương đương trong tiếng Việt là ‘nói gì đến..’, \n- có thể dùng thay thế với 은/는커녕, \n=> thể hiện ý ‘không cần nói điều ở mệnh đề trước thì hành vi sau cũng khó khăn hoặc không thể thực hiện’. \n\n+ 이 지역은 강수량이 적어 이모작은 고사하고 일모작도 쉽지 않습니다.\n+ 임진강 하류 지역은 천연기념물인 철새들의 안식처인데 보호는 고사하고 오히려 자연을훼손시키고있어큰문제가되고있다.\n+ 이번 올림픽경기에서는 메달은 고사하고 본선에도 진출하지 못했다. \n\nA : 이 지역에 섬유산업이 발전한 이유가 무엇이라고 생각하십니까? \nB : 우리 지역은 원래 벼농사는 고사하고 보리농사도 어려운 지역이었습니다. 그 점을 극복하기 위해 노력하다 보니 풍부한 노동력과 풍부한 용수를 바탕으로 섬유 산업 이 발전한 것이지요. \n\nA : 올해도 업계 1등을 차지한 비결이 무엇인지 말씀해 주시지요. \nB : 기업의 경쟁력을 높이지 않으면 업계의 1등은 고사하고, 2등에서 3등, 4등으로 계속 뒤쳐질 수밖에 없습니다. 늘 노력하는 자세가 중요하다고 봅니다."}, {"id": "E332", "book": "6", "lesson": "6.12", "topic": "인간과 자연", "vocabulary": "풍수", "grammar": "V/A거니와", "note": "- Gắn vào sau động từ hay tính từ, \n- có nghĩa tương đương trong tiếng Việt là ‘... thêm vào đó’, có nghĩa là ‘vừa công nhận nội dung phía trước và vừa công nhận sự thật cộng thêm ở phía sau.’, \n=> thể hiện ý 은/는 물론이고 이에 더 나아가, -기도 하고 또한 더욱이, thường dùng trong văn viết và ít dùng trong tiếng Hàn hiện đại. \n\n+ 대구는 분지라서 여름은 무덥거니와 겨울은 매우 추워서 기온의 연교차가 심하다. \n+ 갈매기들이 이곳을 찾는 것은 날씨가 따뜻하기도 하거니와 인근 바다에 먹잇감이 풍부하기 때문이다.\n+ 속담은 뜻이 분명한 것은 물론이거니와 간결하기도 하여 외우기 쉽다. \n\nA : 지붕을 풀로 만들면 어떤 장점이 있습니까? \nB : 여름에는 집이 서늘하거니와 겨울에는 열 손실을 막아주는 보온 효과가 있습니다. \n\nA : 이 마을에 사시는 분들은 대부분은 나이보다 훨씬 젊어 보이시네요. \nB : 공기 좋고 공해 없는 환경 속에서 살기 때문이기도 하거니와 산에서 내려오는 약수의 효능이 정말 뛰어나서 그런 것 같아요. \n\nCó khi còn sử dụng trong trường hợp giải thích lại nội dung liên quan phía sau. Ý nghĩa như -는데. \n예) \n거듭 말하거니와 다시는 이런 비극이 없어야 합니다. \n다시 덧붙이거니와 열심히 해 주시기 바랍니다. \n다시 한번 강조하거니와 늦지 않도록 하세요."}, {"id": "E334", "book": "6", "lesson": "6.13", "topic": "정보와 통신", "vocabulary": "정보 통신 유형", "grammar": "V/A(으)ㄹ 줄이야", "note": "- Kết hợp sau động từ, tính từ chỉ một tình huống hoặc một trạng thái không thể lường trước được. \n- Cấu trúc này thường dùng khi nói về một việc ngoài dự kiến hoặc một tình huống mà người nói ngạc nhiên, bối rối. \n- Cấu trúc này tương đương với biểu hiện \"không ngờ là ..., ai mà biết được là ..., biết đâu được là ...\" trong tiếng Việt. \n- Khi kết hợp với danh từ hoặc đại từ, được dùng ở dạng 일 줄이야. \n\n+ 시골에서도 이렇게 인터넷이 빠를 줄이야. \n+ 컴퓨터를 사러 전자 상가에 갔는데 그렇게 일찍 문을 닫을 줄이야.\n+ 병원 건물이 지하철역에서 보여서 걸어갔더니 20분이나 걸렸다. 이렇게 멀 줄이야. \n\nA : 요즘 운전면허 시험 보려고 운전 연습하고 있다고 하던데, 운전은 좀 늘었어? \nB : 아니, 아직도 30km 이상 속도가 나면 어지럽고 무서워. 내가 겁이 많아서 쉽지는 않을 거라고 예상은 했지만 이렇게 어려울 줄이야. \n\nA : 지난달부터 인터넷 쇼핑몰을 인수해서 운영하고 있는데 정말 골치가 아파. 장사가 잘된다고해서인수한건데이렇게장사가안될줄이야. \nB : 좀 더 잘 생각해 보고 인수하지 그랬어? 그래도 아직 시작한 지 얼마 안 됐으니까 좀 더 열심히 해 봐."}, {"id": "E335", "book": "6", "lesson": "6.13", "topic": "정보와 통신", "vocabulary": "정보 통신 기술 용어", "grammar": "V/A기 마련이다", "note": "- Kết hợp sau động từ, tính từ biểu hiện nghĩa một việc nào đó hoặc một trạng thái nào đó xảy ra là đương nhiên. \n- Cấu trúc này tương đương với biểu hiện \"chắc chắn là ..., đương nhiên là ...\" trong tiếng Việt. \n- Cấu trúc này cũng có thể dùng ở dạng -게 마련이다. \n\n+ 어려서부터 온라인 게임에 중독된 사람은 사회성이 부족하기 마련이야.\n+ 한국 사람과 인터넷으로 채팅을 하다 보면 한국어 타자가 늘기 마련이에요. \n+ 아무리 성격이 긍정적인 사람이라도 큰 병에 걸리면 마음이 약해지기 마련이다. \n\nA : 날씨가 참 화창하네요. 오랜만에 이불 빨래나 해서 널어 놓아야겠어요. \nB : 아까 지나가다가 땅을 보니 개미들이 부지런히 개미집 입구를 흙으로 막고 있더라고요. 이런날엔비가오기마련이니빨래는다음에하는게낫겠어요. \n\nA : 엄마, 지금 홈쇼핑에서 화장품 세트가 나오는데 오늘 사면 한 세트 더 준대요. 다시 는 이 가격에 못 살 거 같은데요. \nB : 아직 화장품 많이 남아 있잖아. 저렇게 헐값으로 팔고 나면 곧 신상품이 나오기 마련이니까 좀 참고 기다려 봐."}, {"id": "E336", "book": "6", "lesson": "6.13", "topic": "정보와 통신", "vocabulary": "유비쿼터스 서비스", "grammar": "V(으)ㄹ래야 + V(으)ㄹ 수 없다", "note": "- Kết hợp sau động từ biểu hiện nghĩa mặc dù có ý định thực hiện một việc gì đó nhưng có tình huống ngược lại với ý định đó xảy ra nên cuối cùng không thực hiện được ý định ban đầu. \n- Tương đương với nghĩa “có muốn ... thế nào đi nữa cũng không thể ..., có bảo ... cũng không thể ...” trong tiếng Việt. \n\n+ 인터넷 사기를 너무 많이 당해서 이제는 인터넷 사이트를 믿을래야 믿을 수 없다.\n+ 내 친구 집 대문 앞에는 크고 무서운 개가 두 마리나 있어서 들어갈래야 들어갈 수 없다. \n+ 학교 앞 분식집에서 파는 떡볶이는 너무 맛있어서 지나갈 때마다 사먹지 않을래야 않 을수없다. \n\nA : 어? 담배 끊은 줄 알았는데 다시 피우는 거야? \nB : 응. 이번에는 꼭 끊기로 다짐했는데 오랫동안 피워서 그런지 끊을래야 끊을 수 없네. \n\nA : 남자 친구가 생일 선물로 사준 예쁜 머리핀을 해변에서 잃어버렸는데 아무리 살펴 봐도 찾을래야 찾을 수가 없어. 어떡하지? \nB : 사람이 별로 없는 해변이니까 잘 찾아 보면 찾을 수 있을 거야. 나랑 같이 가서 다시 한번 찾아보자."}, {"id": "E337", "book": "6", "lesson": "6.13", "topic": "정보와 통신", "vocabulary": "정보 통신 윤리", "grammar": "N도 + V/A(으)려니와", "note": "- Kết hợp sau động từ, tính từ, thể hiện nghĩa công nhận nội dung ở vế trước đồng thời thêm thông tin ở vế sau. \n- Cấu trúc này thường được dùng trong trường hợp đã có một sự thật ở vế trước lại cộng thêm một sự thật khác được giải thích ở vế sau . \n- Khi kết hợp với danh từ và đại từ, nó hoạt động ở dạng (이)려니와. \n- Tương đương với nghĩa “đã ... thêm vào đó lại ... nên ...” trong tiếng Việt. \n\n+ 인터넷으로 제품을 구입하면 가격도 싸려니와 다양한 물건을 쉽게 비교해 볼 수 있어 서 좋다. \n+ 김 선생님은 얼굴도 예쁘시려니와 마음씨까지 고우셔서 학생들에게 인기가 많아요. \n+ 우리 집 강아지는 밥도 잘 먹으려니와 매일 한 시간씩 운동을 하기 때문에 아주 건강해요. \n\nA : 인터넷에 루머를 퍼뜨린 사람이 사이버 수사대에 발각되어 구속되었다고 하네요. \nB : 결국 잡혔군요. 그 악성 루머 때문에 사업이 망한 당사자는 돈도 돈이려니와 정신적 충격으로 엄청나게 고생했다고 들었어요. \n\nA : 이번 로봇 경진 대회에서 우리 반 학생들이 우승을 차지했어요. 큰 박수로 축하해 줍시다. 대표로 민수가 소감을 발표할까요? \nB : 감사합니다. 이번 대회에서 우승한 것은 운도 좋았으려니와 팀원이 하나가 되어 열 심히 노력했기 때문에 가능했던 것 같아요."}, {"id": "E340", "book": "6", "lesson": "6.14", "topic": "현대 사회의 문제", "vocabulary": "실업", "grammar": "N(을/를) 막론하고", "note": "- Gắn vào sau danh từ, \n- có nghĩa tương đương trong tiếng Việt là “không kể...”, “bất chấp...”, \n=> dùng khi không tính toán hoặc kén chọn việc này việc kia. Đây là dạng biểu hiện kết hợp sử dụng tiểu từ 을/를 và dạng ứng dụng 막론하고 của động từ 막론하다. \n\n+ 지위의 높고 낮음을 막론하고 부정부패를 없애야 한다. \n+ 현대사회에서는 남녀노소를 막론하고 스트레스를 받는다. \n+ 나는 범죄를 저지르면 이유를 막론하고 법에 따라 다스린다. \n\nA : 이번에 여행 다녀온 나라는 어땠어요? 비자 문제는 없었나요? \nB : 네, 다행히 그 나라는 여행객의 국적을 막론하고 입출국이 자유로운 나라였어요. \n\nA : 요즘 성형수술을 위해 한국에 오는 해외 관광객이 늘었다고 신문에 났더라고요. \nB : 동서고금을 막론하고 모든 사람들은 미에 관심이 많으니까요."}, {"id": "E341", "book": "6", "lesson": "6.14", "topic": "현대 사회의 문제", "vocabulary": "범죄", "grammar": "V/A(으)리라", "note": "- Gắn vào sau động từ hoặc tính từ, \n- có nghĩa tương đương trong tiếng Việt là “định là sẽ...”, “chắc là sẽ...”, \n=> thể hiện ý định hoặc dự đoán của người nói. \n\n+ 올해에는 꼭 취업하리라.\n+ 그 문제는 보기에 심각하지 않으리라 생각되었다.\n+ 나이가 들어 생각이 많아지니 그저 앞만 보고 살아가리라 생각하던 시절이 그리웠다. \n\nA : 고향에는 자주 가나요? \nB : 아니요, 3년 전에 시집와서 매년 고향에 가리라 생각은 하지만 2년 동안 못 갔어요. \n\nA : 요즘 비정규직 보호법을 위한 시위 활동을 한다고 들었어요. \nB : 네, 한국은 지금 비정규직 문제로 힘들어 하는 사람들이 많거든요. 그래서 옛날부터 그들을 위해 힘닿는 데까지 도우리라 다짐했었어요."}, {"id": "E342", "book": "6", "lesson": "6.14", "topic": "현대 사회의 문제", "vocabulary": "사회 구조와 갈등", "grammar": "V아/어 봤자", "note": "- Gắn vào sau động từ, \n- có nghĩa tương đương trong tiếng Việt là “cho dù là...”, \n- thể hiện ý ‘cho dù cho là cố gắng như thế đi nữa.’ \n\n+ 아무리 성적이 좋아 봤자 영어를 못하면 한국에서는 취업하기 힘들다. \n+ 전화를 하고 이메일을 보내 봤자 그 분은 절대로 연락을 받지 않을 거예요. \n+ 아동 복지 시설이 늘어나 봤자 아동 문제를 위한 근본적인 대책이 없으면 해결되지 않을 것이다. \n\nA : 요즘 사교육비가 전체 가계비에서 50% 이상을 차지한대요. \nB : 지나치게 높은 교육열도 문제예요. 국가에서 공교육을 강화한다고 해 봤자 사교육 비는절대줄지않을거예요. \n\nA : 우리나라 대학 등록금은 터무니없이 비싸요. 대학 등록금을 내릴 때까지 국회 앞에 서1인시위를할거예요. \nB : 이렇게 1인 시위를 해 봤자 소용없어요. 더 적극적인 대안이 필요해요."}, {"id": "E343", "book": "6", "lesson": "6.14", "topic": "현대 사회의 문제", "vocabulary": "사회 문제와 해결 노력", "grammar": "V/A(으)ㄹ망정", "note": "- Gắn vào sau động từ hoặc tính từ, \n- có nghĩa tương đương trong tiếng Việt là “cho dù ... nhưng ...”, “thà là ... chứ ...” \n=> dùng khi nhấn mạnh sự thật như thế nào đó trong vế sau hoàn toàn khác với suy nghĩ thông thường mặc cho sự thật ở câu vế trước. \nNgoài ra, cấu trúc này đứng sau động từ, còn được sử dụng khi muốn nhấn mạnh sự vững vàng không lay chuyển được của nội dung trong vế sau cho dù tình hình có tiêu cực thế nào đi nữa. \n\n+ 혼자 사는 게 불편할망정 결혼을 하지는 않겠다.\n+ 나는 가난하게 살망정 불법적으로 돈을 벌진 않겠다.\n+ 우리 회사는 작은 회사일망정 비정규직 보호법을 준수하는 기업이다. \n\nA : 결혼할 나이가 다 되었는데 좋은 소식 없어요? \nB : 전 결혼에 관심 없어요. 평생 혼자 살망정 아무하고나 결혼하지는 않을 거예요. \n\nA : 이번 시험은 정말 어려울 거라고 하던데....... 무슨 좋은 방법 없을까요? \nB : 시험은 자기 실력으로 보는 거예요. 저는 시험을 못 볼망정 부정행위는 절대 하지 않겠어요."}, {"id": "E344", "book": "6", "lesson": "6.15", "topic": "취업과 직장 생활", "vocabulary": "구직", "grammar": "V기 나름이다", "note": "- Có thể dịch tương đương trong tiếng Việt là 'tùy vào sự/ việc__', \n- gắn vào sau động từ, thể hiện ý nghĩa một việc hay một hành vi nào đó có thể thay đổi tùy theo việc thực hiện công việc hay hành vi đó như thế nào. \n\n+ 요즘 취직하기가 힘들다고 하지만 취직은 준비하기 나름이에요.\n+ 자신의 삶에 대하여 비관적인 사람이 많은데 행복은 생각하기 나름이에요. \n+ 한때 한국 텔레비전에서는 ‘남자는 여자 하기 나름이다’라는 말이 유행했었다. \n\nA : 비싼 카메라인데 너무 자주 망가져요. \nB : 그래요? 카메라를 조심하지 않고 사용하신 것 같아요. 아무리 좋은 것이라도 사용하기 나름이에요. \n\nA : 이 분야의 일은 월급에 비해 업무량이 많다고 들었어요. 정말 그런가요? \nB : 글쎄요. 일하기 나름인 것 같아요. 때때로 업무량이 많기는 하지만\n업무 성과에 따라 성과급이 주어지기 때문에 월급이 다른 분야보다 결코 적지 않아요."}, {"id": "E345", "book": "6", "lesson": "6.15", "topic": "취업과 직장 생활", "vocabulary": "근무와 업무", "grammar": "V는 김에", "note": "- Có thể dịch tương đương trong tiếng Việt là 'nhân tiện, vào dịp __', \n- gắn vào sau động từ, thể hiện ý nghĩa nhân dịp trong lúc làm một hành vi nào đó thì thực hiện luôn một việc có liên quan mà vốn không dự định trước. \n- Cấu trúc -는 김에 được dùng đa dạng với các loại câu như câu trần thuật, câu hỏi, câu cầu khiến, câu mệnh lệnh. \n\n+ 언론사에서 인턴을 하는 김에 언론사 취업 노하우를 배워야겠어요. + 늦은 나이에 어렵게 공부를 다시 시작한 김에 다른 것들도 많이 배워보고 싶어요. \n+ 미국으로 장기 출장을 가는 김에 주말에 캐나다에 잠깐 들러 친구를 만날까 해요. \n\nA : 오늘 흐엉 씨를 오랜만에 만나는 김에 저녁도 같이 먹어야겠어요. \nB : 네, 흐엉 씨 시간이 괜찮다면 그렇게 하세요. \n\nA : 흐엉 씨, 드디어 원하는 일을 하게 되었다면서요?\nB : 네, 힘들게 원하는 일을 하게 된 김에 더 노력해서 이 분야의 전문가가 되고 싶어요. \n\nSo sánh -는 김에 với -는 길에\n-는 김에thể hiện nhân dịp làm một hành vi nào đó mà làm cùng thêm một việc khác, còn -는 길에thì thể hiện nhân lúc đi tới địa điểm nào đó thì thực hiện thêm một việc khác. \n예) \n이번에 영어를 배우는 김에 중국어도 좀 배워야겠어요. (○)\n이번에 영어를 배우는 길에 중국어도 좀 배워야겠어요. (×)\n친구를 만나러 명동에 가는 김에 옷을 한 벌 사 가지고 오려고 해요. (○) \n친구를 만나러 명동에 가는 길에 옷 가게에 들러서 옷을 먼저 사려고 해요. (○)"}, {"id": "E346", "book": "6", "lesson": "6.15", "topic": "취업과 직장 생활", "vocabulary": "미래와 유망 직종", "grammar": "V는 둥 마는 둥", "note": "- Có thể dịch tương đương trong tiếng Việt là 'làm cũng như không làm, làm sơ sài, không làm gì cả, làm qua loa, làm cho có ', \n- gắn vào sau động từ, thể hiện ý nghĩa không làm chăm chỉ hoặc hoàn toàn không làm một hành vi nào đó. \n- Khi diễn đạt tình huống ở qúa khứ thì dùng -은 둥 만 둥 và tình huống ở tương lai thì dùng -을 둥 말 둥. \n\n+ 뚜안 씨는 요즘 가족에 대한 그리움 때문에 회사 일을 하는 둥 마는 둥 해요. \n+ 아침에 늦게 일어나서 밥을 먹는 둥 마는 둥 하고 집을 나오는 사람이 많아요. \n+ 밤새 보고서를 쓰느라고 잠을 자는 둥 마는 둥 했더니 의자에 앉기만 하면 졸음이 오네요. \n\nA : 사람들은 토요일에 회사에 출근해서 보통 어떤 일을 해요? \nB : 글쎄요. 우리 회사는 토요일에 출근을 하긴 하지만 다들 일을 하는 둥 마는 둥 하는 것 같아요. \n\nA : 점심 식사를 못 하셨나 봐요. \nB : 네, 부산으로 가는 비행기를 놓칠까 봐 오늘 점심은 거의 먹는 둥 마는 둥 했어요."}, {"id": "E347", "book": "6", "lesson": "6.15", "topic": "취업과 직장 생활", "vocabulary": "취업 전략", "grammar": "A(으)ㄴ/V는걸요", "note": "- Có thể dịch tương đương trong tiếng Việt là 'có lẽ, chắc là _', \n- gắn vào sau động từ và tính từ, thể hiện ý nghĩa người nói nêu lên một sự thật mới biết nào đó hoặc suy nghĩ hay cảm xúc của bản thân. \n- Tuy nhiên, thỉnh thoảng cấu trúc này cũng được dùng để nêu thêm căn cứ bổ sung mạnh mẽ cho điều được nêu ra trước đó, \n- có thể dịch tương đương trong tiếng Việt là 'cơ đấy, đấy chứ' \n\n+ 오늘 오후까지 그 일을 다 끝내는 것은 힘들겠는걸요. \n+ 남 씨가 일을 하는 걸 보니 이젠 아무도 못 따라오겠는걸요. \n+ 제가 한국어능력시험에서 5급을 받은 건 우연이 아니에요. 날마다 세 시간씩 한국어를 공부한걸요. \n\nA : 요즘 회사 매출이 줄어서 야단이에요. \nB : 그러면 이번 추석에 보너스 받는 것을 포기해야겠는걸요. \n\nA : 흐엉 씨는 한국인이 다 된 것같아요.\nB : 네, 한국에 산 지 벌써 7년이나 된걸요. 그 정도면 한국 사람이나 다름없게 되지요."}]};
